# -*- coding: utf-8 -*-
"""translations_hi.py — Hindi literal + paraphrase translations for Gita verses.
Keyed by "ch.verse" (e.g. "1.01"). Missing entries fall back to English.
Filled chapter by chapter."""

TRANS_HI = {
"1.01": ("धृतराष्ट्र ने कहा: धर्मक्षेत्र कुरुक्षेत्र में, युद्ध के लिए उत्सुक होकर एकत्र हुए — मेरे लोग और पांडु के पुत्र — उन्होंने क्या किया, हे संजय?",
         "राजा धृतराष्ट्र पूछते हैं: “कुरुक्षेत्र के पवित्र मैदान पर मेरे पुत्र और पांडु के पुत्र लड़ने को तैयार होकर इकट्ठे हुए हैं। संजय, बताओ — क्या हुआ?”"),
"1.02": ("संजय ने कहा: पांडव सेना को युद्ध-व्यूह में सजा देखकर, दुर्योधन तब अपने गुरु के पास जाकर ये वचन बोला, हे राजन्।",
         "संजय उत्तर देते हैं: “पांडवों की सेना को व्यूह में खड़ा देखकर दुर्योधन अपने गुरु द्रोण के पास गया और बोला, हे राजा…”"),
"1.03": ("देखिए, हे गुरु, पांडु पुत्रों की यह महान सेना, द्रुपद के पुत्र — आपके ही विद्वान् शिष्य — ने युद्ध के लिए सजाई है।",
         "“देखिए, गुरुजी — पांडु पुत्रों की यह विशाल सेना, आपके ही चतुर शिष्य द्रुपदपुत्र धृष्टद्युम्न ने व्यूहबद्ध की है।”"),
"1.04": ("यहाँ वीर हैं, महान धनुर्धारी, युद्ध में भीम और अर्जुन के समान: युयुधान, विराट, और महारथी द्रुपद।",
         "“उनकी पंक्ति में भीम और अर्जुन की बराबरी करने वाले वीर और धनुर्धारी हैं: युयुधान, राजा विराट, और महान योद्धा द्रुपद।”"),
"1.05": ("और धृष्टकेतु, चेकितान, वीर्यवान् काशी का राजा, पुरुजित्, कुंतिभोज, और मनुष्यों में श्रेष्ठ शैब्य।",
         "“और वहाँ भी: धृष्टकेतु, चेकितान, वीर काशीराज, पुरुजित्, कुंतिभोज, और अतुलनीय शैब्य।”"),
"1.06": ("पराक्रमी युधामन्यु और वीर्यवान् उत्तमौजा, सुभद्रा का पुत्र, और द्रौपदी के पुत्र — सब महारथी।",
         "“निडर युधामन्यु, बलशाली उत्तमौजा, सुभद्रा-पुत्र अभिमन्यु, और द्रौपदी के पाँच पुत्र — सब रथकला में निपुण।”"),
"1.07": ("पर जानिए, हे द्विजश्रेष्ठ, जो हमारी ओर विशिष्ट हैं — मेरी सेना के नायक; आपकी जानकारी के लिए उनका नाम बताता हूँ।",
         "“पर, हे गुरुवर, हमारी ओर जो प्रमुख हैं — मेरी सेना के कमांडर — उनके नाम बताता हूँ, ताकि आप जानें कि हमें कौन आगे बढ़ाता है।”"),
"1.08": ("आप स्वयं, भीष्म, कर्ण, युद्ध में विजयी कृप, अश्वत्थामा, विकर्ण, और सोमदत्त का पुत्र भी।",
         "“आप, मेरे गुरु; और भीष्म, कर्ण, युद्धविजयी कृप, अश्वत्थामा, विकर्ण, और सोमदत्त-पुत्र — सब युद्ध में अपराजित।”"),
"1.09": ("और अनेक अन्य वीर, मेरे लिए प्राण त्यागने को तैयार, विविध शस्त्र धारण किए, सब युद्ध में निपुण।",
         "“हमारे साथ और भी वीर हैं, मेरे लिए मरने को तैयार, हर प्रकार के शस्त्र चलाने वाले — सब युद्ध में पारंगत।”"),
"1.10": ("हमारी वह शक्ति, भीष्म से रक्षित होकर भी, अपर्याप्त है; उनकी यह शक्ति, भीम से रक्षित, पर्याप्त है।",
         "“भीष्म से सुरक्षित होकर भी हमारी सेना पर्याप्त नहीं; भीम से रक्षित उनकी सेना अधिक है।”"),
"1.11": ("सब मोर्चों पर खड़े होकर, अपने-अपने विभाग में स्थान लो — और सबसे बढ़कर, सब मिलकर भीष्म की ही रक्षा करो।",
         "“हर मोर्चे पर अपना-अपना स्थान लो — और तुम सबको विशेष रूप से भीष्म की रक्षा करनी है।”"),
"1.12": ("उन्हें हर्षित करने के लिए, कुरुवंश के पितामह, तेजस्वी भीष्म ने सिंहनाद किया और ऊँचे स्वर में शंख बजाया।",
         "दुर्योधन का उत्साह बढ़ाने के लिए वृद्ध पितामह भीष्म ने सिंह की दहाड़ मारी और पूरे बल से अपना महाशंख बजाया।"),
"1.13": ("तब शंख, नगाड़े, ढोल, मृदंग और तुरहियाँ एक साथ बज उठीं — वह ध्वनि भयानक हो गई।",
         "तुरंत शंख और नगाड़े, ढोल और तुरहियाँ एक साथ बजीं, और कोलाहल विशाल गर्जना में बदल गया।"),
"1.14": ("तब, श्वेत अश्वों से जुते महारथ में खड़े होकर, माधव और पांडु-पुत्र ने अपने दिव्य शंख बजाए।",
         "तब श्वेत घोड़ों से खींचे महारथ पर कृष्ण (माधव) और अर्जुन ने अपने दिव्य शंख फूँके।"),
"1.15": ("हृषीकेश ने पांचजन्य बजाया; धनंजय ने देवदत्त; और महापराक्रमी भीम ने महाशंख पौंड्र।",
         "कृष्ण ने अपना शंख पांचजन्य, अर्जुन ने देवदत्त, और महान पराक्रमी भीम ने विशाल पौंड्र बजाया।"),
"1.16": ("राजा युधिष्ठिर, कुंती-पुत्र, ने अनंतविजय बजाया; नकुल और सहदेव ने सुघोष और मणिपुष्पक।",
         "कुंती-पुत्र राजा युधिष्ठिर ने अनंतविजय बजाया, जबकि नकुल और सहदेव ने अपने शंख सुघोष और मणिपुष्पक फूँके।"),
"1.17": ("और काशी का राजा, श्रेष्ठ धनुर्धारी, महारथी शिखंडी, धृष्टद्युम्न, विराट, और अपराजित सात्यकि।",
         "वैसे ही काशी के महाधनुर्धारी, पराक्रमी शिखंडी, धृष्टद्युम्न, राजा विराट, और कभी न हारने वाले सात्यकि।"),
"1.18": ("द्रुपद और द्रौपदी के पुत्र, हे पृथ्वीपति, और महाबाहु सुभद्रा-पुत्र — सब ने अपने-अपने शंख बजाए।",
         "द्रुपद, द्रौपदी के पुत्र, और बलशाली सुभद्रा-पुत्र — प्रत्येक ने, हे राजा, अपना शंख बजाया।"),
"1.19": ("उस कोलाहल ने धृतराष्ट्र के पुत्रों के हृदय चीर दिए, आकाश और पृथ्वी में गूँजती भयानक ध्वनि से।",
         "बहरा कर देने वाली उस ध्वनि ने धृतराष्ट्र के पुत्रों के हृदय तोड़ दिए और स्वर्ग तथा पृथ्वी दोनों में गूँज उठी।"),
"1.20": ("तब, धार्तराष्ट्रों को व्यूह में खड़ा देखकर, शस्त्र टकराने ही वाले समय, वानर-ध्वज वाले पांडव ने धनुष उठाया।",
         "युद्ध शुरू होते ही, हनुमान-चिह्न वाले ध्वज के नीचे अर्जुन ने शत्रु सेना देखी और अपना धनुष उठा लिया।"),
"1.21": ("हे पृथ्वीपति, तब उन्होंने हृषीकेश से यह वचन कहा: “मेरा रथ दोनों सेनाओं के बीच रखो, हे अच्युत।”",
         "तब, हे राजा, अर्जुन ने कृष्ण से कहा: “मेरा रथ दोनों सेनाओं के बीच रखो, हे अविनाशी प्रभु।”"),
"1.22": ("“ताकि मैं यहाँ युद्ध के लिए उत्सुक खड़े लोगों को देख सकूँ — जिनसे मुझे इस महायुद्ध में लड़ना है।”",
         "“लड़ने आए लोगों को देखूँ, और जानूँ कि इस आने वाले युद्ध में मुझे किसका सामना करना है।”"),
"1.23": ("“मैं युद्ध में लड़ने आए लोगों को देखना चाहता हूँ — जो यहाँ दुष्टबुद्धि धृतराष्ट्र-पुत्र को प्रसन्न करने के लिए एकत्र हुए हैं।”",
         "“मैं यहाँ एकत्र योद्धाओं को देखना चाहता हूँ — जो दुष्ट दुर्योधन को प्रसन्न करने के लिए यह युद्ध करने आए हैं।”"),
"1.24": ("संजय ने कहा: गुडाकेश द्वारा ऐसा कहे जाने पर, हृषीकेश ने, हे भरतवंशी, उस उत्तम रथ को दोनों सेनाओं के बीच रखा।",
         "संजय आगे कहते हैं: “अर्जुन की आज्ञा पाकर, हे धृतराष्ट्र, कृष्ण ने उत्तम रथ को दोनों सेनाओं के मध्य खड़ा किया।”"),
"1.25": ("भीष्म, द्रोण, और पृथ्वी के सब राजाओं के सामने उन्होंने कहा: “हे पार्थ, यहाँ एकत्र हुए इन कुरुओं को देखो।”",
         "भीष्म, द्रोण, और संसार के सब राजाओं के सामने कृष्ण ने कहा: “देखो, अर्जुन — तुम्हारे सामने सम्पूर्ण कुरु वंश एकत्र है।”"),
"1.26": ("वहाँ अर्जुन ने खड़े देखा: पिता, पितामह, गुरु, मामा, भाई, पुत्र, पौत्र, और मित्र भी।",
         "वहाँ, सेनाओं के बीच, अर्जुन ने अपने पिता और पितामह, गुरु और मामा, भाई, पुत्र, पौत्र और मित्र देखे।"),
"1.27": ("दोनों सेनाओं में ससुर और हितैषी — उन सब कुटुंबियों को वहाँ खड़ा देखकर, कुंती-पुत्र…",
         "दोनों ओर ससुर और प्रिय साथी — अर्जुन, कुंती-पुत्र, युद्ध के लिए खड़े अपने सब कुटुंब को देखते हुए…"),
"1.28": ("गहन करुणा से भरकर, शोक करते हुए, उन्होंने कहा — अर्जुन ने कहा: “मेरे इन अपने लोगों को देखकर, हे कृष्ण, यहाँ युद्ध के लिए खड़े…”",
         "गहरी दया से भरकर, शोक में डूबकर अर्जुन ने कहा: “हे कृष्ण, अपने परिवार को अपने सामने लड़ने को तैयार देखकर…”"),
"1.29": ("“मेरे अंग शिथिल होते हैं, मेरा मुँह सूखता है, मेरे शरीर में कंपन होता है, और मेरे रोंगटे खड़े हो जाते हैं।”",
         "“मेरे पैर लड़खड़ाते हैं, मुँह सूख जाता है, सारा शरीर काँपता है, और डर से रोंगटे खड़े हो जाते हैं।”"),
"1.30": ("“गांडीव मेरे हाथ से गिर जाता है, मेरी त्वचा जलती है; मैं खड़ा नहीं रह पाता, और मेरा मन घूम जाता है।”",
         "धनुष हाथ से फिसल रहा है, खाल जल रही है। पैर जमते ही नहीं, और मन जगह पर टिकता ही नहीं।"),
"1.31": ("“और मैं अशुभ शकुन देखता हूँ, हे केशव; और अपने ही कुटुंब को युद्ध में मारने से कोई भलाई भी नहीं देखता।”",
         "“मैं केवल अशुभ शकुन देखता हूँ, कृष्ण — और अपने ही लोगों को युद्ध में मारने से आने वाला कोई भला भी नहीं दिखता।”"),
"1.32": ("“मैं विजय नहीं चाहता, हे कृष्ण, न राज्य, न भोग। हमें राज्य से क्या, हे गोविंद — भोगों से क्या, या जीवन से ही क्या?”",
         "“मुझे विजय नहीं चाहिए, कृष्ण — न राज्य, न सुख। अब हमें राज्य, आनंद या जीवन से ही क्या प्रयोजन, गोविंद?”"),
"1.33": ("“जिनके लिए हम राज्य, भोग और सुख चाहते थे — वे ही यहाँ युद्ध में खड़े हैं, प्राण और धन दोनों त्यागकर।”",
         "“जिनके लिए हम राज्य, आराम और खुशी चाहते थे — वे ही यहाँ अपने प्राण और संपत्ति लुटाने को तैयार खड़े हैं।”"),
"1.34": ("“गुरु, पिता, पुत्र, और वैसे ही पितामह, मामा, ससुर, पौत्र, साला और अन्य संबंधी।”",
         "“मेरे गुरु, पिता, पुत्र और पितामह, मामा और ससुर, पौत्र, साले और सब कुटुंबी — सब यहाँ हैं।”"),
"1.35": ("“मैं उन्हें मारना नहीं चाहता, चाहे वे मुझे ही मारें, हे मधुसूदन — तीनों लोकों के राज्य के लिए भी नहीं, पृथ्वी के लिए तो क्या।”",
         "“मैं उन्हें नहीं मारूँगा, मधुसूदन — चाहे वे मुझे ही मारें। तीनों लोकों के अधिकार के लिए भी नहीं, इस पृथ्वी के लिए तो क्या।”"),
"1.36": ("“धृतराष्ट्र के पुत्रों को मारकर हमें क्या प्रसन्नता होगी, हे जनार्दन? इन आक्रमणकारियों को मारने का पाप ही हमें लगेगा।”",
         "“भले ही हम धृतराष्ट्र के पुत्रों को नष्ट कर दें, जनार्दन, हमें क्या आनंद मिलेगा? इन हत्यारों को मारने का पाप ही हमसे चिपक जाएगा।”"),
"1.37": ("“इसलिए हमें अपने कुटुंबी धृतराष्ट्र-पुत्रों को नहीं मारना चाहिए; क्योंकि अपने ही लोगों को मारकर हम कैसे सुखी हों, हे माधव?”",
         "“इसलिए हमारे लिए अपने परिवार — धृतराष्ट्र के पुत्रों को मारना गलत है। अपने ही कुटुंब की हत्या करके हम कभी सुखी नहीं हो सकते, माधव।”"),
"1.38": ("“यद्यपि ये लोग, जिनके मन लोभ से ग्रस्त हैं, कुल के नाश में दोष नहीं देखते और मित्रों के साथ छल में पाप भी नहीं देखते…”",
         "“सच है, ये लोग — जिनके हृदय लोभ से अंधे हैं — परिवार को तोड़ने में कोई गलती और मित्रों के विश्वासघात में कोई पाप नहीं देखते…”"),
"1.39": ("“पर हम कैसे न जानें — जो कुलविनाश का दोष देखते हैं — कि हमें इस पाप से लौटना चाहिए, हे जनार्दन?”",
         "“पर हम परिवार के नाश से आने वाला विनाश देख सकते हैं — तो हम कैसे इस पाप से पीछे हटने में असफल हो सकते हैं, जनार्दन?”"),
"1.40": ("“कुल के नाश से सनातन कुलधर्म लुप्त होते हैं; और धर्म नष्ट होने पर अधर्म सम्पूर्ण कुल को घेर लेता है।”",
         "“जब परिवार नष्ट होता है, उसकी प्राचीन पवित्र परंपराएँ उसके साथ मर जाती हैं; और एक बार धर्म लुप्त होते ही अधर्म पूरे परिवार पर छा जाता है।”"),
"1.41": ("“अधर्म के उदय से, हे कृष्ण, कुल की स्त्रियाँ भ्रष्ट होती हैं; और भ्रष्ट स्त्रियों से, हे वार्ष्णेय, वर्णसंकर उत्पन्न होता है।”",
         "“जब अधर्म फैलता है, कृष्ण, परिवार की स्त्रियाँ भ्रष्ट होती हैं; और भ्रष्ट स्त्रियों से जातियों और वंशों का मिश्रण होता है।”"),
"1.42": ("“यह संकर कुलघातियों को और कुल को ही नरक की ओर ले जाता है; उनके पितर गिर जाते हैं, पिंड और जल के अर्घ से वंचित होकर।”",
         "“ऐसा मिश्रण परिवार के नाशकों और परिवार दोनों को नरक की ओर खींचता है, और उनके पितर श्राद्ध-क्रिया से वंचित होकर गिर जाते हैं।”"),
"1.43": ("“कुलघातियों के इन दोषों से, जो वर्णसंकर उत्पन्न करते हैं, समाज और कुल के सनातन धर्म नष्ट हो जाते हैं।”",
         "“वर्ण-मिश्रण उत्पन्न करने वाले इन पापों द्वारा जाति और कुल दोनों के शाश्वत धर्म बह जाते हैं।”"),
"1.44": ("“जिनके कुलधर्म नष्ट हो गए हैं, उन मनुष्यों का, हे जनार्दन, नरक में नियत वास बताया गया है — ऐसा हमने सुना है।”",
         "“और, जनार्दन, हमने सुना है कि जिनके पारिवारिक कर्म नष्ट हो जाते हैं, उन्हें नरक में रहना पड़ता है।”"),
"1.45": ("“हाय! हमने कितना बड़ा पाप करने का निश्चय किया है — राज्य और सुख के लोभ से अंधे होकर, हम अपने ही कुटुंब को मारने को तैयार हैं।”",
         "“हम कितना भयानक अन्याय करने जा रहे हैं! राजगद्दी और सुख की लालसा से अंधे होकर, हम अपने ही परिवार को मारने को तैयार हैं।”"),
"1.46": ("“यदि धृतराष्ट्र के पुत्र, हाथ में शस्त्र लिए, युद्ध में मुझे मारें — मुझे निहत्थे और बिना प्रतिरोध — वह मेरे लिए बेहतर होगा।”",
         "“यदि धृतराष्ट्र के पुत्र मुझे — निहत्थे और रक्षाहीन — गिरा दें, तो वह लड़ने से कहीं अच्छा होगा।”"),
"1.47": ("संजय ने कहा: युद्धभूमि में ऐसा कहकर, अर्जुन रथ के आसन पर बैठ गया, धनुष-बाण त्यागकर, मन शोक से भरा हुआ।",
         "संजय निष्कर्ष में कहते हैं: “ऐसा कहकर, अर्जुन रथ की सीट पर धँस गया, धनुष-बाण छोड़ दिया, और हृदय शोक से टूटकर बैठ गया।”"),
"2.01": ("संजय ने कहा: इस प्रकार करुणा से आक्रांत, नेत्रों में आँसू और आवेग भरे हुए, शोकाकुल अर्जुन को देखकर मधुसूदन ने ये वचन कहे।",
         "संजय वर्णन करते हैं: “करुणा में डूबे हुए, आँखों में आँसू और विक्षोभ भरे हुए शोकाकुल अर्जुन को देखकर कृष्ण (मधुसूदन) ने उन्हें सम्बोधित किया।”"),
"2.02": ("श्री भगवान् ने कहा: हे अर्जुन, इस संकट की घड़ी में तुझ पर यह कहाँ से आ गई — यह अनार्य-अयोग्य, स्वर्ग के द्वार को बंद करने वाली और अपयश लाने वाली कापुरुषता?",
         "कृष्ण ने कहा: “अर्जुन, यह कमज़ोरी तुझ पर ठीक इसी संकट की घड़ी में कहाँ से आ पड़ी? यह तुझे शोभा नहीं देती, यह स्वर्ग का द्वार बंद करती है और तुझे अपमानित करेगी।”"),
"2.03": ("हे पार्थ, कापुरुषता को मत अपना — यह तुझे शोभा नहीं देती। हृदय की इस क्षुद्र दुर्बलता को त्यागकर उठ, हे परंतप!",
         "“इस कायरता के आगे मत झुक, अर्जुन — यह तुझे शोभा नहीं देती। इस क्षुद्र कमज़ोरी को झाड़कर खड़ा हो जा, हे शत्रुओं को जलाने वाले!”"),
"2.04": ("अर्जुन ने कहा: हे मधुसूदन, मैं युद्ध में भीष्म और द्रोण पर बाण कैसे चला सकता हूँ — जो पूजनीय हैं, हे शत्रुहन्ता?",
         "अर्जुन पूछते हैं: “हे कृष्ण, भीष्म और द्रोण पर मैं बाण कैसे चला सकता हूँ? वे मेरे आदर के पात्र हैं, हथियारों के नहीं।”"),
"2.05": ("इस लोक में इन महान् गुरुओं को मारने से भीख माँगकर जीना ही अच्छा है। इन्हें मारकर — लौकिक उद्देश्यों के लिए भी — मैं रक्त से सने हुए सुख ही चखूँगा।",
         "“इन पूज्य गुरुओं को मारने से भिक्षा माँगकर खाना ही अच्छा है। यदि मैंने राज्य और भोग के लिए इन्हें मारा, तो मुझे उनके रक्त से सने हुए सुख ही मिलेंगे।”"),
"2.06": ("और हम नहीं जानते कि हमारे लिए क्या अच्छा है — इन्हें जीतना या इनसे पराजित होना। धृतराष्ट्र के ये पुत्र ही हमारे सामने खड़े हैं; इन्हें मारकर हम जीना नहीं चाहेंगे।",
         "“हम यह भी नहीं बता सकते कि विजय अच्छी है या पराजय। धृतराष्ट्र के ये पुत्र हमारे सामने हैं, और इन्हें मारने के बाद हम जीना नहीं चाहेंगे।”"),
"2.07": ("मेरा स्वभाव दया से पराजित है; कर्तव्य के विषय में मेरी बुद्धि मोहित है। मैं तुझसे पूछता हूँ: निश्चय करके बता, क्या कल्याणकारी है — मैं तेरा शिष्य हूँ; मुझे शिक्षा दे, मैंने तेरी शरण ली है।",
         "“दया ने मुझे तोड़ दिया है और धर्म के विषय में मैं उलझन में हूँ। मुझे साफ़-साफ़ बता कि क्या अच्छा है। मैं तेरा शिष्य हूँ — मुझे मार्ग दिखा, मैं तेरी शरण में आया हूँ।”"),
"2.08": ("मैं नहीं देखता कि यह मेरी इन्द्रियों को सुखाने वाला शोक किससे दूर हो — चाहे मुझे पृथ्वी का अद्वितीय राज्य मिले या देवताओं पर स्वामित्व।",
         "“मैं कोई उपाय नहीं देखता जो मेरी इन्द्रियों को सुखाने वाले इस शोक को हटा सके — न तो अविभाजित राज्य से, न देवताओं के शासन से ही।”"),
"2.09": ("संजय ने कहा: हृषीकेश से ऐसा कहकर, शत्रुओं को तपाने वाले अर्जुन ने गोविन्द से कहा, 'मैं युद्ध नहीं करूँगा' — और चुप हो गया।",
         "संजय आगे कहते हैं: “कृष्ण से ऐसा कहकर, और 'मैं युद्ध नहीं करूँगा' घोषित करके, शत्रुओं का आतंक अर्जुन शान्त हो गया।”"),
"2.10": ("दोनों सेनाओं के बीच शोक करते हुए उसे, हे भरतवंशी, हृषीकेश ने मानो मुस्कुराकर ये वचन कहे।",
         "संजय आगे कहते हैं: “तब, हे राजा, दोनों सेनाओं के बीच शोक में बैठे अर्जुन को कृष्ण ने मुस्कुराकर कहा।”"),
"2.11": ("श्री भगवान् ने कहा: जिनके लिए शोक नहीं करना चाहिए, उनके लिए तू शोक करता है, फिर भी पण्डितों की बातें बोलता है। पण्डित न जीवितों के लिए शोक करते हैं, न मृतकों के लिए।",
         "कृष्ण ने कहा: “जिनके लिए शोक उचित नहीं, उन्हीं के लिए तू विलाप करता है, और ऋषि की बातें करता है। ज्ञानी न जीते हुए के लिए रोते हैं, न मरे हुए के लिए।”"),
"2.12": ("ऐसा कोई समय नहीं था जब मैं नहीं था, न तू था, न ये राजा थे; और भविष्य में भी हममें से कोई नहीं रहेगा, ऐसा नहीं है।",
         "ऐसा कोई क्षण कभी था ही नहीं जब मैं न रहा हूँ — या तू, या ये सब राजा। और आगे भी हममें से कोई मिटने वाला नहीं।"),
"2.13": ("जैसे देहधारी आत्मा इस शरीर में बचपन, जवानी और बुढ़ापे से गुजरती है, वैसे ही दूसरे शरीर में प्रवेश करती है; ज्ञानी इससे मोहित नहीं होते।",
         "“जैसे शरीर के भीतर की आत्मा बचपन, जवानी और बुढ़ापे से होकर गुजरती है, वैसे ही मृत्यु पर वह नए शरीर में पहुँचती है। ज्ञानी इसमें कभी भ्रमित नहीं होते।”"),
"2.14": ("हे कुन्तीपुत्र, इन्द्रियों का विषयों से संपर्क सर्दी-गर्मी, सुख-दुःख देता है; ये आते-जाते रहते हैं, अनित्य हैं — हे भारत, इन्हें सहन कर।",
         "“संसार से संपर्क सर्दी-गर्मी, सुख-दुःख लाता है — ये आते-जाते हैं, अर्जुन; क्षणिक हैं। इन्हें सहना सीख।”"),
"2.15": ("जिसे ये विचलित नहीं कर सकते, हे नरश्रेष्ठ — सुख-दुःख में समान रहने वाला ज्ञानी — वही अमरत्व का अधिकारी है।",
         "“जिसे ये हिला नहीं सकते — सुख-दुःख में एक-सा रहने वाला ज्ञानी — वही अमरत्व के योग्य है।”"),
"2.16": ("असत् का अस्तित्व नहीं है; सत् कभी अस्तित्वहीन नहीं होता। दोनों का यह तत्त्व तत्त्वदर्शियों ने देखा है।",
         "“जो वास्तविक नहीं, वह कभी सचमुच रहता नहीं; जो वास्तविक है, वह कभी मिटता नहीं। सत्य को देखने वालों ने दोनों की सीमा समझ ली है।”"),
"2.17": ("जिससे यह सब व्याप्त है, उसे अविनाशी जान। उस अक्षय पुरुष का विनाश कोई नहीं कर सकता।",
         "“जान ले कि यह सब जिससे व्याप्त है, वह अविनाशी है। अस्तित्व की कोई वस्तु उस अपरिवर्तनीय को नष्ट नहीं कर सकती।”"),
"2.18": ("अनन्त, अविनाशी, अप्रमेय देहधारी आत्मा के ये शरीर अन्त वाले कहे गए हैं; इसलिए हे भारत, युद्ध कर।",
         "“अनन्त, अविनाशी, अप्रमेय आत्मा के शरीर ही समाप्त होते हैं — आत्मा नहीं। इसलिए, अर्जुन, युद्ध कर।”"),
"2.19": ("जो आत्मा को मारने वाला समझता है, और जो आत्मा मारा जाता है समझता है — दोनों सचमुच नहीं जानते: यह न मारता है, न मारा जाता है।",
         "“जो सोचता है कि आत्मा मार सकती है, और जो सोचता है कि आत्मा मारी जा सकती है — दोनों ग़लत हैं: आत्मा न मारती है, न मारी जाती है।”"),
"2.20": ("यह कभी जन्मता नहीं, कभी मरता नहीं; होकर यह फिर कभी न होने वाला नहीं है। अजन्मा, नित्य, शाश्वत और पुरातन — शरीर मारे जाने पर यह नहीं मारा जाता।",
         "“आत्मा कभी जन्मती नहीं और कभी मरती नहीं। एक बार होकर वह कभी नहीं मिटती। अजन्मा, नित्य, कालातीत — शरीर मरने पर भी आत्मा नहीं मरती।”"),
"2.21": ("इस आत्मा को अविनाशी, नित्य, अजन्मा और अक्षय जानकर — हे पार्थ, कौन मनुष्य किसे मरवा सकता है या मार सकता है?",
         "“जब कोई आत्मा को अविनाशी, नित्य, अजन्मा और अक्षय जान लेता है — तो ऐसा व्यक्ति किसे मार सकता है, या किससे मरवा सकता है?”"),
"2.22": ("जैसे मनुष्य जीर्ण वस्त्र त्यागकर नए वस्त्र धारण करता है, वैसे ही देहधारी आत्मा जीर्ण शरीर त्यागकर नए शरीर में प्रवेश करती है।",
         "“जैसे व्यक्ति पुराने कपड़े उतारकर नए पहनता है, वैसे ही आत्मा अपने घिसे हुए शरीर को छोड़कर नया शरीर लेती है।”"),
"2.23": ("शस्त्र इसे नहीं काटते, अग्नि इसे नहीं जलाती, जल इसे नहीं भिगोता, वायु इसे नहीं सुखाती।",
         "“कोई हथियार आत्मा को नहीं चीर सकता, कोई आग नहीं जला सकती, कोई पानी नहीं भिगो सकता, कोई हवा नहीं सुखा सकती।”"),
"2.24": ("यह काटा, जलाया, भिगोया और सुखाया नहीं जा सकता। यह नित्य, सर्वव्यापी, स्थिर, अचल और सनातन है।",
         "“आत्मा न कटती है, न जलती है, न भीगती है, न सूखती है। वह नित्य, सर्वव्यापी, स्थिर, अचल और पुरातन है।”"),
"2.25": ("यह अव्यक्त, अचिन्त्य और विकाररहित कहा जाता है। इसे ऐसा जानकर तुझे शोक नहीं करना चाहिए।",
         "“आत्मा अव्यक्त, अचिन्त्य और अपरिवर्तनीय कही जाती है। इसे ऐसे जान लेने पर तुझे शोक का कोई कारण नहीं है।”"),
"2.26": ("किन्तु यदि तू आत्मा को सदा जन्मने वाली और सदा मरने वाली मानता है, हे महाबाहो, तो भी तुझे शोक नहीं करना चाहिए।",
         "“यदि तू भूल से आत्मा को लगातार जन्मती-मरती हुई मानता है, अर्जुन — तब भी शोक नहीं करना चाहिए।”"),
"2.27": ("क्योंकि जन्मे हुए की मृत्यु निश्चित है, और मरे हुए का जन्म निश्चित है। इसलिए, अनिवार्य विषय में तुझे शोक नहीं करना चाहिए।",
         "“जो जन्मा है वह निश्चय मरेगा, और जो मरा है वह निश्चय फिर जन्मेगा। अतः इस अपरिहार्य विषय में शोक का स्थान नहीं है।”"),
"2.28": ("सभी प्राणी आदि में अव्यक्त हैं, मध्य में व्यक्त हैं, और अन्त में फिर अव्यक्त हो जाते हैं। हे भारत, शोक करने की क्या बात है?",
         "“सभी प्राणी जन्म से पहले अदृश्य हैं, जीवन में दृश्य हैं, और मृत्यु के बाद फिर अदृश्य हो जाते हैं। तो शोक करने की क्या बात है?”"),
"2.29": ("कोई आत्मा को आश्चर्य की तरह देखता है, कोई आश्चर्य की तरह वर्णन करता है, कोई आश्चर्य की तरह सुनता है — और सुनकर भी कोई सचमुच नहीं जानता।",
         "“कोई आत्मा को अद्भुत रूप में देखता है, कोई वर्णन करता है, कोई सुनता है — और सुनकर भी वास्तव में कोई नहीं समझता।”"),
"2.30": ("सबके शरीर में रहने वाली देहधारी आत्मा सदा अवध्य है, हे भारत। इसलिए तू किसी भी प्राणी के लिए शोक नहीं करना चाहिए।",
         "“हर शरीर में रहने वाली आत्मा सदा के लिए अविनाशी है, अर्जुन। इसलिए तुझे किसी के लिए भी शोक नहीं करना चाहिए।”"),
"2.31": ("और अपने धर्म पर विचार करके भी तुझे विचलित नहीं होना चाहिए; क्योंकि क्षत्रिय के लिए धर्मयुद्ध से बढ़कर कुछ नहीं है।",
         "“अपने कर्तव्य को देखकर भी तुझे हिचकना नहीं चाहिए: योद्धा के लिए धर्म के लिए लड़े गए युद्ध से बढ़कर कुछ नहीं है।”"),
"2.32": ("हे पार्थ, धन्य हैं वे क्षत्रिय, जिन्हें ऐसा युद्ध स्वयं मिलता है — स्वर्ग का खुला द्वार।",
         "“भाग्यशाली हैं वे योद्धा, अर्जुन, जिन्हें ऐसा युद्ध मिलता है — यह बिना बुलाए आता है और स्वर्ग का खुला द्वार है।”"),
"2.33": ("किन्तु यदि तू यह धर्मयुद्ध नहीं करता, तो अपने धर्म और कीर्ति को त्यागकर पाप प्राप्त करेगा।",
         "“किन्तु यदि तू यह धर्मयुद्ध लड़ने से इनकार करेगा, तो अपना कर्तव्य और सम्मान दोनों खो देगा — और पाप तेरा होगा।”"),
"2.34": ("लोग तेरी चिरस्थायी अपकीर्ति की चर्चा करेंगे; और सम्मानित पुरुष के लिए अपमान मृत्यु से भी बुरा है।",
         "“संसार तेरी चिरन्तन लाज की बात फैलाएगा; और जो सम्मानित है, उसके लिए अपमान मृत्यु से भी बुरा है।”"),
"2.35": ("महारथी यही समझेंगे कि तू भय से युद्ध से भाग गया; और जो तुझे ऊँची दृष्टि से देखते थे, वे तुझे तुच्छ समझेंगे।",
         "“बड़े योद्धा कहेंगे कि तू डर से पीछे हट गया; जो पहले तेरी प्रशंसा करते थे, वे ही तुझे तिरस्कार की दृष्टि से देखेंगे।”"),
"2.36": ("तेरे शत्रु तेरी शक्ति की निन्दा करते हुए बहुत-सी अकथनीय बातें कहेंगे। उससे अधिक पीड़ादायक क्या होगा?",
         "“तेरे शत्रु वे बातें कहेंगे जो कही नहीं जानी चाहिएं — तेरे साहस का उपहास करेंगे। उससे बढ़कर दुखदायी क्या हो सकता है?”"),
"2.37": ("मारा जाकर तू स्वर्ग पाएगा; विजयी होकर पृथ्वी का भोग करेगा। इसलिए हे कुन्तीपुत्र, युद्ध के लिए दृढ़ होकर उठ।",
         "“मरने पर तुझे स्वर्ग मिलेगा; जीतने पर तू पृथ्वी पर राज्य करेगा। इसलिए, अर्जुन, युद्ध का निश्चय करके खड़ा हो जा।”"),
"2.38": ("सुख-दुःख, लाभ-हानि, विजय-पराजय को समान करके तब युद्ध कर — ऐसे युद्ध करने पर तुझे पाप नहीं लगेगा।",
         "“सुख-दुःख, लाभ-हानि, जय-पराजय को एक-सा मानकर युद्ध कर — तुझे कोई पाप नहीं छुएगा।”"),
"2.39": ("हे पार्थ, यह सांख्य-बुद्धि तुझसे कही गई। अब योग-बुद्धि सुन; इससे युक्त होकर तू कर्म-बन्धन से छूट जाएगा।",
         "“मैंने तुझे सांख्य का विवेक सिखाया; अब योग का ज्ञान सुन। इसी में जीने वाला कर्म के बन्धन से मुक्त हो जाता है।”"),
"2.40": ("यहाँ आरम्भ का नाश नहीं होता, न उल्टा फल ही होता है। इस धर्म का अल्प-सा भी अंश महान् भय से रक्षा करता है।",
         "“इस मार्ग में कोई प्रयास व्यर्थ नहीं जाता और कोई बाधा उसे लौटा नहीं देती। इस अभ्यास का थोड़ा-सा भी हिस्सा बड़े भय से बचा लेता है।”"),
"2.41": ("हे कुरुनन्दन, यहाँ दृढ़निश्चयी की बुद्धि एक, एकाग्र होती है; किन्तु अनिश्चयी की बुद्धियाँ अनन्त शाखाओं में फैलती हैं।",
         "“दृढ़ संकल्प की बुद्धि एक और स्थिर होती है, अर्जुन; अनिश्चित मन की बुद्धियाँ अनगिनत दिशाओं में बिखरती हैं।”"),
"2.42": ("वेदों के पुष्पित वचनों में रमने वाले, कर्मकाण्ड और भोग में आसक्त अज्ञानी, हे पार्थ, 'इसके अतिरिक्त और कुछ नहीं है' — ऐसा घोषित करते हैं।",
         "“सतही मन वाले वेदों के आकर्षक वचनों में रमते हैं और दावा करते हैं कि उनसे परे कुछ है ही नहीं — कर्मकाण्ड और उसके फलों से चिपके हुए।”"),
"2.43": ("कामना से भरे, स्वर्ग के इच्छुक वे फल के रूप में जन्म और कर्म बताते हैं, और भोग-ऐश्वर्य के लिए अनेक विशेष कर्मों का उपदेश करते हैं।",
         "“वे कामना से भरे होते हैं, स्वर्ग चाहते हैं, पुनर्जन्म और पुरस्कार का वादा करते हैं, और भोग-विलास के लिए जटिल अनुष्ठानों पर ज़ोर देते हैं।”"),
"2.44": ("भोग और ऐश्वर्य में आसक्त, ऐसे वचनों से मन हरे हुए लोगों में समाधि में दृढ़ एकाग्र बुद्धि नहीं उत्पन्न होती।",
         "“जिनका मन भोग और ऐश्वर्य से मोहित है और इन वचनों ने चुरा लिया है, उनमें समाधि की स्थिर बुद्धि जड़ नहीं जमाती।”"),
"2.45": ("वेद तीन गुणों के विषय हैं; हे अर्जुन, तीनों गुणों से ऊपर उठ — द्वन्द्वों से रहित, सदा सत्त्व में स्थित, लाभ-स्वामित्व से परे, आत्मायुक्त हो।",
         "“वेद तीन गुणों के भीतर ही चलते हैं; उनसे ऊपर उठ, अर्जुन — द्वन्द्व से परे, शुद्धता में टिककर, मोह और स्वामित्व से मुक्त, अपने स्वामी बनकर।”"),
"2.46": ("जितना उपयोग जल से सर्वत्र भर जाने पर कुएँ का होता है, उतना ही समझ वाले ब्राह्मण के लिए सब वेदों का है।",
         "“जब भूमि जलमग्न हो जाती है तो कुएँ का थोड़ा-सा ही काम होता है — वैसे ही सत्य को जान चुके ज्ञानी के लिए सारे वेद।”"),
"2.47": ("तेरा अधिकार केवल कर्म में है, उसके फलों में कभी नहीं। कर्म-फल को अपना उद्देश्य मत बना, और अकर्म में आसक्त भी मत हो।",
         "“तुझे कर्म करने का अधिकार है, पर उसके फल पर कभी नहीं। फल के लिए मत कर, और कुछ न करने की आलस्य में भी मत चिपक।”"),
"2.48": ("हे धनंजय, योग में स्थित होकर, आसक्ति त्यागकर कर्म कर; सिद्धि-असिद्धि में समान रह — यही समत्व योग कहलाता है।",
         "“योग में जड़ जमाकर, बिना आसक्ति के अपना काम कर, अर्जुन। जय-पराजय में एक-सा रह — वही संतुलन योग है।”"),
"2.49": ("हे धनंजय, कर्म बुद्धि-योग से कहीं निकृष्ट है। बुद्धि में शरण खोज; फल के लिए कर्म करने वाले दयनीय हैं।",
         "“साधारण कर्म समझ के योग से कहीं नीचे है, अर्जुन। विवेकपूर्ण बुद्धि में शरण ले — जो केवल फल के लिए परिश्रम करते हैं, वे दयनीय हैं।”"),
"2.50": ("बुद्धि-युक्त व्यक्ति यहीं इस लोक में सुकृत और दुष्कृत दोनों को त्याग देता है। इसलिए योग में लग जा — योग ही कर्म में कुशलता है।",
         "“विवेक से युक्त होकर व्यक्ति इसी जीवन में पुण्य और पाप दोनों छोड़ देता है। इसलिए योग की ओर लग — क्योंकि योग ही कर्म की कला है।”"),
"2.51": ("बुद्धि-युक्त ज्ञानी, कर्म-फल का त्याग करके, जन्म-बन्धन से मुक्त होकर उस पद को प्राप्त करते हैं जो सब दुःखों से परे है।",
         "“समझ में स्थापित ज्ञानी कर्म के फल छोड़ देते हैं और पुनर्जन्म के बन्धन से मुक्त होकर उस अवस्था तक पहुँचते हैं जहाँ कोई दुःख नहीं है।”"),
"2.52": ("जब तेरी बुद्धि मोह की दलदल को पार कर जाएगी, तब तू सुने हुए और सुनने योग्य विषयों के प्रति उदासीन हो जाएगा।",
         "जिस दिन तेरी समझ इस भ्रम की दलदल से बाहर निकलेगी, उस दिन जो सुन चुका है और जो सुनना बाकी है — दोनों बेमानी लगेंगे।"),
"2.53": ("जब श्रुतियों से मोहित तेरी बुद्धि समाधि में स्थिर और अचल हो जाएगी, तब तू योग को प्राप्त होगा।",
         "“जब तेरी बुद्धि, शास्त्रों के विरोधाभासों से न डगमगाकर, समाधि में स्थिर हो जाएगी — तब तू योग तक पहुँच गया है।”"),
"2.54": ("अर्जुन ने कहा: हे केशव, समाधि में स्थित स्थिरप्रज्ञ पुरुष का लक्षण क्या है? स्थिरबुद्धि कैसे बोलता है, कैसे बैठता है, कैसे चलता है?",
         "अर्जुन पूछते हैं: “हे कृष्ण, समाधि में टिके स्थिर प्रज्ञा वाले पुरुष के चिह्न क्या हैं? ऐसा पुरुष कैसे बोलता है, कैसे बैठता है, कैसे चलता है?”"),
"2.55": ("श्री भगवान् ने कहा: हे पार्थ, जब पुरुष मन की सब कामनाओं को त्याग देता है, और आत्मा में ही आत्मा से संतुष्ट रहता है — तब वह स्थिरप्रज्ञ कहलाता है।",
         "कृष्ण उत्तर देते हैं: “जब व्यक्ति मन में उठने वाली हर इच्छा छोड़ देता है और आत्मा में ही आत्मा से संतोष पाता है — वही स्थिर बुद्धि वाला है।”"),
"2.56": ("दुःख में जिसका मन विचलित नहीं होता, सुख में जो निःस्पृह है, जिससे राग, भय और क्रोध चले गए हैं — वही स्थिरबुद्धि मुनि है।",
         "“जिसका मन दुःख से नहीं हिलता और सुख में लालसा नहीं रखता, जिसने काम, भय और क्रोध छोड़ दिए हैं — वह स्थिर मन का ज्ञानी है।”"),
"2.57": ("जो सर्वत्र स्नेहरहित है, शुभ या अशुभ पाकर न हर्षित होता है न विमुख — उसकी बुद्धि दृढ़ स्थापित है।",
         "“जो किसी से चिपकता नहीं, जो अच्छे से प्रसन्न नहीं होता और बुरे से विचलित नहीं होता — उसकी समझ स्थिर होती है।”"),
"2.58": ("जैसे कछुआ चारों ओर से अपने अंगों को समेट लेता है, वैसे ही जब पुरुष इन्द्रियों को विषयों से हटा लेता है — उसकी बुद्धि दृढ़ स्थापित है।",
         "“जैसे कछुआ अपने अंग भीतर खींच लेता है, वैसे जब व्यक्ति इन्द्रियों को विषयों से हटा लेता है — उसकी बुद्धि दृढ़ होती है।”"),
"2.59": ("संयमी पुरुष से विषय दूर हो जाते हैं, पर उनका रस रह जाता है; और परम को देखकर वह रस भी चला जाता है।",
         "“परहेज़ करने वाले से विषय दूर हट जाते हैं, पर उनका लोभ छिपा रहता है; किन्तु परम सत्य को देखते ही वह लोभ भी मिट जाता है।”"),
"2.60": ("हे कुन्तीपुत्र, प्रयत्नशील ज्ञानी के लिए भी चंचल इन्द्रियाँ बलपूर्वक मन को हर ले जाती हैं।",
         "“प्रयास करते हुए ज्ञानी की भी, अर्जुन, बेचैन इन्द्रियाँ मन को ज़बरदस्ती खींच ले जाती हैं।”"),
"2.61": ("उन सबको संयम में रखकर, संयमी पुरुष मुझमें ही तत्पर होकर बैठे; जिसकी इन्द्रियाँ वश में हैं, उसकी बुद्धि दृढ़ स्थापित है।",
         "“सब इन्द्रियों को काबू में रखकर योगी मुझ पर ही ध्यान देकर बैठे; जिसकी इन्द्रियाँ वश में हैं, उसी की समझ दृढ़ होती है।”"),
"2.62": ("विषयों का चिन्तन करने से उनमें आसक्ति उत्पन्न होती है; आसक्ति से कामना उत्पन्न होती है; कामना से क्रोध उत्पन्न होता है।",
         "“इन्द्रिय-विषयों पर मन देना आसक्ति जन्माता है; आसक्ति से इच्छा; इच्छा से क्रोध आता है।”"),
"2.63": ("क्रोध से मोह उत्पन्न होता है; मोह से स्मृति का भ्रम; स्मृति-भ्रम से बुद्धि का नाश; और बुद्धि-नाश से पुरुष नष्ट हो जाता है।",
         "“क्रोध मोह लाता है; मोह स्मरण-शक्ति को उलझा देता है; उलझी स्मृति विवेक को नष्ट करती है; और विवेक नष्ट होते ही व्यक्ति बरबाद हो जाता है।”"),
"2.64": ("किन्तु जो राग-द्वेष से रहित, वश में की हुई इन्द्रियों द्वारा विषयों के बीच विचरता है, संयमी — वह प्रसन्नता को प्राप्त होता है।",
         "“किन्तु आत्म-संयमी, इन्द्रियों को वश में रखकर, राग-द्वेष के बिना विषयों के बीच चलता है — और शान्ति जीतता है।”"),
"2.65": ("उस प्रसन्नता में उसके सब दुःख नष्ट हो जाते हैं; क्योंकि प्रसन्न-चित्त की बुद्धि शीघ्र ही दृढ़ हो जाती है।",
         "“उस शान्ति में ऐसे व्यक्ति के सब कष्ट समाप्त हो जाते हैं; शान्त मन शीघ्र ही स्पष्टता में स्थिर हो जाता है।”"),
"2.66": ("असंयत के लिए बुद्धि नहीं, असंयत के लिए भावना नहीं; भावना-रहित के लिए शान्ति नहीं — शान्ति-रहित को सुख कैसे मिले?",
         "“अनुशासनहीन को विवेक नहीं, चंचल को ध्यान नहीं; ध्यान के बिना शान्ति नहीं, और शान्ति के बिना सुख कैसे सम्भव?”"),
"2.67": ("क्योंकि चलायमान इन्द्रियों का अनुसरण करने वाला मन बुद्धि को हर ले जाता है, जैसे वायु जल में नाव को ले जाती है।",
         "“इन्द्रियों के पीछे भटकता हुआ मन व्यक्ति का विवेक बहा ले जाता है, जैसे हवा समुद्र में नाव को बहा ले जाती है।”"),
"2.68": ("इसलिए, हे महाबाहो, जिसकी इन्द्रियाँ विषयों से सब ओर से हटा ली गई हैं — उसी की बुद्धि दृढ़ स्थापित है।",
         "“इसलिए, अर्जुन, जिसने इन्द्रियों को विषयों से पूरी तरह हटा लिया है — उसी की समझ दृढ़ होती है।”"),
"2.69": ("सब प्राणियों के लिए जो रात है, संयमी मुनि के लिए वह जागरण है; प्राणी जिसमें जागते हैं, वह दर्शी मुनि के लिए रात है।",
         "“साधारण संसार के लिए जो रात है, संयमी ज्ञानी के लिए वह जागृति है; और जिसे संसार दिन कहता है, वह द्रष्टा के लिए रात है।”"),
"2.70": ("जैसे जल चारों ओर से भरने पर भी अचल रहने वाले समुद्र में प्रवेश करते हैं, वैसे ही जिसमें सब कामनाएँ प्रवेश करती हैं, वह शान्ति पाता है — कामनाओं का कामी नहीं।",
         "“जैसे नदियाँ समुद्र में गिरती हैं और समुद्र अचल भरा रहता है, वैसे ही जिसमें सब इच्छाएँ बहकर आती हैं, वह शान्त रहता है — इच्छा का ही लोभी नहीं।”"),
"2.71": ("जो पुरुष सब कामनाओं को त्यागकर निःस्पृह, निर्मम और निरहंकार होकर विचरता है — वह शान्ति को प्राप्त होता है।",
         "“जो व्यक्ति हर इच्छा छोड़कर, लोभ, 'मेरा' और 'मैं' के बिना जीता है — वह शान्ति पाता है।”"),
"2.72": ("हे पार्थ, यह ब्राह्मी अवस्था है; इसे प्राप्त करके पुरुष फिर मोहित नहीं होता। अन्तकाल में भी इसमें स्थित रहकर वह ब्रह्मनिर्वाण पाता है।",
         "“यह ब्रह्म की अवस्था है, अर्जुन। इसमें पहुँचकर कोई फिर कभी मोह में नहीं पड़ता। मृत्यु की घड़ी में भी इसमें टिककर वह ब्रह्म में मुक्ति पाता है।”"),
"3.01": ("अर्जुन ने कहा: हे जनार्दन, यदि आप ज्ञान को कर्म से श्रेष्ठ मानते हैं, तो हे केशव, मुझे इस भयंकर कर्म में क्यों लगा रहे हैं?",
         "अर्जुन पूछते हैं: “यदि आप ज्ञान को कर्म से बेहतर मानते हैं, तो केशव, मुझे इस भयानक युद्ध में क्यों ढकेल रहे हैं?”"),
"3.02": ("मिलते-जुलते प्रतीत होने वाले वचनों से आप मेरी बुद्धि को उलझा रहे हैं। एक ही बात निश्चय करके कहिए, जिससे मैं कल्याण को प्राप्त करूँ।",
         "“आपके वचन मिश्रित और विरोधाभासी लगते हैं — वे मुझे ही उलझाते हैं। सच्चे कल्याण तक पहुँचाने वाला एक ही मार्ग स्पष्ट बताइए।”"),
"3.03": ("श्री भगवान् ने कहा: हे निष्पाप, इस लोक में पहले ही मैंने दो प्रकार की निष्ठाएँ कही हैं: सांख्यों के लिए ज्ञान-योग और योगियों के लिए कर्म-योग।",
         "कृष्ण ने कहा: “बहुत पहले मैंने दो मार्ग सिखाए थे, हे निष्पाप: चिन्तनशील के लिए ज्ञान का मार्ग, और क्रियाशील योगी के लिए निःस्वार्थ कर्म का मार्ग।”"),
"3.04": ("कर्मों के न करने से मनुष्य कर्म-संन्यास को प्राप्त नहीं होता, और न केवल संन्यास से ही सिद्धि मिलती है।",
         "“कर्म से इनकार करके तू कर्म से मुक्त नहीं होता, न संसार त्यागने मात्र से सिद्धि मिलती है।”"),
"3.05": ("निश्चय ही कोई भी एक क्षण भी अकर्मी नहीं रहता; प्रकृति से उत्पन्न गुण सबको असहाय होकर कर्म कराते हैं।",
         "“कोई भी एक पल भी निष्क्रिय नहीं बैठ सकता — प्रकृति के गुण सबसे, चाहे-अनचाहे, कर्म कराते हैं।”"),
"3.06": ("जो कर्मेन्द्रियों को रोककर मन में विषयों का चिन्तन करता हुआ बैठता है — वह मूढ़ कपटी कहलाता है।",
         "“जो हाथ-पैर अकर्मी रखकर मन में भोगों की बातें खेलाता है — वह स्वयं को धोखा देने वाला ढोंगी है।”"),
"3.07": ("किन्तु जो मन से इन्द्रियों को वश में करके, आसक्ति रहित होकर कर्मेन्द्रियों द्वारा कर्म-योग करता है — वह उत्कृष्ट है।",
         "“किन्तु जो मन से इन्द्रियों को काबू में रखकर शरीर से बिना आसक्ति कर्म करता है — वही सचमुच उत्कृष्ट है।”"),
"3.08": ("तू अपना विहित कर्म कर, क्योंकि कर्म अकर्म से श्रेष्ठ है; अकर्म से तो शरीर का निर्वाह भी नहीं होता।",
         "“तुझे दिया गया कर्तव्य पालन कर, क्योंकि कर्म ही अकर्म से उत्तम — बिना कर्म शरीर को जीवित रखना भी असम्भव है।”"),
"3.09": ("यज्ञ के लिए किए गए कर्म को छोड़कर, यह संसार कर्म से बँधा हुआ है; इसलिए हे कुन्तीपुत्र, आसक्ति रहित होकर यज्ञ के लिए कर्म कर।",
         "“स्वार्थ के लिए किया कर्म बाँधता है; यज्ञ के रूप में अर्पित कर्म मुक्त करता है। इसलिए, अर्जुन, बिना आसक्ति उसी के लिए कर्म कर।”"),
"3.10": ("प्रजापति ने आदि में प्राणियों को यज्ञ के साथ सृष्ट करके कहा: “इससे तुम फलो-फूलो; यह तुम्हारी इच्छापूर्ति करने वाली गाय हो।”",
         "“सृष्टिकर्ता ने आदि में मानवता को यज्ञ की विधि दी: ‘इससे तुम फलोगे-फूलोगे; यह तुम्हारी सब आवश्यकताएँ पूरी करेगा।’”"),
"3.11": ("इससे देवताओं का पोषण करो, और देवता तुम्हारा पोषण करें; परस्पर पोषण करते हुए तुम परम कल्याण को प्राप्त होगे।",
         "“यज्ञ से उच्च शक्तियों की सेवा करो और वे बदले में तुम्हें धारण करें — इस परस्पर दान में सब परम कल्याण तक पहुँचते हैं।”"),
"3.12": ("यज्ञ से पोषित देवता तुम्हें वांछित भोग देंगे; उनके दिए का उपभोग करके बदले में न देने वाला निश्चय चोर है।",
         "“तेरे अर्पण से प्रसन्न देवता जीवन की अच्छी वस्तुएँ देते हैं। उनका दिया लेकर बदला न देना — वह चोरी है।”"),
"3.13": ("यज्ञ के बचे हुए प्रसाद को खाने वाले सज्जन सब पापों से मुक्त होते हैं; किन्तु जो केवल अपने लिए पकाते हैं, वे पापी लोग पाप ही खाते हैं।",
         "“यज्ञ का बचा प्रसाद बाँटकर खाने वाले पाप से शुद्ध होते हैं; जो केवल अपने लिए पकाते हैं, वे पाप के अतिरिक्त कुछ नहीं खाते।”"),
"3.14": ("प्राणी अन्न से उत्पन्न होते हैं; अन्न वर्षा से; वर्षा यज्ञ से; यज्ञ कर्म से उत्पन्न होता है।",
         "“जीवन अन्न से, अन्न वर्षा से, वर्षा यज्ञ से, और यज्ञ सत्कर्म से — सब एक शृंखला में जुड़े हैं।”"),
"3.15": ("कर्म ब्रह्म से और ब्रह्म अक्षर से उत्पन्न होता है, यह जान; इसलिए सर्वव्यापी ब्रह्म सदा यज्ञ में प्रतिष्ठित है।",
         "“सब कर्म अनन्त ब्रह्म से उत्पन्न होते हैं; इसलिए सर्वव्यापी परमात्मा सदा निःस्वार्थ अर्पण में विद्यमान है।”"),
"3.16": ("हे पार्थ, जो यहाँ इस प्रकार चलाए गए इस चक्र का अनुसरण नहीं करता, जिसका जीवन पापमय है, इन्द्रियों में रमने वाला — वह व्यर्थ जीता है।",
         "“देने-लेने के इस चक्र में भाग लेने से इनकार करो तो तेरा जीवन व्यर्थ है, अर्जुन — तू केवल इन्द्रियों के लिए जीता है।”"),
"3.17": ("किन्तु जो केवल आत्मा में ही रमता है, आत्मा में ही तृप्त है, और आत्मा में ही संतुष्ट है — उसके लिए करने को कुछ नहीं है।",
         "“जो अपने भीतर ही पूर्ण सुखी है, उसके लिए करने को कुछ नहीं बचता — उसका कोई कर्तव्य नहीं रहता।”"),
"3.18": ("उसके लिए किए गए या न किए गए कर्म में कोई प्रयोजन नहीं है, न किसी प्रयोजन के लिए उसका किसी प्राणी पर आश्रय है।",
         "“ऐसे व्यक्ति को करने या न करने से कुछ प्राप्त नहीं होता; न कोई प्राणी या लक्ष्य उसे बाँध सकता है।”"),
"3.19": ("इसलिए आसक्ति रहित होकर सदा कर्तव्यरूप कर्म ही कर; क्योंकि आसक्ति के बिना कर्म करने से मनुष्य परम पद को प्राप्त होता है।",
         "“इसलिए कर्म करते रह, पर कभी फल से मत चिपक — बिना आसक्ति का कर्म ही परम तक पहुँचाने का मार्ग है।”"),
"3.20": ("निश्चय ही कर्म से ही जनक आदि ने सिद्धि प्राप्त की; लोकसंग्रह को ध्यान में रखकर भी तुझे कर्म करना चाहिए।",
         "“राजा जनक और अनेकों ने कर्म से ही सिद्धि पाई। संसार के हित के लिए तुझे भी कर्म करना ही चाहिए।”"),
"3.21": ("श्रेष्ठ पुरुष जो करता है, वही साधारण मनुष्य करता है; वह जो प्रमाण मानता है, संसार उसी का अनुसरण करता है।",
         "“लोग अपने नेताओं का अनुकरण करते हैं। तुममें से श्रेष्ठ जो करता है, वही दूसरों का नियम बन जाता है।”"),
"3.22": ("हे पार्थ, मेरे लिए तीनों लोकों में करने को कुछ नहीं है, न प्राप्त करने को अप्राप्त कुछ है — फिर भी मैं कर्म में लगा रहता हूँ।",
         "“तीनों लोकों में मुझे प्राप्त करने को कुछ बाकी नहीं है — फिर भी मैं काम करता रहता हूँ।”"),
"3.23": ("यदि मैं कभी अकर्मी होकर, बिना थके, कर्म न करूँ, तो हे पार्थ, लोग सब बातों में मेरा ही मार्ग अपनाएँगे।",
         "“यदि मैं कभी काम करना छोड़ दूँ, तो सब मेरा ही उदाहरण अपनाकर अपने कर्तव्य भी छोड़ देंगे।”"),
"3.24": ("यदि मैं कर्म न करूँ तो ये लोक नष्ट हो जाएँ; मैं संकर का कर्ता बनूँगा और इन प्राणियों को नष्ट करूँगा।",
         "“यदि मैं कर्म करना छोड़ दूँ तो संसार ढह जाएगा — और उसके विनाश का कारण मैं ही बनूँगा।”"),
"3.25": ("हे भारत, जैसे अज्ञानी आसक्त होकर कर्म करते हैं, वैसे ही ज्ञानी को भी आसक्ति रहित होकर, लोकसंग्रह के लिए कर्म करना चाहिए।",
         "“अज्ञानी अपने काम से चिपककर काम करते हैं; ज्ञानी भी उतना ही काम करता है, पर बिना चिपके — सबके हित के लिए।”"),
"3.26": ("कर्म में आसक्त अज्ञानियों की बुद्धि में खलल न डाले; स्वयं योगयुक्त होकर कर्म करता हुआ उनसे सब कर्म कराए।",
         "“अपने कर्तव्यों से जुड़े लोगों को मत उलझाओ। अपना काम भक्ति से करो — और वे तुम्हारे उदाहरण से ही सीखें।”"),
"3.27": ("सब कर्म सब प्रकार से प्रकृति के गुणों द्वारा ही सम्पन्न होते हैं; अहंकार से मोहित व्यक्ति 'मैं कर्ता हूँ' — ऐसा सोचता है।",
         "“प्रकृति की शक्तियाँ ही तुझसे सब काम कराती हैं। अहंकारी व्यक्ति झूठा विश्वास करता है — ‘यह सब मैं कर रहा हूँ।’”"),
"3.28": ("किन्तु हे महाबाहो, गुणों और कर्मों के विभाग को तथा गुणों के गुणों में विचरण करने को जानने वाला तत्त्वज्ञ आसक्त नहीं होता।",
         "“ज्ञानी समझते हैं कि गुण गुणों के साथ ही क्रियाशील होते हैं — वे कभी अपने आपको कर्म से नहीं जोड़ते।”"),
"3.29": ("प्रकृति के गुणों से मोहित लोग गुणों से उत्पन्न कर्मों में आसक्त होते हैं; पूर्णज्ञानी को मन्दबुद्धि अल्पज्ञों को विचलित नहीं करना चाहिए।",
         "“अज्ञानी लोग अपने काम से चिपके रहते हैं; ज्ञानी को संन्यास का उपदेश देकर उन्हें खलबलाना नहीं चाहिए।”"),
"3.30": ("सब कर्मों को मुझमें अर्पण कर, मन को आत्मा में स्थिर कर, आशा और ममता से रहित होकर, ज्वर-रहित — युद्ध कर।",
         "“हर कर्म मुझे अर्पण कर, मन को आत्मा पर रख, सब लोभ और ममता छोड़ — और बिना आवेग युद्ध कर।”"),
"3.31": ("जो पुरुष सदा श्रद्धापूर्वक, दोष न देखकर मेरे इस उपदेश का अनुसरण करते हैं — वे कर्म-बन्धन से भी मुक्त हो जाते हैं।",
         "“जो मेरी इस शिक्षा को विश्वास के साथ और बिना किसी गुनाह के अपनाते हैं — वे कर्म की पकड़ से मुक्त हो जाते हैं।”"),
"3.32": ("किन्तु जो दोष देखकर मेरे इस उपदेश का अनुसरण नहीं करते — उन्हें सब ज्ञान से वंचित, नष्ट और अविवेकी जान।",
         "“जो मेरी शिक्षा पर गुनाह करते हैं और उसे अस्वीकार करते हैं — वे हारे हुए हैं; ज्ञान से वंचित होकर स्वयं को नष्ट करते हैं।”"),
"3.33": ("ज्ञानी पुरुष भी अपने स्वभाव के अनुसार कर्म करता है; प्राणी स्वभाव का अनुसरण करते हैं — संयम से क्या होगा?",
         "“सब, ज्ञानी भी, अपने स्वभाव के अनुसार काम करते हैं। प्राणी अपनी प्रकृति को अपनाते हैं — ज़बरदस्ती रोकने का क्या अर्थ?”"),
"3.34": ("हर इन्द्रिय के विषय में राग और द्वेष स्थिर हैं; मनुष्य उनके वश में न पड़े, क्योंकि वे उसके मार्ग रोकने वाले हैं।",
         "“हर इन्द्रिय-विषय पर पसंद-नापसंद चिपकी हुई है। उन्हें अपने ऊपर हावी मत होने दे — वे आध्यात्मिक मार्ग के लुटेरे हैं।”"),
"3.35": ("अपना धर्म, यद्यपि दोषयुक्त है, पराए सुसम्पन्न धर्म से अच्छा है; अपने धर्म में मरना भी अच्छा — पराया धर्म भय लाता है।",
         "“अपना कर्तव्य त्रुटिपूर्ण हो तो भी दूसरे के कर्तव्य को पूरी तरह करने से अच्छा है। अपनी जगह पर मरना भी अच्छा — दूसरे का काम करके डर में जीने से।”"),
"3.36": ("अर्जुन ने कहा: तब हे वार्ष्णेय, किससे प्रेरित होकर मनुष्य अपनी इच्छा के विरुद्ध, मानो बल से बाध्य होकर भी पाप करता है?",
         "अर्जुन पूछते हैं: “कौन-सी शक्ति व्यक्ति से, न चाहते हुए भी, मानो ज़बरदस्ती खींचकर पाप कराती है?”"),
"3.37": ("श्री भगवान् ने कहा: यह कामना है, यह क्रोध है — रजोगुण से उत्पन्न; सब कुछ खा जाने वाला, महापापी — इसे ही यहाँ शत्रु जान।",
         "कृष्ण ने कहा: “यह कामना है — और उससे जन्मा क्रोध — रजोगुण से उठा हुआ। अतृप्त और अत्यन्त पापी: इसे ही अपना सच्चा शत्रु जान।”"),
"3.38": ("जैसे अग्नि धूम से आच्छादित होती है, दर्पण धूल से, और गर्भ झिल्ली से — वैसे ही यह (ज्ञान) उस (कामना) से आच्छादित है।",
         "“कामना ज्ञान को वैसे ढाँकती है, जैसे धुआँ आग को, धूल दर्पण को, और झिल्ली गर्भ को।”"),
"3.39": ("ज्ञानियों का यह शाश्वत शत्रु — कामना का रूप धारण किए हुए, अतृप्त, हे कुन्तीपुत्र, अग्नि के समान — इससे ज्ञान आच्छादित है।",
         "“यह चिर शत्रु — कामना — ज्ञान को ढाँकती है। यह कभी तृप्त नहीं होती; यह आग की तरह जलती है, अर्जुन।”"),
"3.40": ("इन्द्रियाँ, मन और बुद्धि इसका स्थान कही जाती हैं; इनके द्वारा ज्ञान को ढाँककर यह देहधारी को मोहित करती है।",
         "“कामना इन्द्रियों, मन और बुद्धि में बसती है — और उन्हीं से देहधारी को अंधा और मोहित करती है।”"),
"3.41": ("इसलिए, हे भरतश्रेष्ठ, पहले इन्द्रियों को वश में करके, ज्ञान और विवेक का नाश करने वाले इस पापी को फेंक दे।",
         "“इसलिए, अर्जुन, पहले अपनी इन्द्रियों को काबू में कर — और ज्ञान और विवेक दोनों को नष्ट करने वाले इस दुष्ट को मार।”"),
"3.42": ("इन्द्रियाँ श्रेष्ठ कही जाती हैं; इन्द्रियों से श्रेष्ठ मन; मन से श्रेष्ठ बुद्धि; किन्तु बुद्धि से भी श्रेष्ठ वही (आत्मा) है।",
         "“क्रम से ऊपर उठ: इन्द्रियों से परे मन, मन से परे बुद्धि — और बुद्धि से परे आत्मा ही।”"),
"3.43": ("इस प्रकार बुद्धि से परे उसे जानकर, हे महाबाहो, आत्मा द्वारा आत्मा को स्थिर कर, दुर्जय कामना-रूपी शत्रु को मार।",
         "“बुद्धि से परे की आत्मा को पहचानकर, स्वयं को स्वयं से स्थिर करके, जीतना कठिन कामना-रूपी शत्रु को मार, अर्जुन।”"),
"4.01": ("श्री भगवान् ने कहा: इस अविनाशी योग को मैंने विवस्वान् से कहा; विवस्वान् ने मनु को बताया; मनु ने इक्ष्वाकु को कहा।",
         "कृष्ण ने कहा: “बहुत पहले मैंने यह नित्य योग सूर्यदेव विवस्वान् को सिखाया; उन्होंने मनु को दिया, और मनु ने राजा इक्ष्वाकु को।”"),
"4.02": ("इस प्रकार परम्परा से ग्रहण करके राजर्षियों ने इसे जाना; किन्तु दीर्घ काल के क्रम में, हे परंतप, यह योग लुप्त हो गया।",
         "“गुरु से शिष्य तक पहुँचते हुए राजा-ऋषियों ने इसे जाना — पर बहुत लम्बे समय बाद यह खो गया, अर्जुन।”"),
"4.03": ("यही प्राचीन योग आज मैं तुझसे कहता हूँ, क्योंकि तू मेरा भक्त और मित्र है — सचमुच, यह परम गुह्य है।",
         "“वही प्राचीन योग मैं अब तुझे सिखाता हूँ, क्योंकि तू मुझ पर भक्त है और मेरा मित्र है — यह सबसे बड़ा रहस्य है।”"),
"4.04": ("अर्जुन ने कहा: तेरा जन्म पीछे है, और विवस्वान् का जन्म पहले; तो मैं कैसे समझूँ कि तूने आदि में इसे सिखाया था?",
         "अर्जुन पूछते हैं: “आप सूर्यदेव विवस्वान् के बहुत बाद में जन्मे। आदि में उन्हें यह योग कैसे सिखा सकते थे?”"),
"4.05": ("श्री भगवान् ने कहा: मेरे अनेक जन्म बीत चुके हैं, हे अर्जुन, और तेरे भी; मैं उन सबको जानता हूँ, किन्तु तू नहीं जानता, हे परंतप।",
         "कृष्ण ने कहा: “हम दोनों के अनगिनत जन्म हो चुके हैं, अर्जुन। मैं उन सबको याद रखता हूँ; तू नहीं रखता।”"),
"4.06": ("यद्यपि मैं अजन्मा हूँ, अविनाशी आत्मा हूँ, प्राणियों का स्वामी हूँ — अपनी प्रकृति का आश्रय लेकर, अपनी माया से मैं प्रकट होता हूँ।",
         "“मैं अजन्मा और नित्य हूँ, सब प्राणियों का स्वामी — फिर भी, अपनी प्रकृति को उठाकर, अपनी दिव्य शक्ति से संसार में प्रकट होता हूँ।”"),
"4.07": ("हे भारत, जब-जब धर्म का ह्रास और अधर्म का उदय होता है, तब-तब मैं अपने आपको प्रकट करता हूँ।",
         "“जब-जब धर्म क्षीण होता है और अधर्म बढ़ता है, अर्जुन, तब-तब मैं प्रकट होता हूँ।”"),
"4.08": ("साधुओं की रक्षा, दुष्टों का विनाश, और धर्म की स्थापना के लिए मैं युग-युग में जन्म लेता हूँ।",
         "भले लोगों को बचाने, बुरों को मिटाने और धर्म को फिर खड़ा करने — हर युग में मैं आता हूँ।"),
"4.09": ("जो इस प्रकार सचमुच मेरे दिव्य जन्म और कर्म को जानता है — शरीर त्यागकर वह फिर जन्म नहीं लेता; वह मुझे प्राप्त होता है, हे अर्जुन।",
         "“जो सचमुच मेरे दिव्य जन्म और कर्म को समझता है, वह मृत्यु के बाद फिर कभी जन्म नहीं लेता — वह मुझ तक आता है, अर्जुन।”"),
"4.10": ("आसक्ति, भय और क्रोध से मुक्त, मुझमें मग्न, मेरी शरण लेने वाले अनेकों — ज्ञान-तप से शुद्ध होकर — मेरी अवस्था को प्राप्त हुए हैं।",
         "“जो मोह, भय और क्रोध से मुक्त हैं, जो मेरी शरण लेते हैं — वे ज्ञान की अग्नि से शुद्ध होकर मेरे ही स्वरूप तक पहुँचते हैं।”"),
"4.11": ("मनुष्य जिस-जिस प्रकार मुझे प्राप्त होते हैं, उसी-उसी प्रकार मैं उनका सत्कार करता हूँ; हे पार्थ, लोग सब प्रकार से मेरे ही मार्ग का अनुसरण करते हैं।",
         "“जिस प्रकार भी तुम मेरे पास आते हो, मैं उसी प्रकार तुम्हें ग्रहण करता हूँ। हर मार्ग फिर मुझ तक लौटता है, अर्जुन।”"),
"4.12": ("इस लोक में कर्म की सिद्धि चाहने वाले देवताओं की पूजा करते हैं; क्योंकि मनुष्य-लोक में कर्म-जन्य सिद्धि शीघ्र मिलती है।",
         "“शीघ्र फल चाहने वाले देवताओं की पूजा करते हैं; मनुष्य-लोक में कर्म से फल शीघ्र भी मिलता है।”"),
"4.13": ("गुण और कर्म के विभाग के अनुसार मैंने चार वर्णों की रचना की है; यद्यपि मैं इसका कर्ता हूँ, मुझे अकर्ता और अविनाशी जान।",
         "“मैंने गुण और कर्म के अनुसार समाज के चार वर्ग बनाए — फिर भी मैं उन सबसे परे, अपरिवर्तनीय अकर्ता हूँ।”"),
"4.14": ("कर्म मुझे लिप्त नहीं करते, न मुझे कर्म-फल की इच्छा ही है; जो मुझे ऐसा जानता है, वह भी कर्मों से नहीं बँधता।",
         "“मैं फल की इच्छा नहीं करता, इसलिए कर्म मुझे कभी छूते नहीं। जो यह समझता है, वह भी उतना ही मुक्त है।”"),
"4.15": ("यह जानकर प्राचीन मुक्तिकामियों ने कर्म किया; इसलिए तू भी कर्म कर, जैसा पूर्वजों ने किया था।",
         "“पहले के ज्ञानी, मुक्ति चाहने वाले, इसी तरह कर्म करते थे। तुझे भी, अर्जुन, उन्हीं की तरह कर्म करना चाहिए।”"),
"4.16": ("क्या कर्म, क्या अकर्म — यहाँ ज्ञानी भी मोहित हैं; मैं तुझे वह कर्म बताऊँगा, जिसे जानकर तू दुःख से मुक्त हो जाएगा।",
         "“सचमुच कर्म क्या है, और अकर्म क्या? विद्वान भी उलझन में हैं। मैं तुझे कर्म का सत्य सिखाऊँगा — यह जानकर तू सब हानि से मुक्त हो जाएगा।”"),
"4.17": ("निश्चय ही कर्म का स्वरूप समझना चाहिए, और विकर्म का भी, और अकर्म का भी; कर्म की गति गहन है।",
         "“तुझे कर्म, दुष्कर्म, और अकर्म — तीनों को समझना होगा; कर्म के मार्ग गहरे और अगाध हैं।”"),
"4.18": ("जो कर्म में अकर्म देखता है, और अकर्म में कर्म देखता है — वह मनुष्यों में बुद्धिमान है; वह योग में लगा हुआ है और सम्पूर्ण कर्म करता है।",
         "“जो होते हुए काम में कर्ता नहीं देखता, और शान्ति में कर्म देखता है — वह सचमुच ज्ञानी है; कर्म करते हुए भी वह सब कुछ करता है जो करना चाहिए।”"),
"4.19": ("जिसके सब आरम्भ इच्छा और संकल्प से रहित हैं, और जिसके कर्म ज्ञानाग्नि से दग्ध हो गए हैं — उसे ही ज्ञानी पण्डित कहते हैं।",
         "“जिसका हर काम मोह और स्वार्थ से मुक्त है, जिसका कर्म ज्ञान से भस्म हो गया है — विद्वान उसी को सच्चा ज्ञानी कहते हैं।”"),
"4.20": ("कर्म-फल की आसक्ति का त्याग करके, सदा संतुष्ट, किसी आश्रय के बिना — कर्म में लगा होते हुए भी वह वास्तव में कुछ नहीं करता।",
         "“फल के मोह से मुक्त, सदा संतोषी, कुछ न चाहने वाला — ऐसा व्यक्ति कर्म करता है, फिर भी उससे कुछ नहीं होता।”"),
"4.21": ("आशा से रहित, मन और आत्मा को संयत कर, सब परिग्रह त्यागकर, केवल शारीरिक कर्म करने से वह पाप को नहीं प्राप्त होता।",
         "“इच्छा-रहित, आत्म-संयमी, कुछ न रखने वाला — वह केवल शरीर से काम करता है, और कोई पाप उसे नहीं छूता।”"),
"4.22": ("अनायास प्राप्त में संतुष्ट, द्वन्द्वों से परे, ईर्ष्या से रहित, सिद्धि-असिद्धि में समान — कर्म करते हुए भी वह बँधता नहीं।",
         "“जो कुछ मिले उसी में सुखी, गर्मी-सर्दी और जीत-हार से परे, ईर्ष्या-रहित — उसके कर्म उसे कभी नहीं बाँधते।”"),
"4.23": ("आसक्ति से रहित, मुक्त, ज्ञान में स्थित मन वाले, यज्ञ के लिए कर्म करने वाले के कर्म — वे पूर्णतः विलीन हो जाते हैं।",
         "“जो आसक्ति-रहित और स्वतंत्र है, जिसका मन ज्ञान में टिका है और जिसका काम अर्पण है — उसका कर्म पूरी तरह पिघल जाता है।”"),
"4.24": ("ब्रह्म ही हवि है, ब्रह्म ही आहुति है, ब्रह्म-रूप अग्नि में ब्रह्म द्वारा आहुति दी जाती है; ब्रह्म-कर्म में लीन होने वाला ब्रह्म को ही प्राप्त करता है।",
         "“जब अर्पण, अग्नि, देने वाला और देने की क्रिया — सब ब्रह्म के रूप में दिखते हैं, तो कर्म स्वयं ब्रह्म का मार्ग बन जाता है।”"),
"4.25": ("कुछ योगी यज्ञ द्वारा देवताओं की पूजा करते हैं; अन्य यज्ञ को ही, यज्ञ द्वारा, ब्रह्म-रूप अग्नि में आहुति करते हैं।",
         "“कोई देवताओं को भौतिक पूजा चढ़ाते हैं; कोई सम्पूर्ण जीवन को परमात्मा की अग्नि में अर्पण कर देते हैं।”"),
"4.26": ("कुछ लोग श्रवण आदि इन्द्रियों को संयम-रूप अग्नि में आहुति करते हैं; अन्य शब्द आदि विषयों को इन्द्रिय-रूप अग्नि में आहुति करते हैं।",
         "“कुछ साधक अपनी इन्द्रियों को आत्म-संयम की अग्नि में चढ़ाते हैं; अन्य इन्द्रियों के विषयों को ही चढ़ा देते हैं।”"),
"4.27": ("और अन्य लोग इन्द्रियों की सब क्रियाओं और प्राणों की क्रियाओं को, ज्ञान से प्रज्वलित आत्म-संयम-योग-रूप अग्नि में आहुति करते हैं।",
         "“अन्य अपनी इन्द्रियों की हर क्रिया और श्वास की क्रियाओं को, ज्ञान से जली आत्म-संयम की अग्नि में समर्पित करते हैं।”"),
"4.28": ("अन्य लोग द्रव्य-यज्ञ, तपो-यज्ञ, योग-यज्ञ और स्वाध्याय-यज्ञ करते हैं — दृढ़ व्रत वाले तपस्वी।",
         "“कोई धन-दान से, कोई तप से, कोई ध्यान से, कोई शास्त्र-अध्ययन से यज्ञ करते हैं — सब दृढ़ संकल्प के खोजी।”"),
"4.29": ("कुछ प्राण को अपान में, और अपान को प्राण में आहुति करते हैं, प्राण-प्राण की गति को रोककर, प्राणायाम में तत्पर होकर।",
         "“अन्य प्राणायाम करते हैं — एक श्वास को दूसरे में अर्पण करके, जीवन-शक्ति के बहाव को शान्त करके।”"),
"4.30": ("अन्य, मिताहार होकर, प्राणों को प्राणों में ही आहुति करते हैं; ये सब यज्ञ के ज्ञाता हैं, जिनके पाप यज्ञ से भस्म हो जाते हैं।",
         "“अन्य, कम खाकर, श्वास को श्वास में ही अर्पण करते हैं। यज्ञ को समझने वालों के पाप उसी से जल जाते हैं।”"),
"4.31": ("यज्ञ के बचे अमृत का रस चखकर वे अनन्त ब्रह्म को प्राप्त होते हैं; हे कुरुश्रेष्ठ, यह लोक भी यज्ञ-रहित का नहीं — परलोक तो क्या?",
         "“अर्पण के पवित्र बचे भाग पर जीने वाले नित्य ब्रह्म तक पहुँचते हैं। यज्ञ के बिना यह लोक भी भोगा नहीं जा सकता — परलोक तो दूर की बात।”"),
"4.32": ("इस प्रकार शास्त्र में अनेक प्रकार के यज्ञ बताए गए हैं; उन सबको कर्म से उत्पन्न जान — यह जानकर तू मुक्त हो जाएगा।",
         "“शास्त्र कई प्रकार के यज्ञ बताते हैं। जान ले कि वे सब कर्म से उठते हैं — और यह समझना तुझे मुक्त कर देता है।”"),
"4.33": ("हे परंतप, द्रव्यमय यज्ञ से ज्ञान-यज्ञ श्रेष्ठ है; हे पार्थ, सम्पूर्ण कर्म ज्ञान में ही पर्यवसित होता है।",
         "“ज्ञान का अर्पण किसी भी भौतिक अर्पण से बड़ा है — सब कर्म, बिना किसी अपवाद के, ज्ञान में समाप्त होते हैं।”"),
"4.34": ("उस तत्त्व-ज्ञान को प्रणिपात, प्रश्न और सेवा से जान; सत्य को देख चुके तत्त्वदर्शी तुझे उपदेश देंगे।",
         "“नम्रता से ज्ञानियों के पास जा, ईमानदारी से पूछ, और उनकी सेवा कर — सत्य को देखने वाले तुझे ज्ञान देंगे।”"),
"4.35": ("उसे जानकर, हे पाण्डुपुत्र, तू फिर मोह में नहीं पड़ेगा; उससे तू सब प्राणियों को अपने में और मुझमें देखेगा।",
         "“यह ज्ञान पाकर तू फिर कभी मोह में नहीं पड़ेगा — तू सब प्राणियों को अपने भीतर और मुझमें देखेगा।”"),
"4.36": ("यदि तू सब पापियों में सबसे बड़ा पापी भी हो, तो भी तू ज्ञान-रूप नाव से ही सब पापों को पार कर जाएगा।",
         "“यदि तू सबसे बुरा कल्पनीय पापी भी हो, तो ज्ञान की नाव तुझे तेरे सब पापों के पार पहुँचा देगी।”"),
"4.37": ("जैसे प्रज्वलित अग्नि ईंधन को भस्म कर देती है, हे अर्जुन, वैसे ही ज्ञान-अग्नि सब कर्मों को भस्म कर देती है।",
         "“जैसे अग्नि ईंधन को जलाकर राख कर देती है, ज्ञान की अग्नि सब कर्म को जला देती है।”"),
"4.38": ("निश्चय ही यहाँ ज्ञान के समान पवित्र करने वाला और कुछ नहीं है; योग में सिद्ध व्यक्ति उसे समय पर स्वयं, अपनी आत्मा में पाता है।",
         "“ज्ञान के समान पवित्र करने वाला कुछ नहीं है। तैयार योगी उसे समय पर अपने भीतर ही उठता हुआ पाता है।”"),
"4.39": ("श्रद्धावान, तत्पर, इन्द्रियों को वश में करने वाला पुरुष ज्ञान प्राप्त करता है; और ज्ञान प्राप्त करके वह शीघ्र ही परम शान्ति को प्राप्त होता है।",
         "“जिसमें श्रद्धा, लक्ष्य के प्रति समर्पण, और इन्द्रियों पर विजय है — वह ज्ञान पाता है; और ज्ञान के साथ गहरी, स्थायी शान्ति।”"),
"4.40": ("किन्तु अज्ञानी, श्रद्धा-रहित, सन्देह से भरा हुआ पुरुष नष्ट होता है; सन्देही आत्मा के लिए न यह लोक है, न परलोक, न सुख।",
         "“अज्ञानी और श्रद्धा-रहित, सन्देह से टूटे हुए लोग खो जाते हैं — सन्देही को यहाँ या परे, कहीं सुख नहीं।”"),
"4.41": ("योग द्वारा कर्मों का त्याग करने वाले, ज्ञान से सन्देह को नष्ट करने वाले, आत्मा में स्थित पुरुष को कर्म बाँधते नहीं, हे धनंजय।",
         "“जिसने योग से अपना कर्म समर्पण कर दिया है, जिसके सन्देह ज्ञान से कट गए हैं — उसे कुछ नहीं बाँध सकता, अर्जुन।”"),
"4.42": ("इसलिए हृदय में स्थित अज्ञान-जन्य इस सन्देह को ज्ञान-रूप तलवार से काटकर, योग में स्थिर होकर उठ, हे भारत!",
         "“इसलिए हृदय के सन्देह को ज्ञान की तलवार से काट, योग में अपना अडान ले — और उठ, अर्जुन!”"),
"5.01": ("अर्जुन ने कहा: हे कृष्ण, आप कर्म-संन्यास की प्रशंसा करते हैं, और कर्म-योग की भी; इन दोनों में से एक कौन-सा अच्छा है, निश्चय करके बताइए।",
         "अर्जुन पूछते हैं: “कृष्ण, आप कर्म त्यागने और कर्म को योग के रूप में करने — दोनों की प्रशंसा करते हैं; दोनों में से कौन अच्छा है, स्पष्ट बताइए।”"),
"5.02": ("श्री भगवान् ने कहा: संन्यास और कर्म-योग दोनों परम कल्याण के कारण हैं; किन्तु दोनों में से कर्म-योग कर्म-संन्यास से श्रेष्ठ है।",
         "कृष्ण ने कहा: “दोनों मार्ग मुक्ति देते हैं, किन्तु दोनों में से निःस्वार्थ कर्म का योग ही उत्तम है।”"),
"5.03": ("जो न द्वेष करता है न कामना — वह सदा संन्यासी जाना जानिए; द्वन्द्वों से रहित, हे महाबाहो, वह बन्धन से सहज ही मुक्त होता है।",
         "“सच्चा संन्यासी वह है जो राग-द्वेष से मुक्त है — सब द्वन्द्वों से परे, वह बन्धन से सहज ही निकल जाता है।”"),
"5.04": ("बालक ही, ज्ञानी नहीं, सांख्य और योग को भिन्न कहते हैं; एक में भी ठीक से स्थित व्यक्ति दोनों का फल पाता है।",
         "“अपरिपक्व लोग ही ज्ञान और कर्म को अलग मार्ग मानते हैं। किसी एक में सचमुच जड़ जमाओ, दोनों का फल मिलता है।”"),
"5.05": ("सांख्यों को प्राप्त होने वाला पद योगियों को भी मिलता है; जो सांख्य और योग को एक देखता है — वही सचमुच देखता है।",
         "“ज्ञान और कर्म एक ही लक्ष्य तक ले जाते हैं। जो उन्हें एक देखता है, वह सचमुच देखने वाला है।”"),
"5.06": ("किन्तु हे महाबाहो, योग के बिना संन्यास प्राप्त करना कठिन है; योग से युक्त मुनि शीघ्र ही ब्रह्म को प्राप्त होता है।",
         "“भीतरी योग के बिना कर्म त्यागना बहुत कठिन है; किन्तु कर्मयोगी शीघ्र ब्रह्म तक पहुँचता है।”"),
"5.07": ("कर्म-योग में तत्पर, शुद्ध आत्मा वाला, आत्म-विजयी, इन्द्रियों को जीतने वाला, सब प्राणियों का आत्मा — कर्म करते हुए भी वह लिप्त नहीं होता।",
         "“कर्मयोगी, शुद्ध और आत्म-संयमी, स्वयं को सब प्राणियों में देखने वाला — वह कर्म करते हुए भी कभी दागी नहीं होता।”"),
"5.08": ("'मैं कुछ भी नहीं करता' — तत्त्वज्ञ को ऐसे ही सोचना चाहिए, देखता, सुनता, छूता, सूँघता, खाता, चलता, सोता, श्वास लेता हुआ —",
         "“ज्ञानी सोचता है 'मैं कुछ नहीं करता' — देखते, सुनते, छूते, चखते, चलते, सोते, साँस लेते हुए भी,”"),
"5.09": ("बोलता, त्यागता, ग्रहण करता, आँखें खोलता और बंद करता हुआ — यह मानकर कि इन्द्रियाँ ही इन्द्रियों के विषयों में विचरती हैं।",
         "“बोलते, देते, लेते, आँखें खोलते और बंद करते हुए — यह जानकर कि केवल इन्द्रियाँ अपने विषयों से मिल रही हैं।”"),
"5.10": ("जो सब कर्म ब्रह्म में अर्पण करके, आसक्ति त्यागकर कर्म करता है — वह पाप से लिप्त नहीं होता, जैसे कमल का पत्ता जल से नहीं भीगता।",
         "“हर कर्म ब्रह्म में अर्पण करो और आसक्ति छोड़ दो — पाप तुझे छू नहीं सकता, जैसे जल कमल के पत्ते को नहीं भिगो सकता।”"),
"5.11": ("योगी शरीर, मन, बुद्धि या केवल इन्द्रियों द्वारा भी, आसक्ति त्यागकर, आत्म-शुद्धि के लिए कर्म करते हैं।",
         "“योगी शरीर, मन या इन्द्रियों से, बिना आसक्ति — केवल स्वयं को शुद्ध करने के लिए काम करते हैं।”"),
"5.12": ("योग में स्थित व्यक्ति कर्म-फल का त्याग करके स्थायी शान्ति पाता है; योग में न स्थित, इच्छा से प्रेरित, फल में आसक्त व्यक्ति बँध जाता है।",
         "“फल छोड़ने वाला योगी स्थिर शान्ति पाता है; फल से चिपका, मोह से चलाया गया व्यक्ति बँधा ही रहता है।”"),
"5.13": ("मन से ही सब कर्मों का त्याग करके, आत्म-संयमी देहधारी नौ द्वारों वाले नगर में सुख से रहता है — न कर्म करता है न कराता है।",
         "“आत्म-विजयी आत्मा शरीर — नौ द्वारों वाले नगर — में सुख से रहती है, मन में ही सब कर्म समर्पण करके, न कुछ करती है न कराती है।”"),
"5.14": ("भगवान् न लोक का कर्तृत्व बनाते हैं, न कर्म, न कर्म-फल का संयोग; प्रकृति ही कर्म करती है।",
         "“भगवान् न कर्तापन बनाते हैं, न कर्म, न फल — प्रकृति ही सब कुछ करती है।”"),
"5.15": ("सर्वव्यापी प्रभु न किसी का पाप ग्रहण करते हैं, न पुण्य; ज्ञान अज्ञान से आच्छादित है, और इसी से प्राणी मोहित होते हैं।",
         "“प्रभु किसी का पाप या पुण्य स्वीकार नहीं करते। अज्ञान ज्ञान को ढाँकता है, और इसीलिए प्राणी उलझन में पड़ते हैं।”"),
"5.16": ("किन्तु जिनका अज्ञान आत्म-ज्ञान से नष्ट हो चुका है, उनका वह ज्ञान सूर्य के समान चमककर परम तत्त्व को प्रकट करता है।",
         "“जब अज्ञान आत्म-ज्ञान से नष्ट होता है, ज्ञान सूर्य की तरह जलकर परम सत्य को दिखा देता है।”"),
"5.17": ("जिनकी बुद्धि उसमें है, आत्मा उसमें है, शरण उसमें है, लक्ष्य वही है — ज्ञान से पाप धोए हुए वे फिर नहीं लौटते।",
         "“जिनका सम्पूर्ण अस्तित्व ब्रह्म में टिका है, ज्ञान से शुद्ध हुए वे कभी नहीं लौटते — वे सदा के लिए मुक्त होते हैं।”"),
"5.18": ("ज्ञानी विद्या और विनय से युक्त ब्राह्मण, गाय, हाथी, कुत्ता और चाण्डाल को भी समान दृष्टि से देखते हैं।",
         "“समान दृष्टि से ज्ञानी विद्वान, गाय, हाथी, कुत्ता — और चाण्डाल — सबको एक जैसा देखते हैं।”"),
"5.19": ("जिनके मन समता में स्थित हैं, उन्होंने यहीं इस लोक में जन्म-मृत्यु को जीत लिया; ब्रह्म निष्कलंक और समान है — इसलिए वे ब्रह्म में स्थित होते हैं।",
         "“जिनके मन संतुलित हैं, उन्होंने यही संसार जीत लिया — क्योंकि ब्रह्म निष्कलंक और समान है, और वे उसी में बसते हैं।”"),
"5.20": ("प्रिय वस्तु पाकर न हर्षित होता है, अप्रिय पाकर न विचलित; स्थिर बुद्धि, अमोहित — ब्रह्मज्ञ वह ब्रह्म में ही स्थित रहता है।",
         "“सुख उसे उल्लसित नहीं करता, दुःख उसे विचलित नहीं करता — ब्रह्मज्ञ ब्रह्म में ही अचल खड़ा रहता है।”"),
"5.21": ("बाह्य संपर्कों में आसक्ति न रखकर, वह आत्मा में स्थित सुख पाता है; ब्रह्म-योग से युक्त होकर वह अविनाशी आनन्द भोगता है।",
         "“बाहरी सुखों से न चिपककर वह भीतर का आनन्द खोजता है — और ब्रह्म से एक होकर अमर आनन्द चखता है।”"),
"5.22": ("निश्चय ही इन्द्रिय-संपर्क से उत्पन्न सुख दुःख के ही गर्भ हैं; उनका आदि और अन्त होता है, हे कुन्तीपुत्र — ज्ञानी उनमें रमते नहीं।",
         "“इन्द्रिय-जन्य सुख केवल दुःख जन्माता है — वह आता-जाता है। ज्ञानी उसमें आनन्द नहीं लेते।”"),
"5.23": ("जो यहीं, शरीर त्यागने से पहले ही, कामना और क्रोध से उठने वाले वेग को सह सकता है — वह युक्त है, वह सुखी पुरुष है।",
         "“जो यहीं अभी, इच्छा और क्रोध के वेग को सह सकता है — वह सच्चा योगी है, सुखी आत्मा।”"),
"5.24": ("जो भीतर ही सुखी है, भीतर ही रमता है, भीतर ही प्रकाशित है — वह योगी, ब्रह्मभूत होकर, ब्रह्म-निर्वाण को प्राप्त होता है।",
         "“जिसका सुख, आनन्द और प्रकाश सब भीतर हैं — वह योगी, ब्रह्म से एक होकर, ब्रह्म में मुक्ति पाता है।”"),
"5.25": ("जिनके पाप नष्ट हैं, सन्देह कटे हैं, आत्मा वश में है, और जो सब प्राणियों के हित में रमते हैं — वे मुनि ब्रह्म-निर्वाण को प्राप्त होते हैं।",
         "“पाप से शुद्ध, सन्देह-रहित, आत्म-विजयी, सबके हित में लगे मुनि — वे ब्रह्म में मुक्ति पाते हैं।”"),
"5.26": ("इच्छा और क्रोध से मुक्त, मन को वश में करने वाले, आत्मा को जानने वाले यति के लिए — ब्रह्म-निर्वाण चारों ओर है।",
         "“इच्छा और क्रोध से मुक्त, मन पर विजय पाए, आत्मा को जानने वालों के लिए — ब्रह्म में मुक्ति निकट ही है।”"),
"5.27": ("बाह्य विषयों को बाहर फेंककर, दृष्टि को भ्रूमध्य में स्थिर कर, नासिका के भीतर प्राण और अपान की गति को समान करके —",
         "“बाहरी विषयों से हटकर, दृष्टि भौंहों के बीच रखकर, श्वास को समान और संतुलित बहाकर —”"),
"5.28": ("— इन्द्रियों, मन और बुद्धि को वश में कर, मुक्ति में तत्पर, इच्छा, भय और क्रोध से रहित मुनि — वह सदा मुक्त है।",
         "“— आत्म-संयमी, मोह, भय और क्रोध से मुक्त, मुक्ति के लिए समर्पित मुनि — वह सदा के लिए स्वतंत्र है।”"),
"5.29": ("मुझे यज्ञों और तपों का भोक्ता, सब लोकों का महान् स्वामी, सब प्राणियों का मित्र जानकर — वह शान्ति को प्राप्त होता है।",
         "“मुझे सब अर्पणों को ग्रहण करने वाला, सब लोकों का स्वामी, हर प्राणी का मित्र जानकर — तुझे शान्ति मिलेगी।”"),
"6.01": ("श्री भगवान् ने कहा: जो फल की आशा के बिना अपने कर्तव्य-कर्म को करता है — वही संन्यासी भी है और योगी भी; वह नहीं जो केवल अग्नि और क्रिया से रहित है।",
         "कृष्ण ने कहा: “जो फल से न चिपककर अपना कर्तव्य करता है — वह सच्चा संन्यासी और योगी दोनों है — न कि केवल अनुष्ठान छोड़ देने वाला।”"),
"6.02": ("हे पाण्डुपुत्र, जिसे संन्यास कहते हैं, उसे ही योग जान; क्योंकि संकल्प का त्याग किए बिना कोई योगी नहीं होता।",
         "“जिसे लोग संन्यास कहते हैं, वही योग है — स्वार्थी योजना न छोड़े कोई योगी नहीं हो सकता।”"),
"6.03": ("योग में चढ़ना चाहने वाले मुनि के लिए कर्म ही साधन कहा जाता है; चढ़ चुके के लिए शान्ति (उपरम) ही साधन कही जाती है।",
         "“योग की ओर चढ़ने के लिए कर्म ही मार्ग है; एक बार स्थापित होने पर भीतरी शान्ति ही मार्ग बन जाती है।”"),
"6.04": ("जब पुरुष न विषयों में आसक्त होता है न कर्मों में, और सब संकल्पों को त्याग चुका होता है — तब वह योग में चढ़ा हुआ कहा जाता है।",
         "“जब तू न भोगों से चिपकता है न काम से, सब स्वार्थी लक्ष्य छोड़कर — तब तू सचमुच योग में उठ चुका है।”"),
"6.05": ("आत्मा द्वारा आत्मा को उठाए, और आत्मा को न गिराए; क्योंकि आत्मा ही आत्मा का मित्र है, और आत्मा ही आत्मा का शत्रु है।",
         "“अपने आपको अपनी ही आत्मा से ऊपर उठा, कभी डूबने मत दे। आत्मा तेरा अपना सबसे अच्छा मित्र है — या सबसे बड़ा शत्रु।”"),
"6.06": ("जिसने आत्मा द्वारा आत्मा को जीत लिया है, उसके लिए आत्मा मित्र है; किन्तु जिसने आत्मा को नहीं जीता, उसके लिए आत्मा शत्रु के समान विरोधी रहता है।",
         "“स्वयं को जीत — आत्मा मित्र बनती है; स्वयं को न जीत — आत्मा शत्रु बन जाती है।”"),
"6.07": ("आत्म-जित, शान्त पुरुष परमात्मा में स्थित होता है — सर्दी-गर्मी, सुख-दुःख, मान-अपमान में समान।",
         "“आत्म-विजयी मुनि, शान्त और संतुलित, सर्दी-गर्मी, सुख-दुःख, प्रशंसा-निन्दा में एक-सा रहता है।”"),
"6.08": ("जो ज्ञान और विज्ञान में संतुष्ट, अचल, इन्द्रियों को जीतने वाला है, जिसके लिए मिट्टी, पत्थर और सोना समान हैं — वह युक्त कहलाता है।",
         "“ज्ञान में संतुष्ट, स्थिर, इन्द्रियों को वश में किए हुए, मिट्टी, पत्थर और सोने को एक-सा देखने वाला — ऐसा व्यक्ति सचमुच योग से जुड़ा है।”"),
"6.09": ("जो हितैषी, मित्र, शत्रु, उदासीन, मध्यस्थ, घृणा करने वाले, नातेदार और धार्मिक — सबके प्रति समान है, वही श्रेष्ठ है।",
         "“मित्र और शत्रु, तटस्थ और विरोधी, अपने और पराए — सबको समान देखने वाला — ऐसा व्यक्ति सबसे ऊँचा है।”"),
"6.10": ("योगी को एकान्त स्थान में, अकेला, मन और आत्मा को वश में करके, आशा और परिग्रह से रहित होकर निरन्तर अभ्यास करना चाहिए।",
         "“एकान्त स्थान पर अकेले योग का अभ्यास कर — मन और हृदय वश में, मोह और ममता से मुक्त।”"),
"6.11": ("शुद्ध भूमि में अपने लिए स्थिर आसन स्थापित कर — न बहुत ऊँचा न बहुत नीचा — वस्त्र, मृग-छाला और कुश से आच्छादित,",
         "“स्वच्छ स्थान में दृढ़ आसन बना — न ऊँचा न नीचा — कपड़े, खाल और पवित्र घास से बिछाकर —”"),
"6.12": ("मन को एकाग्र करके, मन और इन्द्रियों की क्रियाओं को रोककर, उस आसन पर बैठकर आत्म-शुद्धि के लिए योग का अभ्यास करे।",
         "“वहाँ बैठकर मन को केन्द्रित कर, विचार और इन्द्रियों को शान्त कर, और अपने को शुद्ध करने के लिए योग का अभ्यास कर।”"),
"6.13": ("शरीर, सिर और गर्दन को सीधा और अचल रखकर, अपनी नासिका के अग्र भाग पर दृष्टि स्थिर कर, चारों ओर न देखता हुआ,",
         "“शरीर, सिर और गर्दन सीधी और स्थिर रख; दृष्टि नाक की नोक पर गड़ा, बिना इधर-उधर देखे —”"),
"6.14": ("प्रसन्न मन, निर्भय, ब्रह्मचर्य-व्रत में दृढ़, मन को वश में किए, मुझमें ही चित्त लगाए — युक्त योगी मुझमें तत्पर होकर बैठे।",
         "“शान्त और निर्भय, संयमी और आत्म-नियंत्रित, मुझ पर ही चित्त रखकर — मेरी भक्ति में बैठकर ध्यान कर।”"),
"6.15": ("इस प्रकार सदा आत्मा को संयत करते हुए, वश में किए मन वाला योगी मुझ में स्थित निर्वाण की शान्ति को प्राप्त होता है।",
         "“इस प्रकार अभ्यास करते हुए, शान्त मन का योगी मुझ में विश्राम करने वाली मुक्ति की शान्ति पाता है।”"),
"6.16": ("हे अर्जुन, न अधिक खाने वाला योग को पाता है, न बिल्कुल न खाने वाला; न अधिक सोने वाला, न अधिक जागने वाला।",
         "“योग न अधिक खाने वाले का है, न भूखा रहने वाले का; न अधिक सोने वाले का, न कभी न सोने वाले का — हर बात में संतुलन, अर्जुन।”"),
"6.17": ("जो आहार और विहार में संयमित है, कर्मों में संयमित है, निद्रा और जागरण में संयमित है — उसके लिए योग दुःख का नाश करने वाला बन जाता है।",
         "“खाने, आराम, काम और नींद में संतुलित — ऐसे व्यक्ति के लिए योग सब कष्ट पिघला देता है।”"),
"6.18": ("जब सुसंस्कृत मन आत्मा में ही स्थिर होता है, सब कामनाओं के विषयों से निःस्पृह होता है — तब वह युक्त कहलाता है।",
         "“जब प्रशिक्षित मन आत्मा में ही बसता है, हर लोभ से मुक्त — वही योग में सचमुच स्थापित होना है।”"),
"6.19": ("जैसे हवा रहित स्थान में रखा दीपक नहीं चमकता-धमकता — ऐसा ही संयत मन वाले, आत्म-योग का अभ्यास करने वाले योगी का दृष्टान्त कहा गया है।",
         "“जैसे हवा न लगने वाले स्थान का दीपक कभी नहीं डगमगाता — वैसा ही होता है आत्मा में शान्त मन वाला योगी।”"),
"6.20": ("जिसमें योगाभ्यास से मन शान्त हो जाता है, और आत्मा द्वारा आत्मा को देखकर पुरुष आत्मा में ही संतुष्ट होता है —",
         "“जब अभ्यास से मन शान्त होता है, और भीतर की आत्मा को देखकर तू अपनी ही आत्मा में रमता है —”"),
"6.21": ("— जिसे इन्द्रियों से परे बुद्धि द्वारा ग्रहण करके अनन्त सुख के रूप में जाना जाता है, और जिसमें स्थित होकर पुरुष सत्य से विचलित नहीं होता —",
         "“— जब तू इन्द्रियों से परे उस असीम आनन्द को चखता है, और कोई वस्तु तुझे उससे हिला नहीं सकती —”"),
"6.22": ("— जिसे पाकर कोई अन्य लाभ श्रेष्ठ नहीं लगता, जिसमें बड़ा दुःख भी विचलित नहीं करता — वह अवस्था योग है, दुःख-संयोग का विच्छेद।",
         "“— ऐसा लाभ जिससे परे कुछ मायने नहीं रखता, गहरे शोक से भी न हिलने वाला — वही योग है, सब शोक का अन्त।”"),
"6.23": ("दुःख-संयोग के विच्छेद रूप उस योग को दृढ़ संकल्प और निरुत्साहित मन से अभ्यास करना चाहिए।",
         "“इस योग का — जो तुझे शोक से अलग करता है — दृढ़ संकल्प और अथक हृदय से अभ्यास कर।”"),
"6.24": ("संकल्प से उत्पन्न सब कामनाओं को पूर्णतः त्यागकर, मन द्वारा ही चारों ओर से सम्पूर्ण इन्द्रिय-समूह को रोककर —",
         "“सब कल्पित इच्छाओं को छोड़; मन से ही हर इन्द्रिय को काबू में ले —”"),
"6.25": ("— धीरे-धीरे, क्रम से, धैर्य से दृढ़ बुद्धि द्वारा शान्त होता जाए; और मन को आत्मा में ही स्थिर करके कुछ और न सोचे।",
         "“— क्रमशः, संकल्प से दृढ़ बुद्धि द्वारा मन को आत्मा में विश्राम दे — और कुछ और न सोच।”"),
"6.26": ("चंचल, अस्थिर मन जिस-जिस कारण से भटककर जाता है, उसी से उसे लौटाकर आत्मा के वश में लाए।",
         "“बेचैन मन जहाँ-जहाँ भटकता है, वहीं से बार-बार लौटाकर आत्मा के नियंत्रण में ला।”"),
"6.27": ("जिसका मन शान्त है, रज शान्त हुआ है, जो ब्रह्मभूत और निष्पाप हो गया है — उस योगी को निश्चय ही परम आनन्द प्राप्त होता है।",
         "“बड़ा आनन्द मिलता है उस योगी को — जिसका मन शान्त, कामनाएँ शान्त, जो ब्रह्मभूत और निष्कलंक हो चुका है।”"),
"6.28": ("इस प्रकार सदा आत्मा को संयत करने वाला, निष्पाप योगी ब्रह्म-संयोग के अनन्त सुख को सहज ही प्राप्त होता है।",
         "“इस प्रकार सदा अभ्यास करने वाला, शुद्ध योगी ब्रह्म के मिलन का असीम आनन्द सहज ही पाता है।”"),
"6.29": ("सब प्राणियों में आत्मा और आत्मा में सब प्राणियों को देखने वाला, सब में समान दृष्टि रखने वाला — वह परम तत्त्व को प्राप्त होता है।",
         "“सब में आत्मा और आत्मा में सब देखने वाला, सर्वत्र एक ही देखने वाला — ऐसा व्यक्ति सर्वोच्च तक पहुँचता है।”"),
"6.30": ("जो मुझे सर्वत्र देखता है और सब कुछ मुझ में देखता है — उसके लिए मैं नष्ट नहीं होता, और वह मेरे लिए नष्ट नहीं होता।",
         "“जो मुझे सब में और सब को मुझ में देखता है — मैं उसे कभी नहीं छोड़ता, और वह मुझे कभी नहीं छोड़ता।”"),
"6.31": ("एकत्व में स्थित, सब प्राणियों में विद्यमान मेरी ही पूजा करने वाला योगी — उसी में रहकर, जैसी भी जीवन-शैली हो, वह मुझ में ही रहता है।",
         "“जो योगी मुझे सब प्राणियों में देखता है और वहीं पूजा करता है — वह जो भी करता है, मुझ में ही रहता है।”"),
"6.32": ("आत्म-सादृश्य से सुख और दुःख में सर्वत्र समान देखने वाला — हे अर्जुन, वही परम योगी माना जाता है।",
         "“जो दूसरों के सुख-दुःख को अपने जैसा अनुभव करता है, सबको समान देखता है — वही महान् योगी है, अर्जुन।”"),
"6.33": ("अर्जुन ने कहा: हे मधुसूदन, आपके द्वारा कहा गया यह समत्व-योग — चंचलता के कारण मैं इसकी कोई स्थिर नींव नहीं देखता।",
         "अर्जुन पूछते हैं: “आपके वर्णित समबुद्धि के इस योग की — मैं नहीं देखता कि यह कैसे टिकेगा, क्योंकि मन इतना बेचैन है।”"),
"6.34": ("हे कृष्ण, मन निश्चय ही चंचल, आवेगी, बलवान् और अडिग है; मैं समझता हूँ कि इसे रोकना वायु को रोकने के समान कठिन है।",
         "“मन जंगली, उथल-पुथल, ज़िद्दी और बलवान् है — मुझे लगता है इसे काबू करना हवा पकड़ने जैसा कठिन है।”"),
"6.35": ("श्री भगवान् ने कहा: हे महाबाहो, मन चंचल और रोकने में कठिन है — इसमें सन्देह नहीं; किन्तु हे कुन्तीपुत्र, अभ्यास और वैराग्य से इसे रोका जा सकता है।",
         "कृष्ण ने कहा: “हाँ, मन चंचल और वश में करना कठिन है — किन्तु अभ्यास और वैराग्य से इसे जीता जा सकता है।”"),
"6.36": ("जिसने आत्मा को वश में नहीं किया, उसके लिए योग कठिन है — मेरा यह मत है; किन्तु आत्म-संयमी, उचित साधन से प्रयत्न करने वाला इसे प्राप्त कर सकता है।",
         "“आत्म-संयम के बिना योग बहुत कठिन है; किन्तु आत्म-नियंत्रित और उचित प्रयास करने वाला इसे पा लेगा।”"),
"6.37": ("अर्जुन ने कहा: हे कृष्ण, जो श्रद्धा से भरा पर स्वयं को वश में न कर सका, जिसका मन योग से च्युत हो गया — योग में सिद्धि न पाकर — वह किस गति को प्राप्त होता है?",
         "अर्जुन पूछते हैं: “जो श्रद्धा से प्रयास करता है पर असफल हो जाता है — सिद्धि तक पहुँचने से पहले ही जिसका मन योग से गिर जाता है — उसका क्या होता है, कृष्ण?”"),
"6.38": ("हे महाबाहो, दोनों से च्युत होकर, बिना आधार, ब्रह्म के मार्ग में मोहित होकर — क्या वह छिन्न बादल के समान नष्ट नहीं होता?",
         "“दोनों लोकों से खोकर — क्या वह टूटे बादल की तरह नष्ट हो जाता है, कुछ न थामते हुए, ब्रह्म के मार्ग में भ्रमित?”"),
"6.39": ("हे कृष्ण, आपको ही मेरा यह सन्देह पूर्णतः दूर करना चाहिए; इस सन्देह को नष्ट करने वाला आपके अतिरिक्त और कोई नहीं दिखता।",
         "“कृपया मेरा यह सन्देह पूरा हटाइए, कृष्ण — इसका समाधान करने वाला और कोई नहीं है।”"),
"6.40": ("श्री भगवान् ने कहा: हे पार्थ, न इस लोक में न परलोक में उसका विनाश होता है; क्योंकि हे पुत्र, शुभ कर्म करने वाला कोई दुर्गति को नहीं जाता।",
         "कृष्ण ने कहा: “कभी नहीं, अर्जुन — न यहाँ न मृत्यु के बाद — ऐसा व्यक्ति नष्ट नहीं होता। अच्छा करने वाला कोई बुरे अन्त तक नहीं पहुँचता।”"),
"6.41": ("पुण्य-कर्मियों के लोकों को प्राप्त कर, वहाँ असंख्य वर्षों तक निवास कर, योग से च्युत पुरुष शुद्ध और समृद्ध घर में फिर जन्म लेता है।",
         "“वह सत्पुरुषों के लोकों में युगों तक रहता है, फिर शुद्ध और भाग्यशाली परिवार में पुनर्जन्म लेता है।”"),
"6.42": ("अथवा वह बुद्धिमान् योगियों के घर में जन्म लेता है; सचमुच, ऐसा जन्म इस लोक में बहुत कठिनता से मिलता है।",
         "“या वह ज्ञानी योगियों के बीच जन्म लेता है — ऐसा जन्म इस संसार में पाना बहुत कठिन है।”"),
"6.43": ("हे कुरुनन्दन, वहाँ वह अपने पूर्व-शरीर की बुद्धि को फिर प्राप्त करता है, और वहीं से सिद्धि के लिए फिर प्रयत्न करता है।",
         "“वहाँ उसके पिछले जीवन का ज्ञान लौट आता है, और उसी बिन्दु से वह सिद्धि की ओर बढ़ता है।”"),
"6.44": ("उसी पूर्व-अभ्यास से वह अनिच्छा से भी आगे बढ़ता है; योग को जानने की इच्छा मात्र करने वाला भी वेद के शब्द से परे चला जाता है।",
         "“उसका पुराना अभ्यास उसे अनिच्छा से भी आगे बढ़ाता है — योग जानने की इच्छा मात्र भी शास्त्र के शब्द से परे ले जाती है।”"),
"6.45": ("किन्तु प्रयत्नपूर्वक अभ्यास करने वाला, पाप से शुद्ध, अनेक जन्मों से क्रमशः सिद्ध हुआ योगी तब परम अवस्था को प्राप्त होता है।",
         "“किन्तु ईमानदारी से प्रयास करने वाला, पाप से शुद्ध, अनेक जन्मों में परिपक्व हुआ योगी — वह सर्वोच्च लक्ष्य तक पहुँचता है।”"),
"6.46": ("योगी तपस्वी से श्रेष्ठ है, ज्ञानी से भी श्रेष्ठ माना जाता है, और कर्मकाण्डी से भी श्रेष्ठ; इसलिए हे अर्जुन, योगी बन।",
         "“योगी तपस्वी, विद्वान और अनुष्ठानी — सबसे ऊपर है। इसलिए, अर्जुन, योगी बन।”"),
"6.47": ("और सब योगियों में, जो श्रद्धा से भरकर, अपने अन्तरात्मा को मुझ में स्थिर करके मेरी पूजा करता है — मेरी दृष्टि में उसे ही मैं सबसे युक्त मानता हूँ।",
         "“और सब योगियों में, जो गहरी श्रद्धा से, अपने सम्पूर्ण अस्तित्व को मुझ में टिकाकर मेरी पूजा करता है — मेरी नज़र में वही सबसे बड़ा है।”"),
"7.01": ("श्री भगवान् ने कहा: हे पार्थ, मन को मुझ में आसक्त करके, योग का अभ्यास करके और मेरी शरण में आकर — तू कैसे, बिना किसी सन्देह, मुझे पूर्ण रूप से जानेगा, वह सुन।",
         "कृष्ण ने कहा: “मन मुझ पर लगा, योग का अभ्यास कर, मेरी शरण ले — तब तू मुझे पूरा जानेगा। वह कैसे, सुन।”"),
"7.02": ("मैं तुझे यह ज्ञान और इसका विज्ञान (साक्षात्कार) निःशेष रूप से बताऊँगा; इसे जानकर यहाँ जानने को और कुछ नहीं रह जाएगा।",
         "“मैं तुझे यह ज्ञान — इसके प्रत्यक्ष अनुभव के साथ — पूरा सिखाऊँगा। इसे जानकर सीखने को और कुछ नहीं बचता।”"),
"7.03": ("हज़ारों मनुष्यों में से कोई एक सिद्धि के लिए प्रयत्न करता है; और प्रयत्न करने वालों में से कोई एक मुझे सचमुच जानता है।",
         "“हज़ारों में से एक सिद्धि खोजता है; और सिद्ध होने वालों में से एक सचमुच मुझे जानता है।”"),
"7.04": ("पृथ्वी, जल, अग्नि, वायु, आकाश, मन, बुद्धि और अहंकार — इस प्रकार मेरी प्रकृति आठ भागों में विभक्त है।",
         "मिट्टी, पानी, आग, हवा, आकाश; और मन, बुद्धि तथा 'मैं' का भाव — ये आठ मेरी निचली प्रकृति हैं।"),
"7.05": ("यह अपर प्रकृति है; किन्तु हे महाबाहो, इससे परे मेरी दूसरी परा प्रकृति को जान — जीव-तत्त्व, जिससे यह संसार धारण किया हुआ है।",
         "“वह मेरी अपर प्रकृति है। किन्तु मेरी और भी उच्च प्रकृति है — जीवात्मा — जिससे यह सम्पूर्ण संसार टिका हुआ है।”"),
"7.06": ("इन दोनों प्रकृतियों को ही सब प्राणियों का गर्भ जान; मैं ही सम्पूर्ण जगत् का उत्पत्ति और विनाश हूँ।",
         "“सब कुछ मेरी इन्हीं दो प्रकृतियों से जन्मता है। मैं ही सम्पूर्ण ब्रह्माण्ड का स्रोत और अन्त हूँ।”"),
"7.07": ("हे धनंजय, मुझसे ऊँचा और कुछ नहीं है; यह सब मुझ पर गुँथा हुआ है — जैसे धागे में मोतियों की माला।",
         "“मुझसे परे कुछ नहीं है। यह सब मुझ पर गुँथा है, जैसे डोरी में पिरोए मणि।”"),
"7.08": ("हे कुन्तीपुत्र, मैं जल में रस हूँ; मैं चन्द्रमा और सूर्य का प्रकाश हूँ; सब वेदों में पवित्र अक्षर ॐ हूँ; आकाश में शब्द हूँ; पुरुषों में पौरुष हूँ।",
         "“मैं पानी का स्वाद हूँ, चन्द्रमा और सूर्य का प्रकाश, वेदों में ॐ, आकाश में ध्वनि, पुरुषत्व की शक्ति।”"),
"7.09": ("मैं पृथ्वी की शुद्ध गन्ध हूँ और अग्नि का तेज; सब प्राणियों का जीवन और तपस्वियों की तपस्या भी मैं ही हूँ।",
         "“मैं पृथ्वी की सुगन्ध हूँ, आग की गर्मी, सब प्राणियों का जीवन, तपस्वियों की तपस्या।”"),
"7.10": ("सब प्राणियों का शाश्वत बीज मुझे ही जान; मैं बुद्धिमानों की बुद्धि और तेजस्वियों का तेज हूँ।",
         "“मुझे सबका शाश्वत बीज जान — ज्ञानियों का ज्ञान, तेजस्वियों का तेज।”"),
"7.11": ("और मैं बलवानों का बल हूँ — कामना और आसक्ति से रहित; हे भरतश्रेष्ठ, प्राणियों में मैं धर्म-विरुद्ध न होने वाली कामना हूँ।",
         "“मैं बलवानों का बल हूँ — लोभ और मोह से रहित; और प्राणियों में धर्म से मेल खाने वाली इच्छा।”"),
"7.12": ("और जितनी भी सात्त्विक, राजस या तामस अवस्थाएँ हैं — उन सबको मुझसे ही उत्पन्न जान; किन्तु मैं उनमें नहीं, वे मुझ में हैं।",
         "“सब गुण — सत्त्व, रज, तम — मुझसे ही आते हैं। फिर भी मैं उनसे परे हूँ, यद्यपि वे मुझ में विश्राम करते हैं।”"),
"7.13": ("तीन गुणों से बनी इन अवस्थाओं से मोहित होकर, यह सम्पूर्ण संसार — उनसे परे, अविनाशी — मुझे नहीं जानता।",
         "“तीन गुणों से मोहित होकर संसार मुझे नहीं जानता — जो उनसे परे, नित्य हूँ।”"),
"7.14": ("गुणों से बनी मेरी यह दैवी माया पार करना कठिन है; किन्तु जो केवल मेरी शरण लेते हैं, वे इस माया से परे चले जाते हैं।",
         "“मेरी दिव्य माया पार करना कठिन है — किन्तु जो केवल मुझ में समर्पण करते हैं, वे इससे परे जाते हैं।”"),
"7.15": ("दुष्कर्मी, मोहित और नराधम मेरी शरण नहीं आते; माया से ज्ञान हरे हुए, आसुरी स्वभाव को धारण करते हैं।",
         "“दुष्ट, मोहित, पतित — माया से ज्ञान खोए और आसुरी स्वभाव वाले — मेरी ओर नहीं मुड़ते।”"),
"7.16": ("हे अर्जुन, चार प्रकार के शुभ-कर्मी मेरी पूजा करते हैं: दुःखी, ज्ञान का खोजी, अर्थ का खोजी और ज्ञानी।",
         "“चार प्रकार के अच्छे लोग मेरी पूजा करते हैं: दुःखी, जिज्ञासु, महत्त्वाकांक्षी और ज्ञानी।”"),
"7.17": ("उनमें ज्ञानी, सदा युक्त, एकनिष्ठ भक्त — वही सर्वोत्तम है; क्योंकि मैं ज्ञानी के लिए अत्यन्त प्रिय हूँ, और वह मेरे लिए प्रिय है।",
         "“उनमें सबसे ज्ञानी — सदा मुझसे एक, एकचित्त — उत्तम है। मैं उसके लिए गहरा प्रिय हूँ, और वह मेरे लिए।”"),
"7.18": ("ये सब उदार हैं; किन्तु ज्ञानी मेरा ही स्वरूप है, मेरी समझ में; क्योंकि वह, आत्मा में स्थित होकर, परम लक्ष्य मुझ में ही प्रतिष्ठित है।",
         "“चारों श्रेष्ठ हैं, किन्तु ज्ञानी मेरा ही स्वरूप है — परम लक्ष्य मुझ में ही स्थापित होकर।”"),
"7.19": ("अनेक जन्मों के अन्त में, ज्ञानी पुरुष 'वासुदेव ही सब कुछ है' — ऐसा जानकर मेरी शरण लेता है; वह महात्मा अत्यन्त दुर्लभ है।",
         "“अनेक जन्मों के बाद, ज्ञानी 'वासुदेव ही सब है' जानकर मेरे पास आते हैं — ऐसा महात्मा अत्यन्त दुर्लभ होता है।”"),
"7.20": ("जिनका ज्ञान कामनाओं से हर लिया गया है, वे अपने स्वभाव से बाध्य होकर, इस या उस विधि का अनुसरण करते हुए, अन्य देवताओं की शरण जाते हैं।",
         "“कामनाओं से बहाए गए लोग, अपनी प्रकृति से बँधकर, विभिन्न नियमों का पालन करते हुए दूसरे देवताओं की पूजा करते हैं।”"),
"7.21": ("कोई भी भक्त जिस देव-रूप को श्रद्धा से पूजना चाहता है, मैं उसी की उस श्रद्धा को स्थिर कर देता हूँ।",
         "जो जिस रूप को श्रद्धा से पूजना चाहे, उसी श्रद्धा को मैं मज़बूत कर देता हूँ।"),
"7.22": ("उस श्रद्धा से युक्त होकर वह उस देवता की पूजा में लग जाता है, और उससे अपने इच्छित पदार्थों को प्राप्त करता है — जो वास्तव में मुझ ही से नियत होते हैं।",
         "“उस श्रद्धा से वह पूजा करता है, और उसकी इच्छाएँ पूरी होती हैं — यद्यपि पूरी करने वाला मैं ही हूँ।”"),
"7.23": ("किन्तु उन पूजकों का फल सीमित है; वह फल अल्प-बुद्धि वालों का है। देवताओं के पूजक देवताओं को प्राप्त होते हैं; मेरे भक्त मुझे प्राप्त होते हैं।",
         "“किन्तु ऐसी पूजा केवल सीमित फल देती है। देव-पूजक देवताओं तक पहुँचते हैं; मेरे भक्त मुझ तक पहुँचते हैं।”"),
"7.24": ("अज्ञानी, मेरी परा प्रकृति — अविनाशी और अनुत्तम — को न जानकर, अव्यक्त मुझे व्यक्त रूप धारण किया हुआ मानते हैं।",
         "“मूर्ख मुझे — अव्यक्त — केवल प्रकट रूप मानते हैं, मेरी उच्च, नित्य प्रकृति को न जानकर।”"),
"7.25": ("योग-माया से आवृत्त होने के कारण मैं सबको प्रकट नहीं होता; यह मोहित संसार मुझे — अजन्मा, अविनाशी — नहीं जानता।",
         "“अपनी दिव्य शक्ति से छिपा हुआ, मैं सबको दिखाई नहीं देता; मोहित संसार मुझे — अजन्मा, नित्य — जानने में असफल रहता है।”"),
"7.26": ("हे अर्जुन, मैं बीते हुए, वर्तमान और आने वाले — सब प्राणियों को जानता हूँ; किन्तु मुझे कोई नहीं जानता।",
         "“मैं सब प्राणियों को जानता हूँ — भूत, वर्तमान और भविष्य। किन्तु मुझे सचमुच कोई नहीं जानता।”"),
"7.27": ("इच्छा और द्वेष से उत्पन्न द्वन्द्वों के मोह से, हे भरतवंशी, हे परंतप, सब प्राणी जन्म में ही मोह को प्राप्त होते हैं।",
         "“रुचि और अरुचि से जन्मे द्वन्द्व सब प्राणियों को जन्म से ही मोहित कर देते हैं।”"),
"7.28": ("किन्तु जिनके पाप समाप्त हो चुके हैं, शुभ-कर्म करने वाले वे पुरुष — द्वन्द्वों के मोह से मुक्त — दृढ़ व्रत से मेरी पूजा करते हैं।",
         "“जिनके पाप समाप्त हैं, जिनके कर्म शुभ हैं — द्वन्द्वों के मोह से मुक्त वे दृढ़ संकल्प से मेरी पूजा करते हैं।”"),
"7.29": ("जो बुढ़ापे और मृत्यु से मुक्ति के लिए प्रयत्न करते हुए मेरी शरण लेते हैं — वे ब्रह्म, सम्पूर्ण अध्यात्म और सब कर्म को जानते हैं।",
         "“जो बुढ़ापे और मृत्यु से मुक्ति चाहते हुए मेरी शरण लेते हैं — वे ब्रह्म, आत्मा और सम्पूर्ण कर्म को जानने लगते हैं।”"),
"7.30": ("जो मुझे भूत, देवता और यज्ञ के साथ जानते हैं — वे मृत्यु-काल में भी, स्थिर मन से, मुझे ही जानते हैं।",
         "“जो मुझे सब प्राणियों, सब देवताओं और सब यज्ञों में व्याप्त जानते हैं — मृत्यु की घड़ी में भी, स्थिर मन से, वे मुझे जानते हैं।”"),
"8.01": ("अर्जुन ने कहा: वह ब्रह्म क्या है, अध्यात्म क्या है, कर्म क्या है, हे पुरुषोत्तम? अधिभूत किसे कहा गया है, और अधिदैव किसे कहा जाता है?",
         "अर्जुन पूछते हैं: “ब्रह्म क्या है? आत्मा क्या है? कर्म क्या है, कृष्ण? अधिभूत और अधिदैव क्या हैं?”"),
"8.02": ("हे मधुसूदन, इस शरीर में अधियज्ञ कौन है और कैसे? और संयमी पुरुष मृत्यु-काल में आपको कैसे जान सकते हैं?",
         "“और इस शरीर में अधियज्ञ क्या है — और स्थिर मन वाले मृत्यु की घड़ी में आपको कैसे जान सकते हैं?”"),
"8.03": ("श्री भगवान् ने कहा: अविनाशी ब्रह्म ही परम तत्त्व है; अपना स्वभाव अध्यात्म कहलाता है; प्राणियों को उत्पन्न करने वाली सृष्टि-प्रेरणा कर्म कहलाती है।",
         "कृष्ण ने कहा: “अविनाशी ही परम ब्रह्म है; अपना अस्तित्व अध्यात्म है; और सृष्टि की प्रेरणा कर्म है।”"),
"8.04": ("अधिभूत क्षर (विनाशशील) स्वभाव है; पुरुष अधिदैवत है; हे देहधारियों में श्रेष्ठ, इस शरीर में मैं स्वयं अधियज्ञ हूँ।",
         "“विनाशशील संसार अधिभूत है; पुरुष अधिदैव है; और इस शरीर में मैं स्वयं अधियज्ञ हूँ।”"),
"8.05": ("जो अन्त-काल में केवल मुझे स्मरण करके शरीर का त्याग करता है — वह मेरी अवस्था को प्राप्त होता है; इसमें कोई सन्देह नहीं।",
         "“जो केवल मुझे स्मरण करके शरीर छोड़ता है, वह मेरे ही स्वरूप में आता है — इसमें कोई सन्देह नहीं।”"),
"8.06": ("शरीर त्यागते समय अन्त-काल में जिस-जिस अवस्था का स्मरण होता है, उसी अवस्था को प्राप्त होता है — उसी भाव से सदा व्याप्त होकर।",
         "“अन्तिम घड़ी में तू जो सोचता है, वही बन जाता है — उसी अन्तिम विचार से ढलकर।”"),
"8.07": ("इसलिए सब समय मुझे स्मरण करके युद्ध कर; मन और बुद्धि को मुझ में अर्पण करके, तू निश्चय ही मुझे प्राप्त होगा।",
         "“इसलिए सदा मुझे स्मरण करके युद्ध कर! मन और हृदय मुझे देकर, तू निश्चय मुझ तक पहुँचेगा।”"),
"8.08": ("अभ्यास-योग से युक्त, और कहीं न जाने वाली एकाग्र बुद्धि से — परम दिव्य पुरुष का चिन्तन करता हुआ — वह उसे प्राप्त होता है।",
         "“एकाग्र मन से अभ्यास करते हुए, परम दिव्य पुरुष का ध्यान करते हुए, योगी उन तक पहुँचता है।”"),
"8.09": ("जो प्राचीन ऋषि, शासक, सूक्ष्म से सूक्ष्म, सबका आधार, अचिन्त्य रूप, सूर्य के समान तेजस्वी, अन्धकार से परे — उसका ध्यान करता है —",
         "“जो प्राचीन द्रष्टा — सूक्ष्म से सूक्ष्म, सबका आधार, अचिन्त्य रूप, अन्धकार से परे चमकने वाला — उसका चिन्तन करने वाला —”"),
"8.10": ("— मृत्यु-काल में अविचलित मन, भक्ति और योग-शक्ति से युक्त, भ्रूमध्य में प्राण को स्थिर करके — वह उस परम दिव्य पुरुष को प्राप्त होता है।",
         "“— मृत्यु में स्थिर मन, भक्ति और योग-शक्ति से, भौंहों के बीच श्वास को रोककर — उस परम दिव्य पुरुष तक पहुँचता है।”"),
"8.11": ("वेदों के ज्ञाता जिसे अविनाशी कहते हैं, जिसमें इच्छा-रहित तपस्वी प्रवेश करते हैं, जिसकी इच्छा से वे ब्रह्मचर्य का पालन करते हैं — उस लक्ष्य को मैं तुझे संक्षेप में कहूँगा।",
         "“वेदों के ज्ञानी जिसे घोषित करते हैं, इच्छा-रहित तपस्वी जिसमें प्रवेश करते हैं — उस लक्ष्य को अब मैं तुझे संक्षेप में बताता हूँ।”"),
"8.12": ("शरीर के सब द्वारों को रोककर, मन को हृदय में बंद करके, प्राण को शिर में स्थिर करके, योग-धारणा में स्थित होकर —",
         "“शरीर के द्वार बंद करके, मन को हृदय में रखकर, श्वास को शिखर तक उठाकर — योग-समाधि में स्थित होकर —”"),
"8.13": ("— एकाक्षर ब्रह्म ॐ का उच्चारण करते हुए, और मुझे स्मरण करते हुए — जो शरीर का त्याग करके जाता है, वह परम लक्ष्य को प्राप्त होता है।",
         "“— एकाक्षर ॐ का जप करते हुए, मुझे स्मरण करते हुए — जो इस प्रकार शरीर छोड़ता है, वह परम लक्ष्य तक पहुँचता है।”"),
"8.14": ("हे पार्थ, जो सदा एकाग्र मन से मुझे निरन्तर स्मरण करता है — उस सदा-युक्त योगी के लिए मैं सरलता से प्राप्त होता हूँ।",
         "जो मन बाँटे बिना दिन-रात मुझे याद रखता है, उस सधे हुए योगी को मैं सहज ही मिल जाता हूँ।"),
"8.15": ("मुझे प्राप्त करके महात्मा फिर जन्म में नहीं लौटते — दुःख का घर, अनित्य — वे परम सिद्धि को प्राप्त हो चुके हैं।",
         "“मुझ तक पहुँचकर, महात्मा दुःख और परिवर्तन के इस संसार में फिर नहीं लौटते — वे परम सिद्धि तक पहुँच चुके हैं।”"),
"8.16": ("हे अर्जुन, ब्रह्म-लोक से नीचे के सब लोक फिर लौटते हैं; किन्तु हे कुन्तीपुत्र, मुझे प्राप्त करके पुनर्जन्म नहीं होता।",
         "“ब्रह्मा के लोक तक के सब संसार घूमकर लौटते हैं; किन्तु जो मुझ तक पहुँचता है, वह फिर जन्म नहीं लेता।”"),
"8.17": ("जो ब्रह्मा के दिन को हज़ार युगों में समाप्त होने वाला और रात को हज़ार युगों वाला जानते हैं — वे दिन-रात को जानते हैं।",
         "“जो जानते हैं कि हज़ार युग ब्रह्मा का दिन और हज़ार युग उनकी रात है — वे दिव्य समय का माप जानते हैं।”"),
"8.18": ("दिन के आगमन पर अव्यक्त से सब व्यक्त पदार्थ उत्पन्न होते हैं; रात के आगमन पर वे अव्यक्त में ही विलीन हो जाते हैं।",
         "“ब्रह्मा के दिन के उदय पर सब प्राणी अव्यक्त से उठते हैं; उनकी रात में फिर उसी में विलीन हो जाते हैं।”"),
"8.19": ("प्राणियों का यही समूह, बार-बार उत्पन्न होकर, रात के आगमन पर विलीन होता है, और दिन के आगमन पर फिर उत्पन्न होता है।",
         "“यह प्राणी-समूह बार-बार जन्मकर रात में पिघल जाता है और दिन के उदय पर फिर प्रकट होता है।”"),
"8.20": ("किन्तु इस अव्यक्त से परे एक और शाश्वत अव्यक्त है — जो सब प्राणियों के नष्ट होने पर भी नष्ट नहीं होता।",
         "इस अनदेखे से भी परे एक और है, सदा रहने वाला — सब कुछ मिट जाए तब भी जो नहीं मिटता।"),
"8.21": ("वही अव्यक्त अविनाशी कहलाता है; वे उसे परम लक्ष्य कहते हैं; जिसे पाकर नहीं लौटते — वही मेरा परम धाम है।",
         "“वही अविनाशी है, परम लक्ष्य। उसमें पहुँचकर कोई नहीं लौटता — वह मेरा सर्वोच्च निवास है।”"),
"8.22": ("हे पार्थ, वह परम पुरुष केवल अनन्य भक्ति से प्राप्त होता है; जिसमें सब प्राणी रहते हैं, और जिससे यह सब व्याप्त है।",
         "“वह परम पुरुष एकनिष्ठ भक्ति से पहुँचा जाता है; सब प्राणी उनमें रहते हैं, और वे सबको व्याप्त करते हैं।”"),
"8.23": ("हे भरतश्रेष्ठ, अब मैं उस समय को बताता हूँ जिसमें योगी, प्रस्थान करके, नहीं लौटते; और जिस समय लौटते हैं।",
         "“अब मैं तुझे, अर्जुन, प्रस्थान के समय बताता हूँ — न लौटने का मार्ग और लौटने का मार्ग।”"),
"8.24": ("अग्नि, ज्योति, दिन, शुक्ल पक्ष, उत्तरायण के छः महीने — उस मार्ग से जाने वाले ब्रह्म-ज्ञाता ब्रह्म को प्राप्त होते हैं।",
         "“अग्नि और प्रकाश के मार्ग से, दिन और शुक्ल पक्ष और उत्तरायण के — ब्रह्म-ज्ञाता इस मार्ग से ब्रह्म तक जाते हैं।”"),
"8.25": ("धूम, रात्रि, कृष्ण पक्ष, दक्षिणायन के छः महीने — उस मार्ग से चन्द्र-लोक की ज्योति को प्राप्त करके योगी लौटता है।",
         "“धूम और रात्रि के मार्ग से, कृष्ण पक्ष और दक्षिणायन के — इस मार्ग से योगी चन्द्र-लोक की ज्योति में पहुँचकर लौटता है।”"),
"8.26": ("ये दो मार्ग — शुक्ल और कृष्ण — संसार के सनातन मार्ग हैं; एक से बिना लौटे जाता है, दूसरे से फिर लौटता है।",
         "“ये दो मार्ग — उजला और अन्धकार — संसार में सनातन हैं। एक बिना लौटे ले जाता है, दूसरा लौटा लाता है।”"),
"8.27": ("हे पार्थ, इन दोनों मार्गों को जानकर योगी कभी मोहित नहीं होता; इसलिए, हे अर्जुन, सब समय योग में युक्त रह।",
         "“दोनों मार्गों को जानकर योगी कभी भ्रमित नहीं होता — इसलिए, अर्जुन, सदा योग में स्थिर रह।”"),
"8.28": ("वेदों, यज्ञों, तप और दान में जितना पुण्य-फल कहा गया है — उस सबको जानने वाला योगी उस सबसे ऊपर उठकर परम आदि धाम को प्राप्त होता है।",
         "“इस सत्य को जानने वाला योगी वेद, यज्ञ, तप और दान के सब पुण्यों से ऊपर उठता है — और परम, आदि निवास तक पहुँचता है।”"),
"9.01": ("श्री भगवान् ने कहा: दोष न देखने वाले तुझसे मैं यह सबसे गुह्य रहस्य कहूँगा — ज्ञान साक्षात्कार सहित; इसे जानकर तू पाप से मुक्त हो जाएगा।",
         "कृष्ण ने कहा: “क्योंकि तू ईमानदार है, अर्जुन, मैं तुझे सबसे गहरा रहस्य सिखाऊँगा — ज्ञान अपने प्रत्यक्ष अनुभव के साथ। इसे जानकर तू सब पाप से मुक्त हो जाएगा।”"),
"9.02": ("यह राज-विद्या है, राज-गुह्य है, परम पवित्र, प्रत्यक्ष अनुभव-योग्य, धर्म-युक्त, आचरण में अत्यन्त सरल और अविनाशी है।",
         "“यह ज्ञान और रहस्य का राजा है — सबसे शुद्ध, प्रत्यक्ष दिखने वाला, धर्म के अनुकूल, अपनाने में सरल और नित्य।”"),
"9.03": ("इस धर्म में श्रद्धा न रखने वाले पुरुष, हे परंतप, मुझे प्राप्त न होकर, मृत्यु और पुनर्जन्म के मार्ग में लौट जाते हैं।",
         "“इस शिक्षा में श्रद्धा न रखने वाले मृत्यु और पुनर्जन्म के मार्ग पर लौट जाते हैं, कभी मुझ तक नहीं पहुँचते।”"),
"9.04": ("मेरे अव्यक्त रूप से यह सम्पूर्ण जगत् मुझ से व्याप्त है; सब प्राणी मुझ में रहते हैं, किन्तु मैं उनमें समाहित नहीं हूँ।",
         "“मैं अपने अव्यक्त रूप से इस सम्पूर्ण संसार को व्याप्त करता हूँ। सब प्राणी मुझ में रहते हैं, फिर भी मैं उनमें नहीं रहता।”"),
"9.05": ("और प्राणी मुझ में नहीं रहते — मेरी दिव्य योग-शक्ति देख! मैं सब प्राणियों को धारण करता हूँ फिर भी अलग रहता हूँ, और मेरी आत्मा ही प्राणियों का उत्पत्ति-स्थान है।",
         "“प्राणी सचमुच मुझ में नहीं रहते — मेरी दिव्य शक्ति देख! मैं सब प्राणियों को धारण करता हूँ, फिर भी अलग रहता हूँ; मैं ही उनका स्रोत हूँ।”"),
"9.06": ("जैसे महान्, सदा चलने वाली वायु आकाश में रहती है, वैसे ही सब प्राणी मुझ में रहते हैं — यह जान।",
         "“जैसे बड़ी हवा हर जगह चलती है फिर भी आकाश में ही रहती है, वैसे ही सब प्राणी मुझ में रहते हैं — यह समझ।”"),
"9.07": ("हे कुन्तीपुत्र, कल्प के अन्त में सब प्राणी मेरी प्रकृति में लौट जाते हैं; कल्प के आरम्भ में मैं उन्हें फिर से उत्पन्न करता हूँ।",
         "“ब्रह्माण्डीय युग के अन्त में सब प्राणी मेरी प्रकृति में विलीन हो जाते हैं; युग के उदय पर मैं उन्हें फिर भेजता हूँ।”"),
"9.08": ("अपनी ही प्रकृति को धारण करके, मैं इस सम्पूर्ण प्राणी-समूह को बार-बार उत्पन्न करता हूँ — प्रकृति की शक्ति में असहाय हुए।",
         "“अपनी प्रकृति से ही मैं इस सम्पूर्ण प्राणी-समूह को बार-बार प्रकट करता हूँ — प्रकृति के अधीन असहाय प्राणी।”"),
"9.09": ("हे धनंजय, ये कर्म मुझे बाँधते नहीं, क्योंकि मैं इन कर्मों में आसक्त न होकर, उदासीन होकर बैठा हूँ।",
         "“ये सब मुझे नहीं बाँधते, अर्जुन — मैं आसक्ति-रहित, बेपरवाह दर्शक की तरह अलग बैठा हूँ।”"),
"9.10": ("मेरे अधीन रहकर प्रकृति चर और अचर — सबको उत्पन्न करती है; इसी कारण, हे कुन्तीपुत्र, संसार घूमता रहता है।",
         "“मेरे निर्देशन में प्रकृति चल और अचल — सबका उत्पादन करती है; इसीलिए संसार घूमता रहता है।”"),
"9.11": ("मोहित लोग, मेरे परम अस्तित्व को न जानकर, मानव रूप धारण किए हुए मुझे तुच्छ दृष्टि से देखते हैं।",
         "“मूर्ख, मेरी उच्च प्रकृति को न देखकर, मानव शरीर लिए हुए मुझे नीची दृष्टि से देखते हैं।”"),
"9.12": ("व्यर्थ आशाओं, व्यर्थ कर्मों और व्यर्थ ज्ञान वाले, अविवेकी — वे मोहक, राक्षसी और आसुरी स्वभाव से चिपके रहते हैं।",
         "“उनकी आशाएँ, कर्म और विद्या सब व्यर्थ हैं; उलझकर खोकर वे भ्रमित, आसुरी प्रकृति का अनुसरण करते हैं।”"),
"9.13": ("किन्तु हे पार्थ, महात्मा दैवी प्रकृति की शरण लेकर, प्राणियों के अविनाशी स्रोत मुझे जानकर, अविभाजित मन से मेरी पूजा करते हैं।",
         "“किन्तु उदार आत्माएँ, अर्जुन, दैवी प्रकृति की ओर फिरकर एकचित्त होकर, सबके शाश्वत स्रोत मुझे जानकर मेरी पूजा करती हैं।”"),
"9.14": ("सदा मेरी स्तुति करते हुए, दृढ़ व्रत से प्रयत्न करते हुए, भक्ति से मुझे प्रणाम करते हुए, सदा युक्त होकर — वे मेरी पूजा करते हैं।",
         "“सदा मेरी प्रशंसा गाते हुए, दृढ़ संकल्प से प्रयास करते हुए, भक्ति में मुझे झुककर — सदा एक होकर वे मेरी पूजा करते हैं।”"),
"9.15": ("और अन्य ज्ञान-यज्ञ द्वारा — मुझे एक, अनेक और सर्वत्र मुख वाले विराट रूप में पूजकर — मेरी उपासना करते हैं।",
         "“और अन्य ज्ञान का अर्पण चढ़ाते हैं — मुझे एक, अनेक, और सब ओर फैले दिव्य रूप में पूजकर।”"),
"9.16": ("मैं क्रिया हूँ, मैं यज्ञ हूँ, मैं पितरों को दी जाने वाली स्वधा हूँ, मैं औषधि हूँ; मैं मन्त्र हूँ, मैं घी हूँ, मैं अग्नि हूँ, मैं आहुति हूँ।",
         "“मैं अनुष्ठान, अर्पण, पितृ-तर्पण, औषधि, मन्त्र, घी, अग्नि और दान — सब कुछ हूँ।”"),
"9.17": ("मैं इस जगत् का पिता, माता, धर्ता और पितामह हूँ; मैं जानने-योग्य वस्तु, पवित्र करने वाला, प्रणव ॐ, और ऋक्, साम तथा यजु हूँ।",
         "“मैं संसार का पिता और माता, उसका आधार और पितामह हूँ; मैं जानने-योग्य, पवित्रकर्ता, ॐ और तीनों वेद हूँ।”"),
"9.18": ("मैं लक्ष्य, धर्ता, स्वामी, साक्षी, आश्रय, शरण और मित्र हूँ; उत्पत्ति, विनाश, आधार, भण्डार और शाश्वत बीज हूँ।",
         "“मैं लक्ष्य, वाहक, स्वामी, साक्षी, घर, शरण और मित्र हूँ — सबका स्रोत, अन्त, विश्राम-स्थान, भण्डार और अमर बीज।”"),
"9.19": ("मैं ताप देता हूँ; मैं वर्षा को रोकता और बरसाता हूँ; मैं अमृत भी हूँ और मृत्यु भी; हे अर्जुन, मैं सत् भी हूँ और असत् भी।",
         "“मैं गर्मी देता हूँ; मैं वर्षा रोकता और बरसाता हूँ। मैं जीवन और मृत्यु, सत्ता और असत्ता हूँ, अर्जुन।”"),
"9.20": ("तीनों वेदों के ज्ञाता, सोम-पान करके, पाप से शुद्ध होकर, यज्ञ द्वारा मेरी पूजा करते हुए स्वर्ग का मार्ग माँगते हैं; इन्द्र-लोक को प्राप्त कर वे स्वर्ग के दिव्य सुख भोगते हैं।",
         "“वेदों के अनुष्ठानी, सोम पीकर और पाप से शुद्ध होकर, यज्ञ से मेरी पूजा करके स्वर्ग पाते हैं; इन्द्र के लोक में दिव्य आनन्द भोगते हैं।”"),
"9.21": ("विशाल स्वर्ग-लोक को भोगकर, पुण्य समाप्त होने पर वे मर्त्य-लोक में लौट आते हैं; इस प्रकार तीनों वेदों के धर्म का अनुसरण करते हुए, कामनाएँ चाहने वाले आते-जाते रहते हैं।",
         "“पुण्य समाप्त होने पर, विशाल स्वर्गीय सुख भोगकर, वे मर्त्य संसार में लौट आते हैं — कामना से बँधकर सदा आने-जाने वाले।”"),
"9.22": ("जो मुझे ही स्मरण करके, सदा युक्त होकर मेरी पूजा करते हैं — उन सदा-भक्तों के लिए, न मिली हुई वस्तु मैं स्वयं पूरी करता हूँ, और मिली हुई वस्तु की रक्षा करता हूँ।",
         "“जो एकनिष्ठ भक्ति से, सदा मुझ से एक होकर मेरी पूजा करते हैं — उनकी कमी मैं स्वयं पूरी करता हूँ और उनका धन सुरक्षित रखता हूँ।”"),
"9.23": ("अन्य देवताओं के भक्त होकर श्रद्धा से उनकी पूजा करने वाले भी — हे कुन्तीपुत्र — केवल मेरी ही पूजा करते हैं, यद्यपि विधि-पूर्वक नहीं।",
         "“दूसरे देवताओं के भक्त भी, श्रद्धा से उनकी पूजा करते हुए, वास्तव में मेरी ही पूजा करते हैं — यद्यपि उचित विधि से नहीं।”"),
"9.24": ("क्योंकि मैं ही सब यज्ञों का भोक्ता और स्वामी हूँ; किन्तु वे मुझे सचमुच नहीं जानते, और इसलिए पतित होते हैं।",
         "हर आहुति का भोक्ता और स्वामी मैं ही हूँ। पर वे यह पहचानते नहीं, इसीलिए फिसल जाते हैं।"),
"9.25": ("देवताओं के पूजक देवताओं को प्राप्त होते हैं; पितरों के पूजक पितरों को; भूतों के पूजक भूतों को; किन्तु मेरे पूजक मुझे प्राप्त होते हैं।",
         "“देव-पूजक देवताओं तक, पितृ-पूजक पितरों तक, भूत-पूजक भूतों तक पहुँचते हैं — किन्तु मेरे भक्त मुझ तक आते हैं।”"),
"9.26": ("जो भक्ति से मुझे एक पत्ता, एक फूल, एक फल या जल अर्पण करता है — शुद्ध हृदय का वह अर्पण मैं स्वीकार करता हूँ।",
         "“मुझे प्रेम से एक पत्ता, फूल, फल या जल दे — शुद्ध हृदय का वह अर्पण मैं ग्रहण करता हूँ।”"),
"9.27": ("हे कुन्तीपुत्र, जो-जो करता है, जो-जो खाता है, जो-जो अर्पण करता है, जो-जो दान देता है, जो-जो तप करता है — वह सब मेरे अर्पण के रूप में कर।",
         "“जो-जो करता है, खाता है, चढ़ाता है, दान देता है या तप करता है — सब मुझे अर्पण कर।”"),
"9.28": ("इस प्रकार तू शुभ-अशुभ फल देने वाले कर्मों के बन्धन से मुक्त हो जाएगा; संन्यास-योग से युक्त आत्मा होकर, मुक्त होकर — तू मुझे प्राप्त होगा।",
         "“ऐसा करके तू कर्म और उसके शुभ-अशुभ फलों के बन्धन से मुक्त हो जाता है; योग में त्याग करके, स्वतंत्र होकर — तू मुझ तक आता है।”"),
"9.29": ("मैं सब प्राणियों में समान हूँ; मेरा कोई प्रिय या अप्रिय नहीं है; किन्तु जो भक्ति से मेरी पूजा करते हैं — वे मुझ में हैं, और मैं उनमें हूँ।",
         "मेरा कोई चहेता या पराया नहीं; सब बराबर। पर जो प्रेम से पुकारता है, वह मुझ में बसता है और मैं उसमें।"),
"9.30": ("अति दुष्ट आचरण वाला पुरुष भी यदि एकनिष्ठ भक्ति से मेरी पूजा करता है, तो वह साधु ही माना जाना चाहिए, क्योंकि उसका संकल्प ठीक है।",
         "“सबसे दुष्ट व्यक्ति भी यदि अविभाजित प्रेम से मेरी पूजा करता है, तो उसे साधुओं में ही गिनना चाहिए — क्योंकि उसका संकल्प सही है।”"),
"9.31": ("वह शीघ्र ही धर्मात्मा हो जाता है और स्थायी शान्ति को प्राप्त होता है; हे कुन्तीपुत्र, निश्चय जान: मेरा भक्त कभी नष्ट नहीं होता।",
         "“वह शीघ्र ही धार्मिक बनता है और स्थायी शान्ति तक पहुँचता है। निश्चय जान: मेरा भक्त कभी बरबाद नहीं होता।”"),
"9.32": ("हे पार्थ, मेरी शरण लेने वाले — पाप-जन्म वाले, स्त्रियाँ, वैश्य और शूद्र भी — वे भी परम लक्ष्य को प्राप्त होते हैं।",
         "“मेरी शरण में आने वाले सब — नीच जन्म वाले, स्त्रियाँ, व्यापारी और मज़दूर भी — सर्वोच्च लक्ष्य तक पहुँचते हैं।”"),
"9.33": ("तो फिर पवित्र ब्राह्मण और समर्पित राजर्षि — उनकी बात ही क्या! इस अनित्य, सुख-रहित संसार में आकर मेरी पूजा कर।",
         "“तो शुद्ध ब्राह्मण और समर्पित राजा-ऋषि — उनकी बात ही क्या! इस क्षणभंगुर, शोकमय संसार में मेरी पूजा कर।”"),
"9.34": ("मन मुझ में लगा, मेरा भक्त बन, मुझे अर्पण कर, मुझे प्रणाम कर — इस प्रकार आत्मा को मुझ में युक्त करके, मुझ में ही तत्पर होकर, तू निश्चय ही मुझे प्राप्त होगा।",
         "“मन मुझ पर रख, मेरा भक्त बन, मेरी पूजा कर, मुझे प्रणाम कर — पूर्ण रूप से मुझ में समर्पित होकर, तू निश्चय मुझ तक पहुँचेगा।”"),
"10.01": ("श्री भगवान् ने कहा: हे महाबाहो, फिर सुन मेरे परम वचन, जो मैं तुझसे, जो मुझे प्रिय है, तेरे कल्याण की इच्छा से कहता हूँ।",
         "कृष्ण ने कहा: “फिर सुन, महाबाहु अर्जुन, मेरी सर्वोच्च शिक्षा — जो मैं प्रेम से, तेरे कल्याण के लिए देता हूँ।”"),
"10.02": ("न देवताओं के समूह न महर्षि मेरी उत्पत्ति को जानते हैं; क्योंकि मैं सब प्रकार से देवताओं और महर्षियों का आदि हूँ।",
         "“न देवता न महान् ऋषि जानते हैं कि मैं कहाँ से आया — मैं ही उन सबका स्रोत हूँ।”"),
"10.03": ("जो मुझे अजन्मा, आदि-रहित, जगत् का महान् स्वामी जानता है — मनुष्यों में अमोहित, वह सब पापों से मुक्त हो जाता है।",
         "“जो मुझे अजन्मा, आदि-रहित, सब लोकों का स्वामी जानता है — वह फिर कभी नहीं उलझता, और उसके सब पाप झड़ जाते हैं।”"),
"10.04": ("बुद्धि, ज्ञान, असम्मोह, क्षमा, सत्य, दम, शम — सुख, दुःख, भव, अभव, भय और अभय,",
         "“समझ, ज्ञान, स्पष्टता, धैर्य, सत्य, आत्म-संयम, शान्ति — सुख, शोक, जन्म, मृत्यु, भय और साहस,”"),
"10.05": ("अहिंसा, समता, संतोष, तप, दान, यश और अपयश — प्राणियों की ये विविध अवस्थाएँ मुझसे ही उत्पन्न होती हैं।",
         "“— अहिंसा, समदृष्टि, संतोष, तपस्या, दान, प्रसिद्धि और अपमान — प्राणियों के ये सब गुण मुझसे ही आते हैं।”"),
"10.06": ("सात महर्षि, चार प्राचीन मनु — मेरे मन से उत्पन्न — उन्हीं से इस जगत् के प्राणी उत्पन्न होते हैं।",
         "“सात प्राचीन ऋषि और चार मनु — मेरे ही विचार से जन्मे — उन्हीं से इस संसार के सब प्राणी उत्पन्न होते हैं।”"),
"10.07": ("जो मेरी इस विभूति और योग को सचमुच जानता है, वह अविचलित योग से मुझ से युक्त हो जाता है — इसमें कोई सन्देह नहीं।",
         "“जो सचमुच मेरी विभूतियों और मेरी शक्ति को जानता है, वह अटल योग से मुझ से जुड़ जाता है — इसमें कोई सन्देह नहीं।”"),
"10.08": ("मैं सबका स्रोत हूँ; सब कुछ मुझसे ही आगे बढ़ता है। यह जानकर ज्ञानी, भक्ति से भरकर, मेरी पूजा करते हैं।",
         "“मैं सबकी उत्पत्ति हूँ; सब मुझसे ही बहता है। ज्ञानी, यह जानकर, प्रेम से मेरी पूजा करते हैं।”"),
"10.09": ("उनके विचार मुझ में, जीवन मुझे समर्पित, एक-दूसरे को ज्ञान देते हुए, सदा मेरी ही चर्चा करते हुए — वे संतुष्ट और आनन्दित होते हैं।",
         "“मन मुझ पर, जीवन मुझे समर्पित, एक-दूसरे को सिखाते और सदा मेरी बातें करते हुए — वे तृप्त और प्रसन्न होते हैं।”"),
"10.10": ("उन्हें, सदा समर्पित, प्रेम से मेरी पूजा करने वालों को, मैं बुद्धि-योग देता हूँ — जिससे वे मुझे प्राप्त होते हैं।",
         "“सदा एक होकर भक्ति से मेरी पूजा करने वालों को मैं विवेक-योग देता हूँ — जिससे वे मुझ तक पहुँचते हैं।”"),
"10.11": ("उन पर दया करके, उनके हृदय में रहकर, मैं उनके अज्ञान-जन्य अन्धकार को ज्ञान के दीपक से नष्ट कर देता हूँ।",
         "“करुणा से, उनके भीतर रहकर, मैं उनके अज्ञान के अन्धकार को ज्ञान के उज्ज्वल दीपक से मिटा देता हूँ।”"),
"10.12": ("अर्जुन ने कहा: आप परम ब्रह्म, परम ज्योति, परम पवित्र हैं; नित्य दिव्य पुरुष, आदि देवता, अजन्मा और सर्वव्यापी।",
         "अर्जुन कहते हैं: “आप परम ब्रह्म, सर्वोच्च आश्रय, सबसे शुद्ध हैं; नित्य दिव्य पुरुष, पहले देवता, अजन्मा और सर्वत्र।”"),
"10.13": ("इस प्रकार ऋषि आपको कहते हैं — दिव्य ऋषि नारद, असित, देवल, व्यास — और आप स्वयं भी मुझसे कहते हैं।",
         "“सब ऋषि ऐसा कहते हैं — नारद, असित, देवल, व्यास — और आप स्वयं भी मुझे इसकी पुष्टि करते हैं।”"),
"10.14": ("हे केशव, आपके कहे यह सब मैं सत्य मानता हूँ; निश्चय ही, हे प्रभु, न देवता न दानव आपकी प्रकट अवस्था को जानते हैं।",
         "“आपके कहे सब पर मैं विश्वास करता हूँ, केशव। न देवता न दानव, हे प्रभु, जान सकते हैं कि आप कैसे प्रकट होते हैं।”"),
"10.15": ("हे परम पुरुष, आप स्वयं ही अपने आपको स्वयं जानते हैं — हे प्राणियों के स्रोत, प्राणियों के स्वामी, देवों के देव, जगत् के स्वामी!",
         "“केवल आप ही अपने आपको जानते हैं, हे सर्वोच्च पुरुष — सबके सृष्टिकर्ता, देवों के देव, ब्रह्माण्ड के स्वामी!”"),
"10.16": ("इन सब लोकों को व्याप्त करके रहने वाली आपकी दिव्य विभूतियाँ मुझसे बिना बाकी कहिए।",
         "“कृपया अपनी दिव्य विभूतियाँ पूरी बताइए — जिनसे आप इन सब लोकों को व्याप्त करके रहते हैं।”"),
"10.17": ("हे योगी, सदा आपका चिन्तन करता हुआ मैं आपको कैसे जानूँ? और हे प्रभु, किन-किन रूपों में आपका ध्यान करूँ?",
         "“सदा आपको स्मरण करते हुए मैं आपको कैसे जान सकता हूँ? किन-किन रूपों में, हे प्रभु, मैं आपका ध्यान करूँ?”"),
"10.18": ("हे जनार्दन, आपका योग और विभूति फिर, विस्तार से कहिए; आपका अमृत सुनते-सुनते मैं कभी तृप्त नहीं होता।",
         "“अपनी शक्ति और विभूतियाँ फिर, विस्तृत रूप से बताइए, जनार्दन — यह अमृत पीते-पीते मैं कभी नहीं अघाता।”"),
"10.19": ("श्री भगवान् ने कहा: हाँ, मैं तुझसे अपनी दिव्य विभूतियाँ कहूँगा — मुख्य-मुख्य, हे कुरुश्रेष्ठ; क्योंकि मेरे विस्तार का अन्त नहीं है।",
         "कृष्ण ने कहा: “मैं तुझे अपनी दिव्य विभूतियाँ बताऊँगा — मुख्य-मुख्य, अर्जुन; क्योंकि मेरे विस्तार का कोई अन्त नहीं है।”"),
"10.20": ("हे गुडाकेश, मैं सब प्राणियों के हृदय में रहने वाला आत्मा हूँ; मैं ही सब प्राणियों का आदि, मध्य और अन्त हूँ।",
         "“मैं सब प्राणियों के हृदय में बैठा आत्मा हूँ; मैं ही उनका आदि, मध्य और अन्त हूँ।”"),
"10.21": ("आदित्यों में मैं विष्णु हूँ; ज्योतियों में तेजस्वी सूर्य; मरुतों में मैं मरीचि हूँ; नक्षत्रों में मैं चन्द्रमा हूँ।",
         "“आदित्यों में मैं विष्णु; ज्योतियों में दहकता सूर्य; वायुओं में मरीचि; तारों में चन्द्रमा।”"),
"10.22": ("वेदों में मैं साम-वेद हूँ; देवताओं में मैं इन्द्र हूँ; इन्द्रियों में मैं मन हूँ; प्राणियों में मैं चेतना हूँ।",
         "वेदों में सामवेद मैं हूँ। देवताओं में इन्द्र, इन्द्रियों में मन, और प्राणियों के भीतर की चेतना — सब मैं।"),
"10.23": ("रुद्रों में मैं शंकर हूँ; यक्षों और राक्षसों में कुबेर; वसुओं में मैं अग्नि हूँ; पर्वतों में मेरु।",
         "रुद्रों में शिव मैं हूँ; धन के स्वामी कुबेर भी मैं; वसुओं में आग; और पहाड़ों में मेरु।"),
"10.24": ("हे पार्थ, पुरोहितों में मुझे मुख्य बृहस्पति जान; सेनापतियों में मैं स्कन्द हूँ; जलाशयों में मैं सागर हूँ।",
         "“पुरोहितों में मुझे बृहस्पति जान; सेनापतियों में स्कन्द; जल-निकायों में सागर।”"),
"10.25": ("महर्षियों में मैं भृगु हूँ; शब्दों में मैं एकाक्षर ॐ हूँ; यज्ञों में मैं जप-यज्ञ हूँ; स्थावरों में मैं हिमालय हूँ।",
         "“महर्षियों में मैं भृगु; वाणी में पवित्र ॐ; यज्ञों में मौन जप; स्थिरों में हिमालय।”"),
"10.26": ("सब वृक्षों में मैं अश्वत्थ हूँ; देवर्षियों में नारद; गन्धर्वों में चित्ररथ; सिद्धों में मुनि कपिल।",
         "सब पेड़ों में पीपल मैं हूँ। ऋषियों में नारद, आकाश के गायकों में चित्ररथ, और सिद्ध पुरुषों में कपिल।"),
"10.27": ("घोड़ों में अमृत से उत्पन्न उच्चैःश्रवा मुझे जान; गजराजों में ऐरावत; मनुष्यों में राजा।",
         "“घोड़ों में मैं उच्चैःश्रवा — अमृत से जन्मा; हाथियों में ऐरावत; मनुष्यों में उनका राजा।”"),
"10.28": ("अस्त्रों में मैं वज्र हूँ; गौओं में मैं कामधेनु हूँ; प्रजनन-कर्ताओं में मैं काम हूँ; सर्पों में वासुकि।",
         "“अस्त्रों में मैं वज्र; गौओं में इच्छापूर्ति करने वाली गौ; कामी लोगों में कामदेव; सर्पों में वासुकि।”"),
"10.29": ("सर्पों में मैं अनन्त हूँ; जलचरों में वरुण; पितरों में अर्यमा; नियन्ता-शासकों में यम।",
         "साँपों में शेषनाग मैं हूँ; पानी के जीवों में वरुण; पितरों में अर्यमा; और दण्ड देने वालों में यम।"),
"10.30": ("दैत्यों में मैं प्रह्लाद हूँ; गणना करने वालों में काल; पशुओं में मैं सिंह हूँ; पक्षियों में गरुड़।",
         "दैत्यों में प्रह्लाद मैं हूँ; गिनती में समय; जानवरों में सिंह; और पंछियों में गरुड़।"),
"10.31": ("पवित्र करने वालों में मैं वायु हूँ; शस्त्र-धारियों में मैं राम हूँ; मछलियों में मैं मकर हूँ; नदियों में गंगा।",
         "“पवित्र करने वालों में मैं वायु; हथियार उठाने वालों में राम; मछलियों में मकर; नदियों में गंगा।”"),
"10.32": ("हे अर्जुन, सृष्टियों में मैं आदि, मध्य और अन्त भी हूँ; विद्याओं में मैं अध्यात्म-विद्या हूँ; वादियों में तर्क।",
         "“सब सृष्टियों में मैं आदि, मध्य और अन्त हूँ; विद्याओं में आत्म-विद्या; वाद-विवाद में ठोस तर्क।”"),
"10.33": ("अक्षरों में मैं अकार हूँ; समासों में द्वन्द्व; मैं ही अक्षय काल हूँ; सब ओर मुख वाला विधाता मैं ही हूँ।",
         "“अक्षरों में मैं 'अ'; समासों में द्वन्द्व; मैं अनन्त काल हूँ; मैं सब ओर फिरा हुआ सृष्टिकर्ता हूँ।”"),
"10.34": ("मैं सब कुछ खा जाने वाला मृत्यु हूँ, और भविष्य में होने वाली वस्तुओं की उत्पत्ति; स्त्रियों में मैं कीर्ति, श्री, वाणी, स्मृति, मेधा, धृति और क्षमा हूँ।",
         "“मैं सब बहा ले जाने वाला मृत्यु और आने वाली वस्तुओं का स्रोत हूँ; स्त्रियों में कीर्ति, कृपा, वाक्पटुता, स्मरण, बुद्धि, स्थिरता और धैर्य।”"),
"10.35": ("सामों में मैं बृहत्-साम हूँ; छन्दों में गायत्री; महीनों में मैं मार्गशीर्ष हूँ; ऋतुओं में वसन्त।",
         "साम-गानों में सबसे बड़ा मैं हूँ; छन्दों में गायत्री; बारह महीनों में फ़सल पकने वाला; ऋतुओं में फूलता वसन्त।"),
"10.36": ("मैं जुआरियों का पासा हूँ; मैं तेजस्वियों का तेज हूँ; मैं विजय हूँ, मैं उद्यम हूँ; मैं सत्पुरुषों का सत्त्व हूँ।",
         "“मैं जुआरी की कला, तेजस्वी का तेज; मैं विजय और संकल्प हूँ; मैं सज्जन का सद्गुण हूँ।”"),
"10.37": ("वृष्णियों में मैं वासुदेव हूँ; पाण्डवों में अर्जुन; मुनियों में मैं व्यास हूँ; कवियों में कवि उशना।",
         "यादवों में कृष्ण मैं ही हूँ, और पाँच भाइयों में अर्जुन। मननशीलों में व्यास, और कवियों में उशना।"),
"10.38": ("मैं दण्ड देने वालों का दण्ड हूँ; विजय चाहने वालों में मैं नीति हूँ; मैं गोपनीय का मौन हूँ; ज्ञानियों में मैं ज्ञान हूँ।",
         "“मैं शासकों का राजदण्ड और विजयी की कूटनीति हूँ; मैं रहस्यों का मौन हूँ; ज्ञानियों में ज्ञान।”"),
"10.39": ("और जो-जो सब प्राणियों का बीज है, वह मैं हूँ, हे अर्जुन; चर हो या अचर, मुझसे रहित कोई प्राणी नहीं है।",
         "“जो बीज सब प्राणियों को जन्म देता है — वह मैं हूँ। चल हो या अचल, मुझसे अलग कुछ अस्तित्व में नहीं है।”"),
"10.40": ("हे परंतप, मेरी दिव्य विभूतियों का अन्त नहीं है; मेरी विभूति के विस्तार का यह केवल संक्षेप में कहा गया वर्णन है।",
         "“मेरी दिव्य विभूतियों का अन्त नहीं है, अर्जुन — उनके विशाल विस्तार का यह केवल छोटा-सा बयान है।”"),
"10.41": ("जो-जो प्राणी विभूतिशाली, तेजस्वी या शक्तिशाली है — उसे मेरे तेज के एक अंश से उत्पन्न जान।",
         "“जो-जो भव्य, चमकीला या शक्तिशाली है — उसे मेरे तेज के एक कण से उठा हुआ जान।”"),
"10.42": ("किन्तु हे अर्जुन, इस विस्तृत ज्ञान से क्या प्रयोजन? मैं अपने एक अंश से इस सम्पूर्ण जगत् को धारण किए खड़ा हूँ।",
         "“किन्तु यह सब विस्तृत जानने से क्या अर्थ, अर्जुन? मैं अपने एक अंश से इस सम्पूर्ण ब्रह्माण्ड को धारण किए हुए हूँ।”"),
"11.01": ("अर्जुन ने कहा: आत्मा के परम गुह्य विषय में आपके दया-पूर्ण वचनों से मेरा मोह मिट गया।",
         "अर्जुन कहते हैं: “आत्मा के सर्वोच्च रहस्य पर आपने कृपा करके कहा — उसी से मेरा भ्रम दूर हुआ।”"),
"11.02": ("हे कमल-नयन, प्राणियों की उत्पत्ति और विनाश मैंने आपसे विस्तार से सुना, और आपका अनन्त वैभव भी।",
         "“हे कमल-नयन प्रभु, सब प्राणियों का जन्म और नाश, और आपकी असीम महिमा — सब मैंने आपसे सुना।”"),
"11.03": ("हे परमेश्वर, जैसे आपने अपना वर्णन किया, हे पुरुषोत्तम, वैसे ही मैं आपका विश्व-रूप देखना चाहता हूँ।",
         "“जैसे आपने अपना वर्णन किया, हे सर्वोच्च प्रभु, मैं वही विश्व-रूप देखना चाहता हूँ।”"),
"11.04": ("हे प्रभु, यदि आप समझते हैं कि यह मुझसे देखा जा सकता है, तो हे योगेश्वर, मुझे अपना अविनाशी स्वरूप दिखाइए।",
         "“यदि आप मानते हैं कि मैं इसे देख सकता हूँ, तो हे योगेश्वर, मुझे अपना नित्य स्वरूप प्रकट कीजिए।”"),
"11.05": ("श्री भगवान् ने कहा: हे पार्थ, देख — मेरे सैकड़ों और हज़ारों रूप, अनेक प्रकार के और अनेक रंगों वाले।",
         "कृष्ण ने कहा: “अब देख, अर्जुन, मेरे सैकड़ों-हज़ारों रूप — अनेक प्रकार के और अनेक रंगों के।”"),
"11.06": ("हे भारत, आदित्यों, वसुओं, रुद्रों, अश्विनीकुमारों और मरुतों को देख; पहले कभी न देखे गए अनेक आश्चर्यों को देख।",
         "“सूर्य-देवताओं, वसुओं, रुद्रों, जुड़वाँ अश्विनों, आँधी-हवाओं को देख — तूने कभी न देखे आश्चर्य, अर्जुन।”"),
"11.07": ("हे गुडाकेश, अब यहाँ मेरे शरीर में चर और अचर — सम्पूर्ण ब्रह्माण्ड — एक साथ जमा देख, और जो और भी देखना चाहे वह भी।",
         "“मेरे शरीर में सम्पूर्ण ब्रह्माण्ड — चल और अचल — एक साथ देख, और जो-जो भी तू देखना चाहे।”"),
"11.08": ("किन्तु तू अपनी आँख से मुझे नहीं देख सकता; मैं तुझे दिव्य दृष्टि देता हूँ — मेरा दिव्य ऐश्वर्य देख।",
         "“तेरी मर्त्य आँख मुझे नहीं देख सकती — यह दिव्य दृष्टि ले और मेरी विश्व-रूपी शक्ति देख।”"),
"11.09": ("संजय ने कहा: हे राजन्, ऐसा कहकर, महान् योगेश्वर हरि ने पार्थ को अपना परम दिव्य रूप दिखाया।",
         "संजय वर्णन करते हैं: “ऐसा कहकर, हे राजा, महान् योगेश्वर कृष्ण ने अर्जुन को अपना सर्वोच्च विश्व-रूप प्रकट किया।”"),
"11.10": ("असंख्य मुख और नेत्र, असंख्य आश्चर्यमय दृश्य, असंख्य दिव्य आभूषण और उठाए हुए अस्त्र-शस्त्र सहित,",
         "“— अगणित मुख और नेत्र, गिनती से परे आश्चर्य, दिव्य आभूषण और चारों ओर उठे हुए अस्त्र सहित —”"),
"11.11": ("दिव्य मालाएँ और वस्त्र धारण किए, दिव्य सुगन्ध से विलेपित, सब आश्चर्यों से भरा — हर दिशा में मुख वाला अनन्त देव।",
         "“— दिव्य मालाओं और वस्त्रों से सजा, दिव्य सुगन्ध से विभूषित, हर दिशा में मुख वाला असीम देव।”"),
"11.12": ("यदि आकाश में एक साथ हज़ार सूर्यों का तेज उठे, तो भी वह उस महापुरुष के तेज के बराबर नहीं होगा।",
         "“यदि आकाश में हज़ार सूर्य एक साथ जल उठें, तो भी वह उस महान् व्यक्ति के वैभव के बराबर नहीं होगा।”"),
"11.13": ("वहाँ, देवों के देव के शरीर में, पाण्डुपुत्र ने सम्पूर्ण ब्रह्माण्ड को — एक किन्तु अनन्त रूपों में विभाजित — देखा।",
         "“वहाँ अर्जुन ने देवों के देव के शरीर में सम्पूर्ण ब्रह्माण्ड — एक किन्तु असीम रूप से विविध — देखा।”"),
"11.14": ("तब, आश्चर्य से भरकर, रोंगटे खड़े होने पर, धनंजय ने देव को सिर झुकाया, और हाथ जोड़कर बोला।",
         "“तब, आश्चर्य से अभिभूत, रोंगटे खड़े अर्जुन ने झुककर, हाथ जोड़कर कहा।”"),
"11.15": ("हे देव, मैं आपके शरीर में सब देवों और प्राणियों के समूहों को देखता हूँ; कमल पर बैठे ब्रह्मा को, और सब मुनियों और दिव्य सर्पों को देखता हूँ।",
         "“आपके शरीर में मैं सब देवों और हर प्रकार के प्राणियों को देखता हूँ — कमल-आसन पर बैठे ब्रह्मा को, मुनियों और दिव्य सर्पों को।”"),
"11.16": ("हे विश्व-रूप, मैं आपको असंख्य बाहुओं, उदरों, मुखों और नेत्रों सहित देखता हूँ — चारों ओर अनन्त; मैं आपका न आदि देखता हूँ, न मध्य, न अन्त।",
         "“हे विश्व-रूप, मैं आपको गिनती से परे बाहुओं, पेटों, मुखों और नेत्रों सहित देखता हूँ — सब दिशाओं में असीम; आपका न आदि, न मध्य, न अन्त।”"),
"11.17": ("मैं आपको मुकुट धारण किए, गदा और चक्र लिए, चारों ओर चमकते प्रकाश-पुञ्ज देखता हूँ — देखना कठिन, अग्नि और सूर्य के समान जलता, अप्रमेय।",
         "“मैं आपको मुकुट, गदा और चक्र सहित देखता हूँ — प्रकाश की ज्वाला, देख न सकने की हद तक दैदीप्यमान, अग्नि और सूर्य जैसा, अमापनीय।”"),
"11.18": ("आप अविनाशी, जानने योग्य परम वस्तु हैं; आप इस ब्रह्माण्ड के परम आश्रय हैं; आप धर्म के शाश्वत रक्षक — आदि पुरुष हैं, मैं ऐसा आपको मानता हूँ।",
         "“आप नित्य, जानने योग्य सर्वोच्च हैं; आप ब्रह्माण्ड के परम धाम, धर्म के अपरिवर्तनीय रक्षक — आदि पुरुष हैं।”"),
"11.19": ("आदि, मध्य और अन्त से रहित, अनन्त शक्ति वाले, असंख्य बाहुओं वाले, सूर्य-चन्द्र नेत्रों वाले — मैं आपको अग्नि-जैसे मुखों से, अपने तेज से सम्पूर्ण जगत् को जलाते देखता हूँ।",
         "“आदि-अन्त से रहित, असीम शक्ति, अगणित बाहु, सूर्य-चन्द्र नेत्र — मैं आपको अग्नि-जैसे मुखों से अपने तेज से संसार को जलाते देखता हूँ।”"),
"11.20": ("पृथ्वी और आकाश के बीच का आकाश और सब दिशाएँ आपसे ही भरी हैं; आपका भयंकर, अद्भुत रूप देखकर तीनों लोक काँपते हैं, हे महात्मा।",
         "“स्वर्ग और पृथ्वी के बीच, हर दिशा में, आप अकेले ही सब कुछ भरते हैं — और तीनों लोक आपके भयानक रूप से काँपते हैं।”"),
"11.21": ("देवताओं के समूह आप में प्रवेश करते हैं; कोई, डरकर, हाथ जोड़कर आपकी स्तुति करते हैं; महर्षियों और सिद्धों के समूह आपके स्तोत्र गाते हैं।",
         "“देवताओं की सेनाएँ आप में बहती हैं; कोई, त्रस्त होकर, जुड़े हाथों से आपकी महिमा गाते हैं; ऋषि और सिद्ध पवित्र स्तोत्रों से आपकी प्रशंसा करते हैं।”"),
"11.22": ("रुद्र, आदित्य, वसु, साध्य, विश्वेदेव, अश्विनीकुमार, मरुत और पितर — गन्धर्व, यक्ष, दानव और सिद्ध — सब आश्चर्यचकित होकर आपको देखते हैं।",
         "“देवताओं के सब वर्ग — रुद्र, सूर्य-देवता, वसु और शेष — दिव्य गायकों और आत्माओं के साथ — सब चकित होकर आपको देखते हैं।”"),
"11.23": ("हे महाबाहो, अनेक मुख, नेत्र, अनेक उदर और अनेक भयानक दाँतों वाला आपका विशाल रूप देखकर लोक काँपते हैं — और मैं भी।",
         "“आपके विशाल रूप — अनेक मुख, नेत्र, पेट और भयानक दाँतों सहित — को देखकर लोक काँपते हैं, हे महाबाहो, और मैं भी।”"),
"11.24": ("आकाश को छूने वाला, देदीप्यमान, अनेक रंगों वाला, खुले मुखों और देदीप्यमान विशाल नेत्रों वाला — आपको देखकर मेरा अन्तर हृदय काँपता है; मुझे न स्थिरता मिलती है न शान्ति, हे विष्णु।",
         "आकाश को छूते, देदीप्यमान, अनेक रंगों वाले रूप को — खुले मुख, चौड़ी जलती आँखें — देखकर मेरा हृदय काँप उठता है; मुझे न स्थिरता मिलती है न शान्ति, हे विष्णु।"),
"11.25": ("प्रलयकाल की अग्नि के समान जलते, भयानक दाँतों वाले आपके भयंकर मुख देखकर, मैं दिशाएँ नहीं पहचानता, और न कोई शरण पाता हूँ; हे देवों के स्वामी, जगत् के आश्रय, कृपा कीजिए।",
         "विनाश-काल की अग्नि की तरह दहकते, भयानक दाँतों वाले मुख देखकर, मैं दिशा ही नहीं पहचानता और न कोई शरण पाता हूँ; कृपा कीजिए, हे देवों के स्वामी।"),
"11.26": ("धृतराष्ट्र के ये सब पुत्र, राजाओं के समूहों सहित, आपके मुखों में प्रवेश कर रहे हैं — भीष्म, द्रोण, कर्ण, और हमारे प्रमुख योद्धा भी,",
         "धृतराष्ट्र के बेटे, अपने साथ के राजाओं समेत, आपके मुँह की ओर खिंचे चले जा रहे हैं — भीष्म भी, द्रोण भी, कर्ण भी, और हमारी ओर के बड़े योद्धा भी,"),
"11.27": ("उनके सिर आपके दाँतों के बीच पिसे जा रहे हैं — कुछ, डर से चिपककर, आपके भयानक दाँतों के खाली स्थानों में दिख रहे हैं।",
         "सिर आपके दाँतों के बीच चूर हो रहे हैं; कुछ तो दाँतों की दरारों में फँसे हुए दिखते हैं।"),
"11.28": ("जैसे अनेक बहती नदियों की धाराएँ समुद्र में जा मिलती हैं, वैसे ही ये मर्त्य लोक के वीर आपके जलते मुखों में प्रवेश करते हैं।",
         "“जैसे नदियाँ अपने असंख्य जल-प्रवाहों सहित समुद्र में बहती हैं, वैसे ही ये मानव-वीर आपके जलते मुखों में बहते हैं।”"),
"11.29": ("जैसे पतंगे अपने विनाश के लिए पूरे वेग से जलती अग्नि में उड़ते हैं, वैसे ही ये लोक अपने विनाश के लिए आपके मुखों में उड़ते हैं।",
         "“जैसे पतंगे नष्ट होने के लिए ज्वाला में कूद पड़ते हैं, वैसे ही ये लोक नष्ट होने के लिए आपके मुखों में दौड़ते हैं।”"),
"11.30": ("आप अपने जलते मुखों से सब लोकों को चाटते हैं, चारों ओर से निगलते हैं; आपकी भयंकर किरणें सम्पूर्ण ब्रह्माण्ड को भर देती हैं, हे विष्णु।",
         "जलते हुए मुँह से आप लोकों को जीभ से समेटते हुए चारों ओर से निगल रहे हैं; आपकी उग्र आँच से सारा ब्रह्माण्ड तप रहा है, हे विष्णु।"),
"11.31": ("हे भयंकर रूप, बताइए आप कौन हैं; मैं आपको प्रणाम करता हूँ — हे देवों में श्रेष्ठ, कृपा कीजिए! मैं आपको, आदि पुरुष को, जानना चाहता हूँ; मैं आपकी गतियों को नहीं समझता।",
         "“इस भयानक रूप में आप कौन हैं, बताइए; मैं आपको प्रणाम करता हूँ — कृपा कीजिए, प्रभु। मैं आपको, आदिम पुरुष को, जानना चाहता हूँ, क्योंकि आपके मार्ग मैं नहीं समझ सकता।”"),
"11.32": ("श्री भगवान् ने कहा: मैं काल हूँ — जगत् का नाश करने वाला, परिपक्व हुआ; इन लोकों को नष्ट करने मैं आया हूँ — तेरे बिना भी, तेरे सामने सजे इन योद्धाओं में से कोई नहीं बचेगा।",
         "कृष्ण ने कहा: “मैं काल हूँ — लोकों को नष्ट करने के लिए परिपक्व। तेरे आघात के बिना भी इन योद्धाओं में से कोई नहीं बचेगा।”"),
"11.33": ("इसलिए उठ और कीर्ति जीत; शत्रुओं को जीत और फलते-फूलते राज्य का भोग कर — वे मेरे द्वारा पहले ही मारे जा चुके हैं; हे सव्यसाची, तू केवल साधन है।",
         "“इसलिए उठ और यश कमा; शत्रु को हरा और समृद्ध राज्य का आनन्द ले। मैंने उन्हें पहले ही मार दिया है — तू केवल माध्यम है, अर्जुन।”"),
"11.34": ("द्रोण, भीष्म, जयद्रथ, कर्ण और अन्य वीर-योद्धाओं को मार — जिन्हें मैंने पहले ही मार दिया है; बिना भय के प्रहार कर, युद्ध कर — तू रण में अपने प्रतिद्वंद्वियों को जीतेगा।",
         "“द्रोण, भीष्म, जयद्रथ और कर्ण को मार — मैंने उन्हें पहले ही नष्ट कर दिया है। बिना हिचक प्रहार कर और युद्ध कर; तू रण में विजयी होगा।”"),
"11.35": ("संजय ने कहा: केशव के ये वचन सुनकर, मुकुट-धारी अर्जुन, काँपते हुए, हाथ जोड़कर, फिर झुककर, रुके हुए स्वर में कृष्ण से बोला।",
         "संजय वर्णन करते हैं: “कृष्ण के वचन सुनकर, काँपते हुए अर्जुन ने हाथ जोड़े, फिर झुका, और लड़खड़ाते स्वर में बोला।”"),
"11.36": ("हे हृषीकेश, उचित ही है कि संसार आपके वैभव में प्रसन्न और आनन्दित हो; राक्षस भय से चारों दिशाओं में भागते हैं, और सिद्धों के समूह आपको प्रणाम करते हैं।",
         "“ठीक ही है, हे कृष्ण, कि संसार आपकी प्रशंसा में रमता है; दानव त्रास में भागते हैं, और सिद्ध आपको प्रणाम करते हैं।”"),
"11.37": ("हे महात्मा, आदि सृष्टिकर्ता ब्रह्मा से भी श्रेष्ठ आपको वे क्यों न झुकें — हे देवों के अनन्त स्वामी, जगत् के आश्रय, आप ही अविनाशी, सत् और असत् और दोनों से परे हैं?",
         "“हे महान्, पहले सृष्टिकर्ता ब्रह्मा से भी श्रेष्ठ आपको कौन न झुकेगा? आप नित्य, सत् और असत्, और उनसे परे — सब कुछ हैं।”"),
"11.38": ("आप आदि देव, प्राचीन पुरुष, इस ब्रह्माण्ड के परम शरण हैं; आप ज्ञाता और ज्ञेय, परम धाम हैं; हे अनन्त रूप, आपसे ही यह ब्रह्माण्ड व्याप्त है।",
         "“आप पहले देव, प्राचीन पुरुष, ब्रह्माण्ड के सर्वोच्च आश्रय हैं; आप जानने वाले और जानने योग्य, परम घर हैं — और सब आप में ही फैला है।”"),
"11.39": ("आप वायु, मृत्यु, अग्नि, वरुण, चन्द्रमा और प्रजापति — और महान् पितामह हैं; मैं आपको हज़ार बार प्रणाम करता हूँ — बार-बार और फिर आपको प्रणाम करता हूँ।",
         "“आप वायु, मृत्यु, अग्नि, वरुण, चन्द्रमा — पिता और महान् पूर्वज हैं। आपको हज़ारों प्रणाम — बार-बार, मैं झुकता हूँ।”"),
"11.40": ("मैं आपको आगे से और पीछे से प्रणाम करता हूँ; हे सर्व, मैं आपको चारों ओर से प्रणाम करता हूँ! आप अनन्त शक्ति और अमापनीय वेग वाले हैं; आप सबको व्याप्त करते हैं, इसलिए आप ही सब हैं।",
         "“मैं आपको आगे और पीछे प्रणाम करता हूँ; हे सर्वव्यापी, मैं चारों ओर से आपको प्रणाम करता हूँ। आपकी शक्ति अनन्त है — आप सब कुछ हैं, क्योंकि आपने सब कुछ भरा है।”"),
"11.41": ("आपकी महिमा को न जानकर, उतावली और अपरिचितता में — 'हे कृष्ण, हे यादव, हे मित्र' — लापरवाही से या प्रेम से मैंने जो-जो कहा,",
         "“आपकी महानता न जानकर, हिम्मत और लापरवाही में — आपको कृष्ण, यादव, मेरा मित्र कहकर — मज़ाक में या ममता में जो-जो कहा,”"),
"11.42": ("और खेल में, विश्राम में, बैठते या भोजन करते समय, अकेले या दूसरों के सामने आपके प्रति जो-जो अनादर किया — हे अच्युत, हे अप्रमेय, वह सब क्षमा कीजिए।",
         "“— और खेल, आराम, भोजन या दूसरों की संगति में, आपके प्रति जो-जो हेला की — हे अपरिवर्तनीय, अमापनीय प्रभु, वह सब क्षमा कीजिए।”"),
"11.43": ("आप इस चर-अचर जगत् के पिता हैं; आप इसके परम पूजनीय और सबसे श्रद्धेय गुरु हैं; तीनों लोकों में आपके बराबर कोई नहीं — फिर आपसे बढ़कर कौन हो सकता है, हे अतुल शक्ति वाले?",
         "“आप चल और अचल — सबके पिता हैं; आप परम पूज्य और सबसे बड़े गुरु हैं। तीनों लोकों में आपके बराबर कुछ नहीं — आपसे ऊपर तो कुछ कैसे हो सकता है?”"),
"11.44": ("इसलिए मैं झुककर आपके सामने शरीर पसारता हूँ, और आपकी कृपा माँगता हूँ, हे पूजनीय प्रभु; जैसे पिता पुत्र को, मित्र मित्र को, प्रेमी प्रियतम को क्षमा करता है — वैसे ही मुझे क्षमा कीजिए, हे देव।",
         "इसीलिए मैं ज़मीन पर लेटकर आपसे विनती करता हूँ। जैसे पिता बेटे को, दोस्त दोस्त को, प्रेमी अपने प्रिय को माफ़ कर देता है — वैसे ही मुझे माफ़ कीजिए।"),
"11.45": ("पहले कभी न देखा यह देखकर मैं प्रसन्न हूँ, फिर भी मेरा मन भय से काँपता है; हे देव, अपना मनोहर रूप दिखाइए — हे विश्वेश्वर, कृपा कीजिए।",
         "“यह आश्चर्य देखकर मैं हर्षित हूँ, किन्तु मेरा हृदय भय से काँपता है; हे प्रभु, अपना कोमल रूप दिखाइए — कृपा कीजिए।”"),
"11.46": ("मैं आपको पहले जैसा — मुकुट, गदा और चक्र हाथ में लिए — देखना चाहता हूँ; हे हज़ार भुजाओं वाले विश्व-रूप, उस चतुर्भुज रूप में प्रकट हों।",
         "फिर वही पुराना रूप देखने को जी करता है — सिर पर मुकुट, हाथ में गदा और चक्र। हे विश्वरूप, वही चार भुजाओं वाला रूप दिखा दीजिए।"),
"11.47": ("श्री भगवान् ने कहा: हे अर्जुन, मैंने कृपा करके तुझे यह परम रूप दिखाया — तेजोमय, विश्व-रूपी, अनन्त, आदिम रूप — जो तुझसे पहले किसी ने नहीं देखा।",
         "कृष्ण ने कहा: “कृपा से, अर्जुन, मैंने तुझे यह सर्वोच्च, दैदीप्यमान, विश्व-रूपी, असीम, आदिम रूप दिखाया — तुझसे पहले किसी ने नहीं देखा।”"),
"11.48": ("हे कुरुनन्दन, वेदों के अध्ययन, यज्ञ, दान, अनुष्ठान या घोर तपस्या से — किसी भी उपाय से, मनुष्य-लोक में, तुझे छोड़कर कोई मुझे इस रूप में नहीं देख सकता।",
         "“न वेद-अध्ययन से, न यज्ञ से, न दान से, न अनुष्ठान से, न घोर तप से — इस रूप को मर्त्य लोक में तुझे छोड़कर कोई नहीं देख सकता।”"),
"11.49": ("मेरे इस भयंकर रूप को देखकर न डर, न मोहित हो; भय हटाकर, प्रसन्न हृदय से, मेरा यह मनोहर रूप फिर देख।",
         "“मेरे इस भयानक दृश्य को देखकर न डर, न उलझन में पड़। भय जाने पर, सहज हृदय से, मेरा कोमल रूप फिर देख।”"),
"11.50": ("संजय ने कहा: अर्जुन से ऐसा कहकर, वासुदेव ने फिर अपना निजी रूप दिखाया, और महात्मा ने भयभीत अर्जुन को, फिर अपने मनोहर रूप में, सान्त्वना दी।",
         "संजय वर्णन करते हैं: “ऐसा कहकर, कृष्ण ने फिर अपना कोमल रूप धारण किया, और महात्मा ने त्रस्त अर्जुन को सान्त्वना दी।”"),
"11.51": ("अर्जुन ने कहा: हे जनार्दन, आपका यह मनोहर मानव रूप देखकर, मैं अब शान्त हूँ और अपने स्वभाव में लौट आया हूँ।",
         "अर्जुन कहते हैं: “आपका कोमल मानव रूप देखकर, हे जनार्दन, मैं फिर शान्त हूँ, और मेरा मन अपने आप में लौट आया है।”"),
"11.52": ("श्री भगवान् ने कहा: तूने जो रूप देखा, उसे देखना अत्यन्त कठिन है; देवता भी इस रूप के दर्शन की सदा इच्छा करते हैं।",
         "कृष्ण ने कहा: “जो तूने अभी देखा, वह किसी को कभी-कभार ही दिखता है। देवता तक इस झलक के लिए तरसते रह जाते हैं।”"),
"11.53": ("न वेदों से, न तपस्या से, न दान से, न पूजा से मैं इस रूप में देखा जा सकता हूँ; केवल उसी प्रकार, जिस प्रकार तूने मुझे देखा, मैं देखा जाता हूँ।",
         "“यह दर्शन न वेद-अध्ययन से, न तप से, न दान से, न अनुष्ठान से मिलता है — मैं वैसे ही दिखता हूँ, जैसे तूने मुझे देखा।”"),
"11.54": ("किन्तु हे अर्जुन, एकनिष्ठ भक्ति से मैं इसी रूप में सचमुच जाना, देखा और प्रवेश किया जा सकता हूँ।",
         "पर अर्जुन, जिसका मन कहीं और बँटा नहीं — वही मुझे इस रूप में सचमुच जान पाता है, देख पाता है, और मुझ में समा जाता है।"),
"11.55": ("जो मेरा कर्म करता है, मुझे परम लक्ष्य मानता है, मुझ में भक्त है, आसक्ति से रहित है, और किसी प्राणी से द्वेष नहीं रखता — हे पाण्डव, वह मुझे प्राप्त होता है।",
         "“जो मेरे लिए काम करता है, मुझे अपना परम लक्ष्य बनाता है, मुझ में समर्पित है, आसक्ति और द्वेष से मुक्त है — वह मुझ तक पहुँचता है, अर्जुन।”"),
"12.01": ("अर्जुन ने कहा: सदा युक्त होकर आपकी पूजा करने वाले भक्त — और अविनाशी अव्यक्त की पूजा करने वाले — इनमें से कौन योग के बेहतर ज्ञाता हैं?",
         "अर्जुन पूछते हैं: “कौन बड़े योगी हैं — भक्ति से आपकी पूजा करने वाले, या निराकार, अविनाशी परमात्मा की पूजा करने वाले?”"),
"12.02": ("श्री भगवान् ने कहा: जो मन मुझ में लगाकर, सदा युक्त होकर, परम श्रद्धा से मेरी पूजा करते हैं — उन्हें ही मैं सबसे युक्त मानता हूँ।",
         "कृष्ण ने कहा: “जो मन मुझ पर रखकर, सदा समर्पित होकर, परम श्रद्धा से मेरी पूजा करते हैं — मेरी दृष्टि में वे ही महान् योगी हैं।”"),
"12.03": ("किन्तु जो अविनाशी, अवर्णनीय, अव्यक्त — सर्वव्यापी, अचिन्त्य, अपरिवर्तनीय, अचल, नित्य — की पूजा करते हैं,",
         "और कुछ लोग उस निराकार की उपासना करते हैं — जिसे शब्दों में बाँधा नहीं जा सकता, जो हर जगह है, सोच से परे, कभी न बदलने वाला,"),
"12.04": ("— सब इन्द्रियों को संयत करके, सर्वत्र समान मन से, सब प्राणियों के हित में रमकर — वे भी मुझे प्राप्त होते हैं।",
         "“— जो इन्द्रियों को रोककर, सबको समान देखकर, सब प्राणियों के हित में रमते हैं — वे भी मुझ तक पहुँचते हैं।”"),
"12.05": ("जिनके मन अव्यक्त में आसक्त हैं, उनका परिश्रम अधिक है; देहधारियों के लिए अव्यक्त की प्राप्ति कठिन है।",
         "“किन्तु उनका संघर्ष बड़ा है, क्योंकि निराकार परमात्मा शरीर में रहने वालों के लिए दुर्लभ है।”"),
"12.06": ("किन्तु जो सब कर्म मुझ में अर्पण करते हैं, मुझ में ही तत्पर होकर, अविभाजित योग से मेरी पूजा करते हैं और मेरा ध्यान करते हैं,",
         "“किन्तु जो अपने सब कर्म मुझे अर्पण करते हैं, मुझे परम मानते हैं, और एकाग्र ध्यान से मेरी पूजा करते हैं,”"),
"12.07": ("— हे पार्थ, उनके लिए, जिनका मन मुझ में टिका है, मैं शीघ्र ही जन्म-मृत्यु के सागर से उद्धारक बन जाता हूँ।",
         "“— जिनका हृदय मुझ में विश्राम करता है, उनके लिए मैं शीघ्र ही जन्म-मृत्यु के सागर से उद्धारकर्ता बन जाता हूँ।”"),
"12.08": ("केवल मुझ में ही मन लगा; मुझ में ही बुद्धि स्थिर कर; तब तू मुझ में ही रहेगा — इसमें कोई सन्देह नहीं।",
         "“अपना मन और समझ केवल मुझ पर रख — और तू निश्चय मुझ में ही रहेगा; इसमें कोई सन्देह नहीं।”"),
"12.09": ("यदि तू मन को मुझ में स्थिर नहीं कर सकता, तो हे धनंजय, अभ्यास-योग से — अभ्यास द्वारा मुझ तक पहुँचने का प्रयास कर।",
         "“यदि तू मन को मुझ पर स्थिर नहीं रख सकता, तो बार-बार के अभ्यास से मुझ तक पहुँचने का प्रयास कर, अर्जुन।”"),
"12.10": ("यदि तू वह भी नहीं कर सकता, तो मेरे लिए कर्म करने में समर्पित हो; मेरे ही लिए कर्म करके भी तू सिद्धि पा जाएगा।",
         "“यदि वह भी सम्भव नहीं, तो मेरे लिए काम करने में लग जा — मेरे ही लिए कर्म करके भी तू सिद्धि तक पहुँचेगा।”"),
"12.11": ("यदि यह भी नहीं कर सकता, तो मेरे योग की शरण लेकर, आत्मा को संयत करके, सब कर्मों का फल त्याग दे।",
         "“यदि वह भी नहीं कर सकता, तो आत्म-संयमित मन से, अपने सब कर्मों का फल मुझे समर्पण कर दे।”"),
"12.12": ("अभ्यास से ज्ञान अच्छा है; ज्ञान से ध्यान अच्छा है; ध्यान से कर्म-फल-त्याग अच्छा है — क्योंकि त्याग से तुरन्त शान्ति मिलती है।",
         "रटने से समझ बेहतर, समझ से ध्यान बेहतर; पर सबसे बेहतर है नतीजे की चाह छोड़ देना — वहीं से चैन तुरन्त शुरू होता है।"),
"12.13": ("जो किसी प्राणी से द्वेष नहीं करता, मित्र-भाव और करुणा रखता है, ममता और अहंकार से मुक्त है, सुख-दुःख में समान है, क्षमाशील है —",
         "“जो किसी से घृणा नहीं करता, दयालु और करुणामय है, 'मेरा' और 'मैं' से मुक्त है, सुख-दुःख में एक-सा है, धैर्यवान् है —”"),
"12.14": ("— सदा संतुष्ट, योगी, आत्म-संयमी, दृढ़ संकल्प वाला, मन और बुद्धि मुझ में अर्पण किए — वह मेरा भक्त मुझे प्रिय है।",
         "“— सदा संतोषी, आत्म-विजयी, संकल्पवान्, मन और हृदय मुझे दिए — ऐसा भक्त मुझे प्रिय है।”"),
"12.15": ("जिससे संसार विचलित नहीं होता, और जो संसार से विचलित नहीं होता — हर्ष, क्रोध, भय और चिन्ता से मुक्त — वह मुझे प्रिय है।",
         "जिससे किसी को तकलीफ़ नहीं होती, और जिसे किसी से तकलीफ़ नहीं होती; जो न फूलता है, न भड़कता, न डरता, न घबराता — वह मुझे प्यारा है।"),
"12.16": ("जो आसक्ति-रहित, शुद्ध, दक्ष, उदासीन, चिन्ता-रहित, सब आरम्भों का त्यागी — वह मेरा भक्त मुझे प्रिय है।",
         "“जो आसक्ति-रहित, शुद्ध, निपुण, तटस्थ, चिन्ता-मुक्त, और सब स्वार्थी परियोजनाओं को छोड़ने वाला — वह भक्त मुझे प्रिय है।”"),
"12.17": ("जो न रमता है न घृणा करता है, न शोक करता है न इच्छा रखता है, शुभ और अशुभ दोनों को त्यागने वाला — वह भक्त मुझे प्रिय है।",
         "“जो न हर्षित होता है न निराश, न शोक करता है न लालसा, शुभ-अशुभ दोनों छोड़ने वाला — ऐसा भक्त मुझे प्रिय है।”"),
"12.18": ("मित्र और शत्रु, मान और अपमान, सर्दी और गर्मी, सुख और दुःख में समान, आसक्ति-रहित —",
         "“मित्र और शत्रु, प्रशंसा और निन्दा, सर्दी-गर्मी, सुख-शोक में समान, मोह से मुक्त —”"),
"12.19": ("— मौन, जो कुछ मिले उसी में संतुष्ट, गृह-रहित, स्थिर मन वाला, भक्ति से भरा — वह मनुष्य मुझे प्रिय है।",
         "“— मौन, जो मिले उसी में संतुष्ट, स्थान से आसक्ति-रहित, स्थिर मन, समर्पित — ऐसा व्यक्ति मुझे प्रिय है।”"),
"12.20": ("किन्तु जो इस अमृत धर्म का, कहे अनुसार, श्रद्धा से, मुझे परम लक्ष्य बनाकर अनुसरण करते हैं — वे भक्त मुझे अत्यन्त प्रिय हैं।",
         "“किन्तु जो इस अमर धर्म का श्रद्धा से, मुझे सर्वोच्च लक्ष्य मानकर अनुसरण करते हैं — ऐसे भक्त सबसे अधिक प्रिय हैं।”"),
"13.01": ("श्री भगवान् ने कहा: हे कुन्तीपुत्र, यह शरीर क्षेत्र कहलाता है; जो इसे जानता है, उसे ज्ञानी क्षेत्रज्ञ कहते हैं।",
         "कृष्ण ने कहा: “यह शरीर क्षेत्र कहलाता है; जो इसे जानता है, वह क्षेत्रज्ञ कहलाता है।”"),
"13.02": ("हे भारत, सब क्षेत्रों में मुझे भी क्षेत्रज्ञ जान; क्षेत्र और क्षेत्रज्ञ का ज्ञान ही मेरी दृष्टि में सच्चा ज्ञान है।",
         "“मुझे हर शरीर का क्षेत्रज्ञ जान; क्षेत्र और उसके ज्ञाता का विवेक ही मैं सच्चा ज्ञान कहता हूँ।”"),
"13.03": ("क्षेत्र क्या है, कैसा है, इसके विकार क्या हैं, यह कहाँ से उत्पन्न होता है, और वह कौन है और उसकी शक्तियाँ क्या हैं — यह सब मुझसे संक्षेप में सुन।",
         "“क्षेत्र क्या है, उसका स्वरूप, उसके परिवर्तन, उसका स्रोत — और ज्ञाता कौन है और उसकी शक्तियाँ क्या हैं — यह सब मुझसे संक्षेप में सुन।”"),
"13.04": ("मुनियों ने इसे अनेक प्रकार से, विविध छन्दों में, और ब्रह्म-सूत्रों में, कारण सहित, अच्छी तरह निर्णय करके गाया है —",
         "ऋषियों ने यह बात कई ढंग से गाई है — अलग-अलग छन्दों में, और ब्रह्मसूत्रों में भी, पूरे तर्क के साथ, दो-टूक।"),
"13.05": ("— महाभूत, अहंकार, बुद्धि, अव्यक्त, दस इन्द्रियाँ और मन, और पाँच इन्द्रिय-विषय,",
         "गिनाऊँ तो: पाँच महाभूत, 'मैं' का भाव, बुद्धि, और वह अनदेखा मूल; दस इन्द्रियाँ, मन, और इन्द्रियों के पाँच विषय —"),
"13.06": ("— इच्छा, द्वेष, सुख, दुःख, शरीर, चेतना और धृति: यही क्षेत्र है, संक्षेप में, अपने विकारों सहित।",
         "“— इच्छा, अरुचि, आनन्द, शोक, शरीर ही, चेतना और स्थिरता: यही क्षेत्र है, संक्षेप में, अपने सब परिवर्तनों सहित।”"),
"13.07": ("अमानित्व, अदम्भित्व, अहिंसा, क्षान्ति, आर्जव, आचार्य-सेवा, शौच, स्थैर्य, आत्म-संयम,",
         "“नम्रता, विनम्रता, अहिंसा, धैर्य, ईमानदारी, गुरु की सेवा, शुद्धता, दृढ़ता, आत्म-संयम,”"),
"13.08": ("— इन्द्रिय-विषयों में वैराग्य, अहंकार का अभाव, और जन्म, मृत्यु, बुढ़ापे और रोग का दोष-दर्शन,",
         "“— इन्द्रिय-सुखों में अनासक्ति, अहंकार का न होना, और जन्म, मृत्यु, बुढ़ापे और रोग की पीड़ा को स्पष्ट देखना,”"),
"13.09": ("— आसक्ति-रहितता, पुत्र, पत्नी और घर में ममता न रखना, लाभ-हानि में निरन्तर समता,",
         "“— आसक्ति न होना, परिवार और घर में मोह न होना, सफलता-असफलता में स्थिर समत्व,”"),
"13.10": ("— अविभाजित योग से मुझ में अविचलित भक्ति, एकान्त में रुचि, मनुष्यों की भीड़ से अरुचि,",
         "“— एकनिष्ठ योग से मुझ में अटल भक्ति, एकान्त में प्रेम, सांसारिक भीड़ से अरुचि,”"),
"13.11": ("— आत्म-ज्ञान में निरन्तर लगन, और तत्त्व-ज्ञान के प्रयोजन की दृष्टि: यही ज्ञान कहा गया है; इससे भिन्न जो है वह अज्ञान है।",
         "“— आत्म-ज्ञान की निरन्तर खोज, और सत्य-ज्ञान का उद्देश्य देखना: इसे ज्ञान कहते हैं; इससे अलग जो है वह अज्ञान है।”"),
"13.12": ("मैं जानने-योग्य वस्तु कहूँगा, जिसे जानकर मनुष्य अमरत्व का रस चखता है — आदि-रहित परम ब्रह्म, जिसे न सत् कहा जाता है न असत्।",
         "“मैं तुझे जानने-योग्य वस्तु बताता हूँ, जिसे जानकर तू अमरत्व चखेगा — आदि-रहित परम ब्रह्म, सत् और असत् दोनों से परे।”"),
"13.13": ("हर ओर हाथ-पैर, हर ओर नेत्र, सिर और मुख, हर ओर कान रखकर — यह संसार में सबको व्याप्त करके खड़ा है।",
         "“इसके हाथ-पैर सब दिशाओं में हैं, नेत्र, सिर और मुख सब ओर, कान सब ओर — यह सबको आलिंगन किए खड़ा है।”"),
"13.14": ("इन्द्रियों के सब गुणों से युक्त प्रतीत होता हुआ, किन्तु सब इन्द्रियों से रहित; आसक्ति-रहित, फिर भी सबको धारण करने वाला; गुण-रहित, फिर भी गुणों का भोक्ता।",
         "“यह इन्द्रियों के सब गुणों वाला दिखता है, किन्तु इसकी इन्द्रियाँ नहीं हैं; यह आसक्ति-रहित है, फिर भी सबको धारण करता है; गुणों से परे, फिर भी उनका भोग करता है।”"),
"13.15": ("यह सब प्राणियों के भीतर और बाहर है; यह अचल भी है और चल भी; सूक्ष्म होने से यह जाना नहीं जा सकता — यह दूर भी है, और निकट भी।",
         "“यह सब प्राणियों के भीतर और बाहर है; अचल और चल दोनों; इतना सूक्ष्म कि पकड़ में न आए — दूर भी, और हाथों हाथ भी।”"),
"13.16": ("यह अविभाजित है, फिर भी प्राणियों में विभाजित-सा दिखता है; इसे प्राणियों का धर्ता, भोक्ता और स्रष्टा जान।",
         "“अविभाजित, यह प्राणियों में विभाजित-सा दिखता है; इसे सबका धारण करने वाला, भोगने वाला और स्रोत जान।”"),
"13.17": ("यह ज्योतियों की ज्योति है, अन्धकार से परे कहा गया — ज्ञान, ज्ञेय और ज्ञान का लक्ष्य, सबके हृदय में बैठा हुआ।",
         "“यह सब ज्योतियों की ज्योति, अन्धकार से परे — ज्ञान ही, उसका विषय, और उसका लक्ष्य — हर हृदय में निवास करने वाला।”"),
"13.18": ("इस प्रकार क्षेत्र, ज्ञान और ज्ञेय संक्षेप में कहा गया; मेरा भक्त, इसे जानकर, मेरी अवस्था को प्राप्त होता है।",
         "इतना ही है — खेत, ज्ञान, और जो जानने योग्य है। जो मुझसे जुड़ा है वह यह पकड़ लेता है, और मेरे जैसा हो जाता है।"),
"13.19": ("प्रकृति और पुरुष दोनों को आदि-रहित जान; और विकारों तथा गुणों को प्रकृति से उत्पन्न जान।",
         "“जान कि प्रकृति और पुरुष दोनों आदि-रहित हैं; और सब परिवर्तन तथा गुण प्रकृति से उठते हैं।”"),
"13.20": ("प्रकृति कार्य की सिद्धि में कर्तृत्व का कारण कही जाती है; पुरुष सुख-दुःख के भोग का कारण कहा जाता है।",
         "“प्रकृति करने का कारण है; पुरुष सुख-दुःख का अनुभव करने का कारण है।”"),
"13.21": ("प्रकृति में बैठा पुरुष प्रकृति से उत्पन्न गुणों का भोग करता है; गुणों में आसक्ति ही शुभ-अशुभ योनियों में जन्म का कारण है।",
         "“प्रकृति में विश्राम करने वाला पुरुष प्रकृति से जन्मे गुणों को चखता है; उन गुणों से चिपकना ही ऊँची या नीची योनियों में जन्म का कारण है।”"),
"13.22": ("साक्षी, अनुमोदक, धर्ता, भोक्ता, महान् स्वामी — और परम आत्मा कहा गया: शरीर में स्थित यह परम पुरुष।",
         "“साक्षी, स्वीकर्ता, धारण करने वाला, भोगने वाला, महान् स्वामी — जिसे परम आत्मा कहते हैं: शरीर में स्थित यही सर्वोच्च पुरुष।”"),
"13.23": ("जो इस प्रकार पुरुष और गुणों सहित प्रकृति को जानता है — जैसी भी जीवन-शैली हो — वह फिर जन्म नहीं लेता।",
         "जो प्रकृति और उसके गुणों के साथ पुरुष को इस तरह पहचान लेता है — चाहे वह जैसे भी जिए — उसका दोबारा जन्म नहीं होता।"),
"13.24": ("कोई भीतर की आत्मा को ध्यान से देखते हैं; कोई ज्ञान-योग से; अन्य कोई कर्म-योग से।",
         "कोई भीतर बैठकर आत्मा को निहारता है; कोई सोच-विचार के रास्ते पहुँचता है; कोई बिना स्वार्थ काम करते-करते।"),
"13.25": ("अन्य, न जानकर, दूसरों से सुनकर पूजा करते हैं; और वे भी, सुनी हुई बात में समर्पित होकर, मृत्यु से पार हो जाते हैं।",
         "“अन्य, प्रत्यक्ष न जानकर, गुरुओं से सुनकर पूजा करते हैं — और वे भी सुने गए उपदेश में श्रद्धा से मृत्यु पार कर जाते हैं।”"),
"13.26": ("हे भरतश्रेष्ठ, जो-जो प्राणी जन्मता है, चर हो या अचर — उसे क्षेत्र और क्षेत्रज्ञ के संयोग से उत्पन्न जान।",
         "“जो-जो अस्तित्व में आता है, चल हो या स्थिर — उसे क्षेत्र और उसके ज्ञाता के मिलन से उठा जान, अर्जुन।”"),
"13.27": ("जो सब प्राणियों में समान रूप से स्थित, नष्ट होते हुए भी न नष्ट होने वाले परम स्वामी को देखता है — वही सचमुच देखता है।",
         "मिटने वाले सब जीवों के बीच जो नहीं मिटता — उसे हर जगह एक-सा देख लेना ही सचमुच देखना है।"),
"13.28": ("क्योंकि सर्वत्र समान स्थित स्वामी को देखकर, वह आत्मा द्वारा आत्मा को हानि नहीं पहुँचाता; इसलिए वह परम लक्ष्य को प्राप्त होता है।",
         "“सब में समान स्थित स्वामी को देखकर, वह अपनी आत्मा को कभी नीचा नहीं करता; और इसलिए सर्वोच्च लक्ष्य तक पहुँचता है।”"),
"13.29": ("जो देखता है कि सब कर्म प्रकृति से सम्पन्न होते हैं, और आत्मा अकर्ता है — वही सचमुच देखता है।",
         "करती तो प्रकृति है, आत्मा कुछ नहीं करती — जिसे यह दिख गया, उसे ही सही दिखा।"),
"13.30": ("जब वह प्राणियों की विविध अवस्थाओं को एक ही तत्त्व में विश्रान्त और उसी से फैली हुई देखता है — तब वह ब्रह्म को प्राप्त होता है।",
         "“जब वह सब प्राणियों की विविध अवस्थाओं को एक में टिकी और एक ही से उठी देखता है — तब वह ब्रह्म हो जाता है।”"),
"13.31": ("आदि-रहित और गुण-रहित होने से यह परम आत्मा अविनाशी है — शरीर में रहते हुए भी, यह न कर्म करता है न लिप्त होता है।",
         "जिसका न आरम्भ है न कोई गुण, वह परम आत्मा कभी घटती नहीं। देह में रहकर भी वह न कुछ करती है, न उसमें कुछ चिपकता है।"),
"13.32": ("जैसे सर्वव्यापी आकाश, सूक्ष्म होने पर भी, लिप्त नहीं होता, वैसे ही हर शरीर में स्थित आत्मा लिप्त नहीं होती।",
         "हवा-सा फैला आकाश हर जगह है, फिर भी उस पर कुछ नहीं लगता; देह में बसी आत्मा का हाल भी वैसा ही है।"),
"13.33": ("जैसे एक ही सूर्य इस सम्पूर्ण जगत् को प्रकाशित करता है, हे भारत, वैसे ही क्षेत्रज्ञ सम्पूर्ण क्षेत्र को प्रकाशित करता है।",
         "एक ही सूरज पूरी दुनिया को रोशन कर देता है, अर्जुन; उसी तरह खेत को जानने वाला पूरे खेत को रोशन करता है।"),
"13.34": ("जो ज्ञान के नेत्र से क्षेत्र और क्षेत्रज्ञ का भेद, और प्रकृति से मुक्ति देखते हैं — वे परम तत्त्व को प्राप्त होते हैं।",
         "“जो ज्ञान के नेत्र से क्षेत्र और उसके ज्ञाता का अन्तर, और प्रकृति से स्वतंत्रता देखते हैं — वे सर्वोच्च तक पहुँचते हैं।”"),
"14.01": ("श्री भगवान् ने कहा: मैं फिर परम ज्ञान कहूँगा — सब ज्ञानों में उत्तम; जिसे जानकर सब मुनि परम सिद्धि को प्राप्त हुए हैं।",
         "कृष्ण ने कहा: “अब मैं तुझे सर्वोच्च ज्ञान बताता हूँ — सबसे उत्तम; जिसे जानकर मुनि परम सिद्धि तक पहुँचे।”"),
"14.02": ("इस ज्ञान की शरण लेकर, वे मेरे स्वरूप से एक हो जाते हैं; न सृष्टि के आरम्भ में जन्मते हैं, न विनाश में विचलित होते हैं।",
         "“इस ज्ञान में विश्राम करके, वे मुझ से एक हो जाते हैं; सृष्टि के उदय पर जन्मते नहीं, न अन्त में विचलित होते हैं।”"),
"14.03": ("मेरा गर्भ महद्-ब्रह्म है; उसमें मैं बीज रखता हूँ — उसी से सब प्राणियों का जन्म होता है, हे भारत।",
         "“महान् ब्रह्म मेरा गर्भ है; मैं उसमें बीज रखता हूँ, और उसी से सब प्राणी जन्मते हैं।”"),
"14.04": ("हे कुन्तीपुत्र, जिस-जिस योनि में जो-जो रूप उत्पन्न होते हैं — उनका गर्भ महद्-ब्रह्म है, और बीज देने वाला पिता मैं हूँ।",
         "“जिस-जिस योनि में जो-जो रूप प्रकट होते हैं — वह योनि महान् ब्रह्म है, और बीज बोने वाला पिता मैं हूँ।”"),
"14.05": ("हे महाबाहो, प्रकृति से उत्पन्न गुण — सत्त्व, रज और तम — शरीर में अविनाशी देहधारी को बाँधते हैं।",
         "“प्रकृति के गुण — सत्त्व, रज और तम — अमर आत्मा को शरीर में बाँधते हैं।”"),
"14.06": ("उनमें सत्त्व, शुद्ध होने से, प्रकाश देता है और रोग-रहित है; यह सुख और ज्ञान में आसक्ति से बाँधता है, हे निष्पाप।",
         "“सत्त्व शुद्ध, प्रकाशमय और स्वस्थ है — फिर भी यह आनन्द और ज्ञान की आसक्ति से बाँधता है।”"),
"14.07": ("हे कुन्तीपुत्र, रज को राग-स्वभाव, तृष्णा और आसक्ति से उत्पन्न जान; यह कर्म में आसक्ति से देहधारी को बाँधता है।",
         "“रज राग है, लोभ और मोह से जन्मा; यह कर्म की आसक्ति से देहधारी को बाँधता है।”"),
"14.08": ("हे भारत, तम को अज्ञान से उत्पन्न, सब देहधारियों को मोहित करने वाला जान; यह प्रमाद, आलस्य और निद्रा से बाँधता है।",
         "“तम अज्ञान से जन्मा, सब प्राणियों को मोहित करने वाला है; यह लापरवाही, आलस्य और नींद से बाँधता है।”"),
"14.09": ("हे भारत, सत्त्व सुख से, रज कर्म से जोड़ता है; तम, ज्ञान को ढाँपकर, प्रमाद से जोड़ता है।",
         "“सत्त्व तुझे आनन्द से, रज कर्म से, और तम — ज्ञान छिपाकर — लापरवाही से जोड़ता है।”"),
"14.10": ("रज और तम को दबाकर सत्त्व उठता है; इसी प्रकार सत्त्व और तम को दबाकर रज उठता है; और दोनों को दबाकर तम भी उठता है।",
         "“रज और तम पर हावी होकर सत्त्व उठता है; सत्त्व और तम पर हावी होकर रज उठता है; और दोनों पर हावी होकर तम भी उठता है।”"),
"14.11": ("जब इस शरीर के सब द्वारों से ज्ञान का प्रकाश चमकता है, तब समझ कि सत्त्व बढ़ गया है।",
         "“जब शरीर के हर द्वार से प्रकाश आता है, तब समझ कि सत्त्व प्रबल है।”"),
"14.12": ("हे भरतश्रेष्ठ, जब रज बढ़ता है, तब लोभ, प्रवृत्ति, कर्म का आरम्भ, अशान्ति और तृष्णा उत्पन्न होती है।",
         "“लोभ, व्यस्तता, काम शुरू करना, बेचैनी और लालसा — ये सब रज के प्रबल होने पर दिखते हैं।”"),
"14.13": ("हे कुरुनन्दन, जब तम बढ़ता है, तब अन्धकार, आलस्य, प्रमाद और मोह उत्पन्न होते हैं।",
         "“सुस्ती, अकर्मण्यता, लापरवाही और भ्रम — ये तम के प्रबल होने पर उठते हैं।”"),
"14.14": ("यदि देहधारी सत्त्व के प्रबल होने पर मृत्यु को प्राप्त होता है, तो वह परम ज्ञाताओं के शुद्ध लोकों को प्राप्त होता है।",
         "“सत्त्व के प्रबल होने पर मरने वाला परम जानने वालों के शुद्ध लोकों तक पहुँचता है।”"),
"14.15": ("रज में मरकर कर्म में आसक्त लोगों के बीच जन्म लेता है; तम में मरकर मोहित लोगों की योनियों में जन्म लेता है।",
         "“रज में मरकर कर्म से बँधे लोगों के बीच पुनर्जन्म होता है; तम में मरकर मोहित लोगों के बीच।”"),
"14.16": ("शुभ कर्म का फल शुद्ध और सात्त्विक कहा गया है; रज का फल दुःख; तम का फल अज्ञान कहा गया है।",
         "“शुभ कर्म सत्त्व का शुद्ध फल देता है; रज दुःख देता है; तम अज्ञान देता है।”"),
"14.17": ("सत्त्व से ज्ञान उत्पन्न होता है; रज से लोभ; तम से प्रमाद, मोह और अज्ञान उत्पन्न होते हैं।",
         "“सत्त्व से ज्ञान; रज से लोभ; तम से लापरवाही, भ्रम और अज्ञान आते हैं।”"),
"14.18": ("सत्त्व में स्थित ऊपर जाते हैं; राजस बीच में रहते हैं; निम्नतम गुणों में डूबे तामस नीचे जाते हैं।",
         "सत्त्व वाले ऊपर उठते हैं, रजस वाले बीच में ही अटके रहते हैं, और तमस वाले सबसे नीचे उतरते चले जाते हैं।"),
"14.19": ("जब द्रष्टा गुणों के अतिरिक्त कोई कर्ता नहीं देखता, और उनसे परे के तत्त्व को जानता है — तब वह मेरी अवस्था को प्राप्त होता है।",
         "“जब ज्ञानी देखता है कि केवल गुण ही काम करते हैं, और उनसे परे के तत्त्व को पहचानता है — तब वह मेरे ही स्वरूप तक पहुँचता है।”"),
"14.20": ("शरीर से उत्पन्न इन तीनों गुणों से परे जाकर, जन्म, मृत्यु, बुढ़ापे और दुःख से मुक्त होकर, देहधारी अमरत्व का रस चखता है।",
         "देह से उपजे इन तीनों को लाँघ जाए तो देहधारी जन्म, मौत, बुढ़ापे और दर्द से छूट जाता है — और अमरता का स्वाद पा लेता है।"),
"14.21": ("अर्जुन ने कहा: हे प्रभु, इन तीनों गुणों से परे गये पुरुष को किन चिह्नों से जाना जाता है? उसका आचरण कैसा है, और वह इन्हें कैसे पार करता है?",
         "अर्जुन पूछते हैं: “जो इन तीनों से पार जा चुका है, उसे पहचानूँ कैसे? वह उठता-बैठता कैसे है, और यह पार जाना होता कैसे है?”"),
"14.22": ("श्री भगवान् ने कहा: हे पाण्डव, जो न प्रकाश, प्रवृत्ति और मोह के आने पर उनसे घृणा करता है, न जाने पर उनकी इच्छा करता है,",
         "कृष्ण ने कहा: “जो न प्रकाश, क्रिया और भ्रम के प्रकट होने पर उनसे चिढ़ता है, न हटने पर उनके लिए तरसता है,”"),
"14.23": ("— उदासीन बैठा हुआ, गुणों से न हिलने वाला, 'गुण ही कर्म करते हैं' ऐसा सोचकर अचल रहने वाला —",
         "“— बेपरवाह दर्शक की तरह बैठा, गुणों से न हिलने वाला, 'गुण ही काम करते हैं' सोचकर दृढ़ खड़ा रहने वाला —”"),
"14.24": ("— सुख-दुःख में समान, आत्मा में ही स्थित, जिसके लिए मिट्टी, पत्थर और सोना समान हैं, प्रिय-अप्रिय में समान, दृढ़, प्रशंसा-निन्दा में समान —",
         "“— सुख-शोक में समान, अपने में ही संतुष्ट, मिट्टी, पत्थर और सोने को एक-सा देखने वाला, प्रशंसा-निन्दा से न चलने वाला —”"),
"14.25": ("— मान-अपमान में समान, मित्र-शत्रु में समान, सब आरम्भों का त्यागी — वह गुणों से परे हुआ कहा जाता है।",
         "“— मान-अपमान में, मित्र-शत्रु में समान, सब स्वार्थी परियोजनाएँ छोड़ने वाला — ऐसा व्यक्ति गुणों से परे है।”"),
"14.26": ("जो अविचलित भक्ति-योग से मेरी सेवा करता है — इन गुणों को पार करके, वह ब्रह्म का योग्य हो जाता है।",
         "जो डिगे बिना प्रेम से मेरी सेवा में लगा रहता है, वह इन तीनों को पार कर जाता है और ब्रह्म होने लायक बन जाता है।"),
"14.27": ("क्योंकि मैं ही ब्रह्म का, अमरत्व और अविनाशी का, सनातन धर्म का और परम सुख का आश्रय हूँ।",
         "“क्योंकि मैं ही ब्रह्म का, अमरत्व और नित्य का — शाश्वत धर्म और परम आनन्द का — आधार हूँ।”"),
"15.01": ("श्री भगवान् ने कहा: ऊपर जड़ और नीचे शाखाओं वाले अविनाशी अश्वत्थ की चर्चा की जाती है; इसके पत्ते वेद हैं — जो इसे जानता है, वह वेद का ज्ञाता है।",
         "कृष्ण ने कहा: “इसे नित्य पीपल कहते हैं — जगत्-वृक्ष, जड़ ऊपर, शाखाएँ नीचे। इसके पत्ते वेद हैं; जो इसे जानता है, वह वेदों को जानता है।”"),
"15.02": ("इसकी शाखाएँ गुणों से पोषित, विषयों को अंकुर किए, ऊपर और नीचे फैलती हैं; और नीचे इसकी जड़ें, मनुष्य-लोक में कर्म से बाँधने वाली, फैली हैं।",
         "“इसकी शाखाएँ हर ओर फैलती हैं, तीन गुणों से पोषित, इन्द्रिय-विषयों को अंकुर बनाए; नीचे की जड़ें मानव-लोक में कर्म से बाँधती हैं।”"),
"15.03": ("इसका सच्चा रूप यहाँ नहीं दिखता, न इसका अन्त, न आदि, न आधार; दृढ़ जड़ वाले इस अश्वत्थ को वैराग्य की बलवती कुल्हाड़ी से काटकर,",
         "यहाँ खड़े-खड़े इस पेड़ का असली रूप नहीं सूझता — न इसका सिरा, न जड़, न ठिकाना। गहरी पकड़ वाले इस पीपल पर अनासक्ति की मज़बूत कुल्हाड़ी चलानी पड़ती है,"),
"15.04": ("— तब उस अवस्था की खोज करनी चाहिए, जहाँ पहुँचकर कोई नहीं लौटता; मैं उस आदि पुरुष की शरण लेता हूँ, जिससे सनातन धारा बहती है।",
         "“— और फिर उस लक्ष्य की खोज करो, जहाँ से कोई नहीं लौटता। मैं उस आदिम पुरुष में समर्पण करता हूँ — शाश्वत धारा का स्रोत।”"),
"15.05": ("अभिमान और मोह से मुक्त, आसक्ति के दोष को जीतकर, सदा आत्मा में ही स्थित, कामनाओं को फेरकर — सुख-दुःख कहे जाने वाले द्वन्द्वों से मुक्त — अमोहित लोग उस अविनाशी लक्ष्य को प्राप्त होते हैं।",
         "“अभिमान और भ्रम से मुक्त, मोह के दाग को जीतकर, सदा आत्मा में रहने वाला, इच्छा-रहित — सुख-शोक से परे — ज्ञानी उस नित्य धाम तक पहुँचते हैं।”"),
"15.06": ("न सूर्य, न चन्द्रमा, न अग्नि उस मेरे धाम को प्रकाशित करते हैं; वहाँ पहुँचकर कोई नहीं लौटता — वही मेरा परम धाम है।",
         "“मेरा सर्वोच्च घर सूर्य, चन्द्रमा या अग्नि से प्रकाशित नहीं होता; एक बार पहुँचकर कोई नहीं लौटता — वही मेरा परम धाम है।”"),
"15.07": ("मेरा ही अनन्त अंश, जीव-लोक में जीवात्मा बनकर, प्रकृति में रहने वाली इन्द्रियों को — जिनमें मन छठा है — अपनी ओर खींचता है।",
         "“मेरा ही नित्य अंश इस संसार में जीवात्मा बनता है; यह प्रकृति में रहने वाली पाँच इन्द्रियों और मन को अपनी ओर खींचता है।”"),
"15.08": ("जब शरीर का स्वामी शरीर ग्रहण करता है, और जब उसे छोड़ता है — वह इन इन्द्रियों को लेकर जाता है, जैसे वायु अपने स्थान से सुगन्ध ले जाती है।",
         "देह का मालिक जब नया शरीर लेता है और जब उसे छोड़ता है, तब इन्द्रियों को साथ लेता जाता है — जैसे हवा फूल से गन्ध उठा ले जाती है।"),
"15.09": ("श्रवण, स्पर्श, दर्शन, रसना और घ्राण, और मन पर अधिकार रखकर, वह इन्द्रिय-विषयों का भोग करता है।",
         "“सुनने, छूने, देखने, चखने, सूँघने और मन का उपयोग करके, वह इन्द्रियों के विषयों में रमता है।”"),
"15.10": ("मोहित लोग उसे — जाते, रहते या भोगते हुए, गुणों से युक्त हुए — नहीं देखते; किन्तु ज्ञान के नेत्र वाले उसे देखते हैं।",
         "वह जाता है, ठहरता है, भोगता है, गुणों के बीच रहता है — पर भ्रम में पड़े लोगों को कुछ नहीं दिखता। जिनकी आँख में समझ है, वे देख लेते हैं।"),
"15.11": ("प्रयत्नशील योगी उसे आत्मा में स्थापित देखते हैं; किन्तु असंयत, प्रयत्न करते हुए भी, सच्ची समझ न होने से उसे नहीं देखते।",
         "“प्रयासशील योगी उसे भीतर रहते देखते हैं; किन्तु जो अभी शुद्ध नहीं हुए — कितनी भी कोशिश करें — उसे नहीं देख पाते।”"),
"15.12": ("सूर्य में रहने वाला, जो सम्पूर्ण जगत् को प्रकाशित करता है, और चन्द्रमा तथा अग्नि में रहने वाला प्रकाश — उस प्रकाश को मेरा ही जान।",
         "“सूर्य का प्रकाश, जो सम्पूर्ण संसार को उजाला करता है, और चन्द्रमा तथा अग्नि का प्रकाश — उसे सब मेरा ही जान।”"),
"15.13": ("पृथ्वी में प्रवेश करके, मैं अपनी शक्ति से सब प्राणियों को धारण करता हूँ; रसमय चन्द्रमा बनकर, मैं सब औषधियों-वनस्पतियों को पोषण करता हूँ।",
         "“मैं पृथ्वी में प्रवेश करके अपनी शक्ति से सब प्राणी धारण करता हूँ; पोषक चन्द्रमा बनकर, मैं सब पौधों को सींचता हूँ।”"),
"15.14": ("प्राणियों के शरीरों में पाचक अग्नि बनकर, प्राण और अपान से युक्त होकर, मैं चार प्रकार के अन्न को पचाता हूँ।",
         "हर देह में पाचन की आग बनकर, साँसों के आने-जाने के साथ जुड़कर, मैं ही चारों तरह का अन्न पचाता हूँ।"),
"15.15": ("मैं सबके हृदय में बैठा हूँ; मुझसे ही स्मृति, ज्ञान और उनका हरण होता है; सब वेदों से मैं ही जानने योग्य हूँ — मैं वेदान्त का कर्ता और वेदों का ज्ञाता हूँ।",
         "“मैं हर हृदय में रहता हूँ; मुझसे ही स्मरण, ज्ञान और उनकी हानि आती है। सब वेद जो सिखाते हैं वह मैं ही हूँ — उनका कर्ता और ज्ञाता।”"),
"15.16": ("इस संसार में दो पुरुष हैं: क्षर और अक्षर। क्षर तो सब प्राणी हैं; अपरिवर्तनीय आत्मा अक्षर कहलाती है।",
         "दुनिया में दो तरह के पुरुष हैं — एक जो बीत जाता है, दूसरा जो नहीं बीतता। सब जीव पहले वाले हैं; न बदलने वाली आत्मा दूसरी।"),
"15.17": ("किन्तु दूसरा परम पुरुष है — परम आत्मा कहा गया — नित्य स्वामी, जो तीनों लोकों में प्रवेश करके उन्हें धारण करता है।",
         "पर इन दोनों से ऊपर एक और है, जिसे परमात्मा कहते हैं — वह अटल स्वामी जो तीनों लोकों में घुसकर उन्हें थामे हुए है।"),
"15.18": ("क्योंकि मैं क्षर से परे और अक्षर से ऊपर हूँ, इसलिए संसार में और वेद में मैं पुरुषोत्तम — सर्वोच्च पुरुष — के नाम से प्रसिद्ध हूँ।",
         "बीतने वाले से आगे, न बीतने वाले से भी ऊपर — इसीलिए दुनिया में और वेद में मुझे पुरुषोत्तम कहकर पुकारा जाता है।"),
"15.19": ("हे भारत, जो, अमोहित होकर, मुझे परम पुरुष जानता है — सब जानकर, वह सम्पूर्ण भाव से मेरी पूजा करता है।",
         "भ्रम हट जाने पर जो मुझे उस सर्वोच्च पुरुष के रूप में जान लेता है, अर्जुन, वह सब कुछ जान गया — और पूरे मन से मुझे पूजता है।"),
"15.20": ("हे निष्पाप, इस प्रकार मैंने यह अत्यन्त गुह्य शास्त्र कहा है; इसे समझने वाला पुरुष ज्ञानी हो जाता है और सब कर्म पूर्ण कर चुका होता है, हे भारत।",
         "“इसलिए मैंने तुझे यह सबसे गुह्य शास्त्र सिखाया, हे निष्पाप। जो इसे समझता है, वह ज्ञानी होता है और अपना सब उद्देश्य पूरा कर लेता है, अर्जुन।”"),
"16.01": ("श्री भगवान् ने कहा: अभय, हृदय की शुद्धि, ज्ञान और योग में स्थिरता, दान, दम, यज्ञ, शास्त्र-अध्ययन, तपस्या और सरलता,",
         "कृष्ण ने कहा: “निर्भयता, हृदय की शुद्धता, ज्ञान और ध्यान में दृढ़ता, दान, आत्म-संयम, यज्ञ, अध्ययन, तपस्या और ईमानदारी,”"),
"16.02": ("— अहिंसा, सत्य, क्रोध-रहितता, त्याग, शान्ति, निन्दा-रहितता, करुणा, अस्पृहता, कोमलता, लज्जा और स्थिरता —",
         "“— अहिंसा, सत्य, क्रोध से मुक्ति, त्याग, शान्ति, चुगली न करना, करुणा, लोभ-रहितता, कोमलता, विनम्रता और दृढ़ता —”"),
"16.03": ("— तेज, क्षमा, धैर्य, शुद्धता, द्वेष-रहितता और अभिमान-रहितता — ये, हे भारत, दैवी सम्पदा से जन्मे की पहचान हैं।",
         "“— ऊर्जा, धैर्य, दृढ़ता, शुद्धता, और द्वेष तथा अहंकार से मुक्ति — ये दैवी प्रकृति के चिह्न हैं।”"),
"16.04": ("हे पार्थ, दम्भ, दर्प, अभिमान, क्रोध, कठोरता और अज्ञान — ये आसुरी सम्पदा से जन्मे की पहचान हैं।",
         "“दम्भ, अहंकार, घमण्ड, क्रोध, रूखापन और अज्ञान — ये आसुरी प्रकृति के चिह्न हैं।”"),
"16.05": ("दैवी सम्पदा मुक्ति के लिए, आसुरी बन्धन के लिए है — हे पाण्डव, शोक मत कर, क्योंकि तू दैवी सम्पदा लेकर जन्मा है।",
         "“दैवी प्रकृति मुक्त करती है; आसुरी बाँधती है। शोक मत कर, अर्जुन — तू दैवी प्रकृति के साथ जन्मा है।”"),
"16.06": ("इस संसार में प्राणियों की दो सृष्टियाँ हैं — दैवी और आसुरी; दैवी का विस्तार से वर्णन किया गया — हे पार्थ, अब आसुरी का सुन।",
         "“इस संसार में दो प्रकार के प्राणी हैं — दैवी और आसुरी। दैवी का वर्णन मैंने किया; अब आसुरी का सुन।”"),
"16.07": ("आसुरी लोग कर्तव्य और अकर्तव्य को नहीं जानते; उनमें न शुद्धि है, न सदाचार, न सत्य।",
         "“आसुरी लोग क्या करना चाहिए और क्या त्यागना चाहिए — यह नहीं जानते; उनमें न शुद्धता है, न अच्छा आचरण, न सत्य।”"),
"16.08": ("वे कहते हैं: संसार असत्य है, आधार-रहित है, ईश्वर-रहित है — परस्पर संयोग से उत्पन्न, कामना से जन्मा — और क्या?",
         "“वे दावा करते हैं: संसार झूठा है, बिना आधार, बिना ईश्वर — संयोग और इच्छा से उठा हुआ।”"),
"16.09": ("इस दृष्टि को धारण करके, ये अल्प-बुद्धि नष्ट आत्माएँ, जगत् के शत्रु होकर, उसके विनाश के लिए क्रूर कर्म करती हैं।",
         "“इस दृष्टिकोण से, खोई हुई मन्द-बुद्धि आत्माएँ, संसार की शत्रु बनकर, उसे बरबाद करने के लिए निर्दयी काम करती हैं।”"),
"16.10": ("अतृप्त कामना में डूबे, दम्भ, दर्प और अहंकार से भरे, मोह से झूठी दृष्टि रखने वाले, वे अशुद्ध संकल्पों से कर्म करते हैं।",
         "“कभी न मिटने वाले लोभ के दास, घमण्ड और अहंकार से फूले, वे गलत विचारों से चिपककर अशुद्ध मनसा काम करते हैं।”"),
"16.11": ("मृत्यु पर ही समाप्त होने वाली अपार चिन्ताओं में डूबे, कामनाओं के भोग में तत्पर, 'यही सब कुछ है' — ऐसा सोचने वाले —",
         "“मृत्यु पर ही समाप्त होने वाली अनन्त चिन्ताओं से खपकर, भोग में जीने वाले, वे सोचते हैं, 'यही सब कुछ है' —”"),
"16.12": ("— सैकड़ों आशाओं के बन्धनों से बँधे, कामना और क्रोध में डूबे, वे भोग की तृप्ति के लिए अन्यायपूर्ण साधनों से धन अर्जित करते हैं।",
         "“— सैकड़ों आशाओं की रस्सियों से बँधकर, इच्छा और क्रोध में समर्पित, वे अपने सुखों के लिए गलत रास्तों से धन जोड़ते हैं।”"),
"16.13": ("'यह मैंने आज पाया; यह इच्छा मैं पूरी करूँगा; यह धन मेरा है — और और भी मेरा होगा,' वे सोचते हैं —",
         "मन ही मन हिसाब लगाते हैं — 'आज इतना हाथ लगा; वह अरमान भी पूरा कर लूँगा; इतना मेरा हो चुका, और भी होगा।'"),
"16.14": ("'मैंने इस शत्रु को मारा, और दूसरों को भी मारूँगा; मैं स्वामी हूँ, मैं भोक्ता हूँ, मैं सिद्ध, बलवान् और सुखी हूँ,'",
         "“'मैंने उस शत्रु को मारा, और बाकियों को भी मारूँगा; मैं स्वामी, भोगी, सफल, शक्तिशाली और सुखी हूँ,'”"),
"16.15": ("'मैं धनी और उच्च कुल का हूँ; मेरे समान और कौन है? मैं यज्ञ करूँगा, दान दूँगा, आनन्द मनाऊँगा' — इस प्रकार अज्ञान से मोहित होते हैं।",
         "“'मैं धनी और कुलीन हूँ; मेरे बराबर कौन हो सकता है? मैं अर्पण करूँगा, दान दूँगा, आनन्द लूँगा' — इस प्रकार अज्ञानी अपने आपको धोखा देते हैं।”"),
"16.16": ("अनेक विचारों से भ्रमित, मोह के जाल में लिपटे, इन्द्रिय-सुख में समर्पित वे घोर नरक में गिरते हैं।",
         "“अगणित विचारों से टूटकर, भ्रम के जाल में फँसकर, सुख की लत में डूबकर — वे घृणित नरक में गिरते हैं।”"),
"16.17": ("आत्म-श्लाघी, हठी, धन के मद से भरे, वे केवल नाम के लिए, दम्भ से, विधि के अनुसार नहीं, यज्ञ करते हैं।",
         "“आत्म-महत्त्व और हठ से भरे, धन के घमण्ड में माते हुए, वे केवल दिखावे के लिए — ढोंग से, शास्त्र के अनुसार नहीं — यज्ञ करते हैं।”"),
"16.18": ("अहंकार, बल, दर्प, कामना और क्रोध से भरे, अपने और दूसरों के शरीरों में स्थित मुझसे द्वेष रखने वाले ये दुष्ट प्राणी —",
         "“अहंकार, शक्ति, घमण्ड, लोभ और क्रोध से भरकर, अपने और दूसरों के हृदयों में बसे मुझे तुच्छ समझने वाले —”"),
"16.19": ("— इन क्रूर द्वेषियों, नराधमों को, मैं पुनर्जन्म के चक्रों में बार-बार आसुरी योनियों में डालता हूँ।",
         "“— इन क्रूर, घृणा से भरे, सबसे नीच मनुष्यों को मैं पुनर्जन्म के चक्रों में बार-बार आसुरी योनियों में फेंकता हूँ।”"),
"16.20": ("आसुरी योनि में पड़कर, जन्म-जन्म मोहित होकर, कभी मुझे न पाकर, वे निम्नतम अवस्था को प्राप्त होते हैं, हे कुन्तीपुत्र।",
         "“आसुरी योनि में जन्मकर, जीवन-जीवन भ्रम में रहकर, कभी मुझे न पाकर, वे निम्नतम अवस्था में गिरते हैं।”"),
"16.21": ("आत्मा का नाश करने वाला नरक का यह द्वार त्रिविध है: काम, क्रोध और लोभ — इसलिए इन तीनों को त्याग दे।",
         "“नरक की ओर ले जाने वाले और आत्मा को नष्ट करने वाले तीन द्वार हैं: काम, क्रोध और लोभ। तीनों छोड़ दे।”"),
"16.22": ("हे कुन्तीपुत्र, अन्धकार के इन तीन द्वारों से मुक्त होकर, मनुष्य अपने कल्याण के लिए कर्म करता है और परम लक्ष्य को प्राप्त होता है।",
         "“जो इन तीन अन्धकारमय द्वारों से बचता है, अर्जुन, वह अपने कल्याण के लिए काम करता है और सर्वोच्च लक्ष्य तक पहुँचता है।”"),
"16.23": ("जो शास्त्र-विधान को त्यागकर, कामना के आवेग से कर्म करता है — वह न सिद्धि पाता है, न सुख, न परम लक्ष्य।",
         "“जो शास्त्र के नियम की अवहेलना करके मनमानी से काम करता है — उसे न सिद्धि मिलती है, न आनन्द, न परम लक्ष्य।”"),
"16.24": ("इसलिए कर्तव्य-अकर्तव्य के निर्णय में शास्त्र ही तेरा प्रमाण हो; शास्त्र के विधान को जानकर, यहाँ उसी के अनुसार कर्म कर।",
         "“इसलिए अच्छे-बुरे का निर्णय करने में शास्त्र को ही अपना मार्गदर्शक बना; उसकी आज्ञा जानकर, यहाँ उसी के अनुसार काम कर।”"),
"17.01": ("अर्जुन ने कहा: हे कृष्ण, जो शास्त्र-विधान को त्यागकर श्रद्धा से पूजा करते हैं — उनकी अवस्था क्या है? सत्त्व, रज या तम?",
         "अर्जुन पूछते हैं: “जो श्रद्धा से पूजा करते हैं किन्तु शास्त्र के नियमों की अवहेलना करते हैं — उनकी स्थिति क्या है, कृष्ण? वे सात्त्विक, राजस या तामस?”"),
"17.02": ("श्री भगवान् ने कहा: देहधारियों की श्रद्धा त्रिविध होती है, अपने स्वभाव से उत्पन्न — सात्त्विक, राजस और तामस; उसे सुन।",
         "कृष्ण ने कहा: “श्रद्धा तीन प्रकार की होती है, अपनी प्रकृति से जन्मी: सात्त्विक, राजस और तामस। सुन।”"),
"17.03": ("हे भारत, प्रत्येक की श्रद्धा उसके स्वभाव के अनुसार होती है; मनुष्य श्रद्धा से ही बना होता है — जैसी उसकी श्रद्धा, वैसा वह।",
         "“श्रद्धा प्रकृति का अनुसरण करती है, अर्जुन। मनुष्य अपनी श्रद्धा से बनता है — जैसा विश्वास करता है, वैसा बन जाता है।”"),
"17.04": ("सात्त्विक देवताओं की पूजा करते हैं; राजस यक्षों और राक्षसों की; और अन्य — तामस — भूतों और प्रेतों के समूहों की पूजा करते हैं।",
         "“सात्त्विक देवताओं को पूजते हैं; राजस देव-योनियों और राक्षसों को; तामस भूत-प्रेत पूजते हैं।”"),
"17.05": ("शास्त्र द्वारा न बताई गई भयंकर तपस्याएँ करने वाले, दम्भ और अहंकार से भरे, कामना और आसक्ति के बल से प्रेरित पुरुष,",
         "“जो घमण्ड और अहंकार से भरकर, लोभ से चलकर, शास्त्र द्वारा निषिद्ध कठोर तपस्या करते हैं,”"),
"17.06": ("— शरीर के तत्त्वों को और शरीर में बैठे मुझे भी पीड़ा देकर — उन्हें आसुरी संकल्प वाले जान।",
         "देह के तत्त्वों को ही नहीं, भीतर बैठे मुझे भी वे सताते हैं। ऐसे लोगों का इरादा ही आसुरी समझ।"),
"17.07": ("भोजन भी, प्रत्येक को प्रिय, त्रिविध होता है; और यज्ञ, तपस्या तथा दान भी — उनका भेद सुन।",
         "“भोजन, यज्ञ, तपस्या और दान — प्रत्येक के तीन रूप होते हैं, स्वभाव के अनुसार प्रिय। भेद सुन।”"),
"17.08": ("जीवन, शुद्धि, बल, स्वास्थ्य, आनन्द और प्रसन्नता बढ़ाने वाले — रसीले, चिकने, दृढ़ और मन-भावने आहार सात्त्विक को प्रिय होते हैं।",
         "“जीवन, स्पष्टता, बल, स्वास्थ्य, आनन्द और संतोष बढ़ाने वाले — रसदार, कोमल, पुष्टिकर और सुखद — ऐसे भोजन सात्त्विक को प्रिय हैं।”"),
"17.09": ("कड़वे, खट्टे, नमकीन, अति गरम, तीखे, रूखे और जलाने वाले — पीड़ा, शोक और रोग उत्पन्न करने वाले आहार राजस को प्रिय होते हैं।",
         "“कड़वे, खट्टे, नमकीन, प्रचण्ड गरम, तीखे, सूखे और जलन देने वाले — दुःख, शोक और रोग लाने वाले — ऐसे भोजन राजस को प्रिय हैं।”"),
"17.10": ("बासी, बेस्वाद, सड़ा और जूठा भोजन, और अपवित्र बचा हुआ — ऐसा भोजन तामस को प्रिय होता है।",
         "रात का रखा, स्वाद खोया, सड़ता हुआ, किसी का जूठा और गन्दा बचा-खुचा — तमस वाले को यही भाता है।"),
"17.11": ("शास्त्र द्वारा विहित, 'यह अवश्य करना चाहिए' — ऐसा मानने वालों द्वारा फल की इच्छा के बिना किया गया यज्ञ — वह सात्त्विक है।",
         "“शास्त्र के अनुसार, फल की आशा के बिना, 'यह करना ही चाहिए' — इस विश्वास से किया गया यज्ञ — वह सात्त्विक है।”"),
"17.12": ("किन्तु हे भरतश्रेष्ठ, फल की इच्छा से और दिखावे के लिए किया गया यज्ञ — उसे राजस जान।",
         "“किन्तु फल के लिए या दिखाने के लिए किया गया यज्ञ — उसे राजस जानो।”"),
"17.13": ("विधि के बिना, अन्न-दान के बिना, मन्त्र के बिना, दक्षिणा के बिना, श्रद्धा से रहित किया गया यज्ञ — तामस कहा गया है।",
         "“उचित विधि के बिना, अर्पण के बिना, मन्त्र के बिना, दान के बिना और श्रद्धा के बिना किया गया यज्ञ — वह तामस है।”"),
"17.14": ("देवताओं, द्विजों, गुरुओं और ज्ञानियों की पूजा; शौच, आर्जव, ब्रह्मचर्य और अहिंसा — यह शरीर की तपस्या है।",
         "“देवताओं, विद्वानों, गुरुओं और मुनियों का सम्मान; शुद्धता, ईमानदारी, ब्रह्मचर्य और अहिंसा — यह शारीरिक तपस्या है।”"),
"17.15": ("दुःख न पहुँचाने वाली, सत्य, प्रिय और हितकारी वाणी, और नियमित शास्त्र-अध्ययन — यह वाणी की तपस्या है।",
         "“कोमल, सत्य, सुखद और हितकारी वाणी, साथ ही दैनिक शास्त्र-पाठ — यह वाणी की तपस्या है।”"),
"17.16": ("मन की प्रसन्नता, सौम्यता, मौन, आत्म-संयम और भाव-शुद्धि — यह मन की तपस्या कही जाती है।",
         "“शान्त मन, दयालुता, मौन, आत्म-संयम और भीतरी शुद्धता — यह मानसिक तपस्या है।”"),
"17.17": ("यह त्रिविध तपस्या, दृढ़ पुरुषों द्वारा परम श्रद्धा से, फल की इच्छा के बिना की गई — सात्त्विक कही गई है।",
         "“यह त्रिविध साधना, दृढ़ संकल्प वालों द्वारा बड़ी श्रद्धा से, बदले में कुछ न चाहकर की गई — सात्त्विक कहलाती है।”"),
"17.18": ("सम्मान, आदर और पूजा के लिए, और दम्भ से की गई तपस्या — यहाँ राजस कही गई है, अस्थिर और क्षणिक।",
         "“यश, सम्मान और प्रशंसा के लिए, और ढोंग से की गई तप — वह राजस है: अस्थिर और क्षणभंगुर।”"),
"17.19": ("मूर्खतापूर्ण हठ से, आत्म-पीड़न से, या दूसरे को नष्ट करने के लिए की गई तपस्या — तामस कही गई है।",
         "“मूर्ख हठ से, स्वयं को यातना देकर, या दूसरों को हानि पहुँचाने के लिए की गई तप — वह तामस है।”"),
"17.20": ("देना ही चाहिए — इस भाव से, बदले में कुछ न कर सकने वाले को, उचित स्थान और समय पर, योग्य व्यक्ति को दिया गया दान — सात्त्विक माना गया है।",
         "'देना चाहिए' — बस इतने भाव से, ऐसे को जो बदले में कुछ लौटा न सके, सही जगह और सही समय पर, सही पात्र को दिया जाए — वह दान सात्त्विक है।"),
"17.21": ("किन्तु बदले में कुछ अपेक्षा करके, फिर फल चाहकर, या अनिच्छा से दिया गया दान — राजस माना गया है।",
         "“किन्तु कुछ वापस मिलने की आशा से, पुरस्कार चाहकर, या जी न लगाकर दिया गया दान — वह राजस है।”"),
"17.22": ("गलत स्थान और समय पर, अयोग्य व्यक्ति को, बिना आदर के और तिरस्कार के साथ दिया गया दान — तामस कहा गया है।",
         "“गलत समय-स्थान पर, अयोग्य को, बिना सम्मान के या तिरस्कार के साथ दिया गया दान — वह तामस है।”"),
"17.23": ("ॐ तत् सत् — ब्रह्म का यह त्रिविध पद-नाम है; इसी से प्राचीन काल में ब्राह्मण, वेद और यज्ञ विधान किए गए।",
         "“ॐ तत् सत् — ब्रह्म का यह त्रिविध नाम है। इसी से बहुत पहले ब्राह्मण, वेद और यज्ञों की सृष्टि हुई।”"),
"17.24": ("इसलिए, ॐ का उच्चारण करके, शास्त्र द्वारा विहित यज्ञ, दान और तपस्या के कर्म, ब्रह्म-ज्ञाताओं द्वारा सदा आरम्भ किए जाते हैं।",
         "“इसलिए ब्रह्म-ज्ञाता ॐ का उच्चारण करके — शास्त्र के विधान के अनुसार — हर यज्ञ, दान और तपस्या आरम्भ करते हैं।”"),
"17.25": ("फल की इच्छा के बिना, 'तत्' का उच्चारण करके, मुक्ति के खोजियों द्वारा यज्ञ, तपस्या और विविध दान के कर्म किए जाते हैं।",
         "“मुक्ति के खोजी — 'तत्' कहकर, कोई पुरस्कार न चाहकर — यज्ञ, तपस्या और हर प्रकार का दान करते हैं।”"),
"17.26": ("हे पार्थ, 'सत्' शब्द सत्य और सद्भाव के अर्थ में प्रयुक्त होता है, और शुभ कर्मों में भी।",
         "“'सत्' का अर्थ सत्य और सद्भाव है; यह श्रेष्ठ कर्मों में भी प्रयुक्त होता है, अर्जुन।”"),
"17.27": ("यज्ञ, तपस्या और दान में स्थिरता भी 'सत्' कहलाती है; और उसी के लिए किया गया कर्म भी 'सत्' कहलाता है।",
         "यज्ञ में, तप में, दान में टिके रहना — यही 'सत्'। और इन्हीं के लिए किया गया हर काम भी 'सत्'।"),
"17.28": ("हे पार्थ, श्रद्धा के बिना चढ़ाया, दिया, किया या सम्पन्न किया हुआ जो-जो है — वह 'असत्' कहलाता है; यहाँ भी नहीं, परलोक में भी नहीं।",
         "श्रद्धा न हो तो चढ़ावा, दान, तप, कोई भी काम — सब 'असत्'। न यहाँ किसी काम का, न जाने के बाद।"),
"18.01": ("अर्जुन ने कहा: हे महाबाहो, मैं संन्यास का सत्य जानना चाहता हूँ, हे हृषीकेश, और त्याग का भी, और दोनों का भेद, हे केशिनिषूदन।",
         "अर्जुन पूछते हैं: “कृपया संन्यास और त्याग का सत्य बताइए, कृष्ण — और वे कैसे भिन्न हैं।”"),
"18.02": ("श्री भगवान् ने कहा: कामना-पूर्ण कर्मों का त्याग ज्ञानी संन्यास कहते हैं; सब कर्म-फलों का त्याग ज्ञानी त्याग कहते हैं।",
         "कृष्ण ने कहा: “स्वार्थी कर्मों को त्यागना ज्ञानी संन्यास कहते हैं; सब कर्मों के फल को त्यागना वे त्याग कहते हैं।”"),
"18.03": ("कुछ ज्ञानी कर्म को दोषयुक्त समझकर त्याग देने की बात कहते हैं; अन्य यज्ञ, दान और तपस्या को नहीं त्यागने की बात कहते हैं।",
         "“कुछ विचारक कर्म को ही दोषयुक्त और त्याज्य कहते हैं; अन्य कहते हैं यज्ञ, दान और तप कभी नहीं त्यागने चाहिए।”"),
"18.04": ("हे भरतश्रेष्ठ, त्याग के विषय में मेरा निश्चित निष्कर्ष सुन; हे नरश्रेष्ठ, त्याग तीन प्रकार का कहा गया है।",
         "“हे अर्जुन, त्याग पर मेरा स्थिर दृष्टिकोण सुन — क्योंकि त्याग तीन प्रकार का कहा गया है।”"),
"18.05": ("यज्ञ, दान और तपस्या के कर्म नहीं त्यागने चाहिए; उन्हें अवश्य करना चाहिए, क्योंकि वे ज्ञानियों को भी शुद्ध करते हैं।",
         "“यज्ञ, दान और तप कभी नहीं त्यागने चाहिए — वे ज्ञानियों को भी शुद्ध करते हैं और अवश्य करने चाहिए।”"),
"18.06": ("किन्तु हे पार्थ, ये कर्म भी आसक्ति और फल को त्यागकर करने चाहिए — यह मेरा निश्चित और उत्तम विश्वास है।",
         "“फिर भी ये भी बिना आसक्ति और बिना फल की आशा के करने चाहिए — यह मेरा दृढ़ और अन्तिम मत है।”"),
"18.07": ("विहित कर्म का त्याग उचित नहीं है; मोह से उसे त्यागना तामस कहा गया है।",
         "“अपना विहित कर्तव्य त्यागना गलत है — भ्रम से त्यागना तामस है।”"),
"18.08": ("जो दुःख आता है कहकर, शारीरिक कष्ट के भय से कर्म का त्याग करता है — वह राजस त्याग करता है और त्याग का फल नहीं पाता।",
         "“जो काम कठिन या पीड़ादायक है कहकर छोड़ देता है — वह राजस त्याग करता है और उससे कुछ नहीं पाता।”"),
"18.09": ("किन्तु हे अर्जुन, करना ही चाहिए — इस भाव से, आसक्ति और फल को त्यागकर किया गया विहित कर्म — वह सात्त्विक त्याग माना गया है।",
         "“किन्तु कर्तव्य केवल कर्तव्य होने से, बिना आसक्ति और बिना फल की इच्छा के किया गया — वह सात्त्विक त्याग है।”"),
"18.10": ("सत्त्व-युक्त, दृढ़ समझ वाला सात्त्विक त्यागी न अप्रिय कर्म से घृणा करता है, न प्रिय कर्म में आसक्त होता है।",
         "“ज्ञानी और स्पष्ट दृष्टि वाला सात्त्विक त्यागी न तो अप्रिय काम से चिढ़ता है, न प्रिय काम में आसक्त होता है।”"),
"18.11": ("निश्चय ही देहधारी सब कर्मों का पूर्ण त्याग नहीं कर सकता; किन्तु जो कर्म-फल का त्याग करता है, वह सच्चा त्यागी कहलाता है।",
         "देह है तो काम पूरा छूटेगा नहीं। छूट सकता है तो बस नतीजे का मोह — जिसने वह छोड़ा, असली त्यागी वही।"),
"18.12": ("अ-त्यागी को कर्म का त्रिविध फल — प्रिय, अप्रिय और मिश्रित — मृत्यु के बाद मिलता है; त्यागी को कभी नहीं।",
         "“कर्म के तीन फल — अच्छा, बुरा और मिश्रित — मृत्यु के बाद अ-त्यागी को मिलते हैं; त्यागी को कभी नहीं।”"),
"18.13": ("हे महाबाहो, कर्म के अन्त के दर्शन (सांख्य-शास्त्र) में कहे गए सब कर्मों के ये पाँच कारण मुझसे सीख:",
         "“वेदान्त के सांख्य में सिखाए गए सब कर्मों के पाँच कारण मुझसे सीख:”"),
"18.14": ("— आधार, कर्ता, करण, विविध चेष्टाएँ, और पाँचवाँ दैव।",
         "“— शरीर, कर्ता, इन्द्रियाँ, विविध प्रयास, और पाँचवाँ भाग्य।”"),
"18.15": ("मनुष्य शरीर, वाणी या मन से जो-जो कर्म करता है — ठीक या गलत — ये पाँच ही उसके कारण हैं।",
         "हाथ से, ज़बान से, या मन से — आदमी जो भी करे, भला या बुरा, पीछे यही पाँच काम कर रहे होते हैं।"),
"18.16": ("ऐसा होने पर, जो — अपूर्ण समझ से — आत्मा को ही कर्ता देखता है, वह सचमुच नहीं देखता।",
         "“इसलिए, जो — सीमित दृष्टि से — आत्मा को ही कर्ता मानता है, वह ठीक से नहीं देखता।”"),
"18.17": ("जिसका मन अहंकार से रहित है, जिसकी बुद्धि लिप्त नहीं है — वह इन लोकों को मारकर भी नहीं मारता, और न बँधता है।",
         "“जो अहंकार-रहित है, जिसकी बुद्धि निष्कलंक है — इन लोगों को मारकर भी वह कुछ नहीं मारता, और नहीं बँधता।”"),
"18.18": ("ज्ञान, ज्ञेय और ज्ञाता — कर्म की त्रिविध प्रेरणा; करण, कर्म और कर्ता — कर्म का त्रिविध आधार।",
         "काम शुरू कराने वाले तीन: जानकारी, जिसे जानना है, और जानने वाला। काम टिकने के तीन: औज़ार, काम खुद, और करने वाला।"),
"18.19": ("गुणों के भेद से ज्ञान, कर्म और कर्ता त्रिविध कहे गए हैं — गुणों की गणना में उन्हें ऐसे सुन।",
         "“ज्ञान, कर्म और कर्ता — प्रत्येक गुणों के अनुसार तीन प्रकार का कहा गया है; उन्हें पूरा सुन।”"),
"18.20": ("जिससे सब प्राणियों में एक ही अविनाशी तत्त्व दिखता है, विभाजित में अविभाजित — उसे सात्त्विक ज्ञान जान।",
         "रूप अलग-अलग हैं, पर हर जीव में वही एक न मिटने वाली चीज़ है — यह दिख जाए, तो वह समझ सात्त्विक है।"),
"18.21": ("किन्तु जो सब प्राणियों में अनेक और पृथक् प्राणियों को देखता है — उसे राजस ज्ञान जान।",
         "“किन्तु जो सब प्राणियों को अनेक और अलग-अलग देखता है — वह राजस ज्ञान है।”"),
"18.22": ("और जो ज्ञान एक ही कार्य को सब कुछ मानकर चिपकता है, बिना कारण, बिना सत्य, तुच्छ — वह तामस कहा गया है।",
         "“और जो ज्ञान एक छोटे अंश को ही सब मानकर चिपकता है, अतार्किक, असत्य और सतही — वह तामस है।”"),
"18.23": ("विधि के अनुसार, बिना आसक्ति, बिना राग-द्वेष, फल न चाहने वाले द्वारा किया गया कर्म — सात्त्विक कहा गया है।",
         "“कर्तव्य के रूप में, बिना आसक्ति, बिना रुचि-अरुचि, पुरस्कार न चाहने वाले द्वारा किया गया कर्म — वह सात्त्विक है।”"),
"18.24": ("किन्तु बड़े परिश्रम से, कामनाओं की पूर्ति चाहकर, अहंकार से भरकर किया गया कर्म — राजस कहा गया है।",
         "“बड़े तनाव से, इच्छाओं की लालसा करके, आत्म-महत्त्व से भरकर किया गया कर्म — वह राजस है।”"),
"18.25": ("मोह से आरम्भ किया गया, परिणाम, हानि और अपनी क्षमता की परवाह न करने वाला कर्म — तामस कहा गया है।",
         "“भ्रम में आरम्भ किया गया, परिणाम, उससे होने वाली हानि और अपनी शक्ति की उपेक्षा करने वाला कर्म — वह तामस है।”"),
"18.26": ("आसक्ति-रहित, अहंकार-रहित, दृढ़ और उत्साही, सफलता-असफलता से न चलने वाला कर्ता — सात्त्विक कहा गया है।",
         "“आसक्ति-रहित, अहंकार-रहित, स्थिर और ऊर्जावान्, जीत-हार से न छूने वाला कर्ता — वह सात्त्विक है।”"),
"18.27": ("राग से भरा, कर्म-फल का लोभी, लोभी, क्रूर, अशुद्ध, हर्ष-शोक से चलने वाला कर्ता — राजस कहा गया है।",
         "“भावुक, फल का भूखा, लोभी, क्रूर, अशुद्ध, उल्लास-निराशा से डोलने वाला कर्ता — वह राजस है।”"),
"18.28": ("असंयत, असभ्य, हठी, कपटी, दुष्ट, आलसी, उदास और देर करने वाला कर्ता — तामस कहा गया है।",
         "“अनुशासनहीन, रूखा, हठी, ढोंगी, बेईमान, आलसी, उदास और ढीला कर्ता — वह तामस है।”"),
"18.29": ("हे धनंजय, गुणों के अनुसार बुद्धि और धृति का त्रिविध भेद, पूर्ण और पृथक् रूप से सुन।",
         "“अब सुन, अर्जुन, गुणों के अनुसार बुद्धि और संकल्प तीन-तीन प्रकार के कैसे विभाजित होते हैं।”"),
"18.30": ("जो कर्म और अकर्म, शुभ-अशुभ, भय और अभय, बन्धन और मुक्ति को जानता है — वह बुद्धि सात्त्विक है।",
         "“जो समझ करने योग्य और न करने योग्य, अच्छा-बुरा, बन्धन और स्वतंत्रता को पहचानती है — वह सात्त्विक है।”"),
"18.31": ("जो शुभ और अशुभ को गलत रूप से जानती है — वह, हे पार्थ, राजस है।",
         "“जो समझ अच्छे-बुरे को उल्टा समझती है — वह, अर्जुन, राजस है।”"),
"18.32": ("अन्धकार से आच्छादित, अशुभ को शुभ मानने वाली और सब बातों को उल्टा देखने वाली बुद्धि — तामस है।",
         "“अन्धकार में लिपटी, बुरे को अच्छा मानने वाली और सब कुछ उल्टा देखने वाली समझ — वह तामस है।”"),
"18.33": ("जिससे मन, प्राण और इन्द्रियों की क्रियाओं को रोका जाता है — वह दृढ़ धृति, हे पार्थ, सात्त्विक है।",
         "“जिस दृढ़ संकल्प से मन, श्वास और इन्द्रियों को काबू में रखा जाता है — वह, अर्जुन, सात्त्विक है।”"),
"18.34": ("किन्तु जिस धृति से धर्म, काम और अर्थ में, आसक्त होकर और फल चाहकर चिपका जाता है — वह, हे अर्जुन, राजस है।",
         "“किन्तु जो संकल्प धर्म, भोग और धन में, आसक्त होकर और उनके फल का लोभ करके चिपकता है — वह राजस है।”"),
"18.35": ("जिस धृति से मन्द बुद्धि निद्रा, भय, शोक, विषाद और दर्प को नहीं छोड़ पाता — वह तामस है।",
         "“और जिस संकल्प से मूर्ख मनुष्य नींद, भय, शोक, निराशा और घमण्ड को नहीं छोड़ पाता — वह तामस है।”"),
"18.36": ("हे भरतश्रेष्ठ, अब मुझसे त्रिविध सुख सुन — जिसमें अभ्यास से रमा जाता है और दुःख के अन्त तक पहुँचा जाता है।",
         "“अब सुन, अर्जुन, सुख के तीन रूप — वह आनन्द जिसमें अभ्यास से रमा जाता है और पीड़ा के अन्त तक पहुँचा जाता है।”"),
"18.37": ("जो पहले विष के समान और अन्त में अमृत के समान होता है — आत्मा की स्पष्टता से उत्पन्न — वह सात्त्विक सुख कहा गया है।",
         "“जो आनन्द पहले कड़वा किन्तु अन्त में अमृत होता है — आत्म-ज्ञान से उत्पन्न — वह सात्त्विक सुख है।”"),
"18.38": ("इन्द्रिय और विषय के संपर्क से उत्पन्न, पहले अमृत और अन्त में विष के समान होने वाला सुख — राजस कहा गया है।",
         "“इन्द्रियों और विषयों के मिलन से उठने वाला, पहले मीठा किन्तु अन्त में विष-जैसा आनन्द — वह राजस है।”"),
"18.39": ("आरम्भ और अन्त दोनों में आत्मा को मोहित करने वाला, निद्रा, आलस्य और प्रमाद से उत्पन्न सुख — तामस कहा गया है।",
         "“आरम्भ से अन्त तक आत्मा को स्तब्ध करने वाला, नींद, आलस्य और लापरवाही से जन्मा आनन्द — वह तामस है।”"),
"18.40": ("प्रकृति से उत्पन्न इन तीन गुणों से मुक्त — पृथ्वी पर कोई नहीं है, न स्वर्ग के देवताओं में।",
         "“पृथ्वी पर कोई नहीं — स्वर्ग के देवता भी नहीं — प्रकृति के इन तीन गुणों से मुक्त है।”"),
"18.41": ("हे परंतप, ब्राह्मण, क्षत्रिय, वैश्य और शूद्र के कर्तव्य अपने स्वभाव से उत्पन्न गुणों के अनुसार विभक्त हैं।",
         "“चार वर्गों — पुरोहित, योद्धा, व्यापारी, श्रमिक — के कर्तव्य उनकी अपनी प्रकृति के गुणों से निर्धारित होते हैं।”"),
"18.42": ("शान्ति, दम, तप, शौच, क्षान्ति, आर्जव, ज्ञान, विज्ञान और आस्तिक्य — स्वभाव से उत्पन्न ब्राह्मण का कर्तव्य।",
         "“शान्ति, आत्म-संयम, तप, शुद्धता, धैर्य, ईमानदारी, ज्ञान, विवेक और श्रद्धा — ये ब्राह्मण के स्वाभाविक कर्तव्य हैं।”"),
"18.43": ("शौर्य, तेज, धृति, दाक्ष्य, युद्ध में न भागना, दान और ईश्वर-भाव — स्वभाव से उत्पन्न क्षत्रिय का कर्तव्य।",
         "“साहस, तेज, दृढ़ता, निपुणता, रण में न हटना, उदारता और नेतृत्व — ये योद्धा के स्वाभाविक कर्तव्य हैं।”"),
"18.44": ("कृषि, गो-रक्षा और वाणिज्य — स्वभाव से उत्पन्न वैश्य का कर्तव्य; और सेवा — शूद्र का कर्तव्य।",
         "“खेती, गोपालन और व्यापार वैश्य का स्वाभाविक काम; सेवा शूद्र का।”"),
"18.45": ("अपने कर्तव्य में लगा हुआ मनुष्य सिद्धि को प्राप्त होता है — सुन, अपने कर्म में रमने वाला कैसे सिद्ध होता है।",
         "अपने ही हिस्से के काम में लगे रहने से आदमी सिद्धि तक पहुँचता है। कैसे पहुँचता है, अब सुन।"),
"18.46": ("जिससे यह सब व्याप्त है, सब प्राणियों का स्रोत — उसकी पूजा अपने कर्तव्य द्वारा करके, मनुष्य सिद्धि को प्राप्त होता है।",
         "“अपना कर्तव्य करते हुए व्यक्ति उस एक की पूजा करता है जिससे सब प्राणी उठते हैं और जिससे सब व्याप्त है — और इस प्रकार सिद्धि तक पहुँचता है।”"),
"18.47": ("अपना धर्म, यद्यपि दोषयुक्त, पराए सुसम्पन्न धर्म से अच्छा है; अपने स्वभाव से उत्पन्न कर्म करने से मनुष्य पाप नहीं करता।",
         "“अपना कर्तव्य त्रुटिपूर्ण हो तो भी दूसरे के पूर्ण किए गए कर्तव्य से अच्छा है। अपनी प्रकृति से जन्मा कर्म करने से कोई पाप नहीं लगता।”"),
"18.48": ("हे कुन्तीपुत्र, अपना स्वाभाविक कर्म, यद्यपि दोषयुक्त है, त्यागना नहीं चाहिए; क्योंकि सब आरम्भ दोष से आच्छादित हैं, जैसे अग्नि धूम से।",
         "“अपनी प्रकृति से जन्मा काम, त्रुटि होते हुए भी, कभी मत छोड़ो — सब परियोजनाएँ दोष से रँगी हैं, जैसे अग्नि धुएँ से।”"),
"18.49": ("आसक्ति-रहित, आत्म-जित, इच्छा-रहित व्यक्ति संन्यास द्वारा कर्म-रहितता की परम सिद्धि प्राप्त करता है।",
         "“आसक्ति-रहित, आत्म-विजयी, लोभ-रहित व्यक्ति त्याग द्वारा कर्म-रहितता की सर्वोच्च सिद्धि तक पहुँचता है।”"),
"18.50": ("हे कुन्तीपुत्र, यह सिद्धि प्राप्त करने वाला कैसे ब्रह्म तक पहुँचता है — ज्ञान की वह परम अवस्था — मुझसे सीख।",
         "“हे अर्जुन, इस सिद्धि तक पहुँचा व्यक्ति कैसे ब्रह्म की ओर जाता है — ज्ञान की सर्वोच्च अवस्था — मुझसे सुन।”"),
"18.51": ("शुद्ध बुद्धि से युक्त, धैर्य से आत्मा को दृढ़ करके, शब्द आदि विषयों को त्यागकर, राग-द्वेष को छोड़कर,",
         "“शुद्ध मन से, आत्मा को दृढ़ रखकर, शब्द और दूसरे इन्द्रिय-विषयों से हटकर, रुचि-अरुचि छोड़कर,”"),
"18.52": ("— एकान्त में रहकर, थोड़ा खाकर, वाणी, शरीर और मन को वश में करके, सदा ध्यान और चिन्तन में लगकर,",
         "“— अलग रहकर, कम खाकर, वाणी, शरीर और मन पर विजय पाकर, सदा ध्यान में तल्लीन होकर,”"),
"18.53": ("— अहंकार, बल, दर्प, काम, क्रोध और ममता को त्यागकर, शान्त, 'मेरा' कहना न छोड़ने वाला — ऐसा व्यक्ति ब्रह्म का योग्य हो जाता है।",
         "“— अहंकार, शक्ति, घमण्ड, लोभ, क्रोध और मोह छोड़कर, शान्त, 'मेरा' न रखने वाला — ऐसा व्यक्ति ब्रह्म के योग्य होता है।”"),
"18.54": ("ब्रह्मभूत, प्रसन्न आत्मा होकर, वह न शोक करता है न इच्छा; सब प्राणियों में समान होकर, वह मुझ में परम भक्ति प्राप्त करता है।",
         "“ब्रह्म से एक, शान्त हृदय, वह न शोक करता है न लालसा; सबको समान देखकर, वह मुझ में सर्वोच्च भक्ति जीतता है।”"),
"18.55": ("उस भक्ति से वह मुझे सचमुच जानता है — मैं क्या और कौन हूँ; और मुझे सचमुच जानकर, वह तुरन्त मुझ में प्रवेश करता है।",
         "इसी प्रेम से वह मुझे सचमुच पहचान लेता है — कि मैं कौन हूँ, कैसा हूँ। और पहचानते ही सीधे मुझ में घुल जाता है।"),
"18.56": ("सब कर्म सदा करते हुए, मेरी शरण लेकर, वह मेरी कृपा से नित्य, अविनाशी अवस्था को प्राप्त होता है।",
         "“सदा सब कर्म करते हुए, मुझ में विश्राम करके, वह मेरी कृपा से नित्य, अपरिवर्तनीय अवस्था तक पहुँचता है।”"),
"18.57": ("विचार से सब कर्म मुझ में अर्पण करके, मुझे परम मानकर, विवेक-योग का सहारा लेकर, मन मुझ में स्थिर कर।",
         "“मन में ही हर कर्म मुझे अर्पण कर, मुझे सर्वोच्च मान, और ज्ञान-योग पर भरोसा करके, हृदय मुझ पर रख।”"),
"18.58": ("मन मुझ में होने से तू मेरी कृपा से सब कठिनाइयाँ पार करेगा; किन्तु अहंकार से न सुनेगा तो तू नष्ट हो जाएगा।",
         "मन मुझ पर टिका रहा तो मेरी कृपा से हर अड़चन पार हो जाएगी। पर अकड़ में आकर अनसुना किया, तो तू कहीं का न रहेगा।"),
"18.59": ("यदि अहंकार के आधार पर 'मैं युद्ध नहीं करूँगा' — ऐसा सोचता है, तो तेरा संकल्प व्यर्थ है; तेरी प्रकृति ही तुझे बाध्य करेगी।",
         "“यदि अहंकार से 'मैं नहीं लड़ूँगा' सोचता है, तो वह संकल्प निरर्थक है; तेरी अपनी प्रकृति ही तुझे ज़बरदस्ती कराएगी।”"),
"18.60": ("हे कुन्तीपुत्र, अपनी प्रकृति से उत्पन्न कर्म से बँधकर, जो तू नहीं करना चाहता — वही तू असहाय होकर करेगा।",
         "“अपनी प्रकृति से जन्मे कर्म से बँधकर, अर्जुन, तू न चाहते हुए भी, असहाय होकर, जो नहीं करना चाहता वही करेगा।”"),
"18.61": ("हे अर्जुन, भगवान् सब प्राणियों के हृदय में रहते हैं, अपनी माया से सब प्राणियों को, मानो यन्त्र पर चढ़े हुए, घुमाते हैं।",
         "“भगवान् हर प्राणी के हृदय में रहते हैं, अपनी शक्ति के चक्र पर सब प्राणियों को, यन्त्र पर चढ़ी पुतलियों की तरह, घुमाते हैं।”"),
"18.62": ("हे भारत, सम्पूर्ण भाव से केवल उन्हीं की शरण ले; उनकी कृपा से तू परम शान्ति और नित्य धाम पाएगा।",
         "“पूरे हृदय से, अर्जुन, केवल उन्हीं की शरण ले; उनकी कृपा से तुझे परम शान्ति और नित्य घर मिलेगा।”"),
"18.63": ("इस प्रकार मैंने तुझसे रहस्य से भी गुह्य यह ज्ञान कहा; इस पर पूरा विचार कर, और जैसा चाहे वैसा कर।",
         "“इसलिए मैंने तुझे यह ज्ञान सिखाया — गुह्य से भी गुह्य। इस पर पूरा मनन कर — फिर जो चाहे वही कर।”"),
"18.64": ("फिर सुन मेरा परम वचन — सबसे गुह्य: तू मुझे अत्यन्त प्रिय है, इसलिए मैं तेरे हित के लिए बोलता हूँ।",
         "“अब सुन मेरा अन्तिम, सबसे छिपा हुआ वचन: तू मुझे बहुत प्रिय है, इसलिए मैं यह तेरे हित के लिए कहता हूँ।”"),
"18.65": ("मन मुझ में लगा, मेरा भक्त बन, मुझे अर्पण कर, मुझे प्रणाम कर — तू निश्चय मुझे प्राप्त होगा; मैं सत्य वचन देता हूँ, क्योंकि तू मुझे प्रिय है।",
         "मन मुझ पर टिका, प्रेम मुझसे, अर्पण मुझे, सिर मेरे आगे — तू मुझ तक पहुँचेगा ही। यह मेरा वादा है, क्योंकि तू मुझे प्यारा है।"),
"18.66": ("सब धर्मों को त्यागकर केवल मेरी शरण आ; मैं तुझे सब पापों से मुक्त करूँगा — शोक मत कर।",
         "“दूसरे सब मार्ग छोड़कर केवल मुझ में समर्पण कर। मैं तुझे सब पापों से मुक्त करूँगा — शोक मत कर।”"),
"18.67": ("यह बात न तपस्या-रहित को कहनी चाहिए, न श्रद्धा-रहित को, न सेवा न करने वाले को, न मेरी निन्दा करने वाले को।",
         "“यह शिक्षा अनुशासन-रहित को, श्रद्धा-रहित को, इच्छुक न होने वाले को या मुझसे घृणा करने वाले को मत दो।”"),
"18.68": ("जो मेरे भक्तों को परम भक्ति से यह परम गुह्य सिखाता है — मुझे अपना उच्चतम प्रेम देकर — वह मुझे प्राप्त होगा।",
         "“जो मेरे भक्तों को, मुझसे प्रेम के कारण, यह परम गुह्य बात सिखाता है — मुझे अपनी गहरी भक्ति देकर — वह मुझ तक पहुँचेगा।”"),
"18.69": ("उससे बढ़कर मेरी सेवा करने वाला मनुष्यों में कोई नहीं; और पृथ्वी पर उससे मुझे प्रिय कोई नहीं होगा।",
         "“ऐसे शिक्षक से बढ़कर मेरी सेवा कोई नहीं करता; पृथ्वी पर उससे मुझे प्रिय कोई नहीं होगा।”"),
"18.70": ("और जो हमारे इस पवित्र संवाद का अध्ययन करता है — उससे मैं ज्ञान-यज्ञ से पूजित होता हूँ; यह मेरा विश्वास है।",
         "“और जो हमारे इस पवित्र संवाद को पढ़ता है — उसने मुझे ज्ञान के यज्ञ से पूजा है, मैं ऐसा मानता हूँ।”"),
"18.71": ("श्रद्धा से, बिना निन्दा के, इसे सुनने वाला मनुष्य भी — मुक्त होकर — सत्पुरुषों के शुभ लोकों को प्राप्त होता है।",
         "“जो श्रद्धा से और बिना ईर्ष्या के केवल सुनता है — वह भी मुक्त होकर सज्जनों के आनन्दमय लोकों तक पहुँचता है।”"),
"18.72": ("हे पार्थ, क्या यह तूने एकाग्र मन से सुना? क्या अज्ञान का मोह नष्ट हुआ?",
         "“क्या तूने यह पूरे ध्यान से सुना, अर्जुन? क्या अज्ञान का भ्रम दूर हुआ?”"),
"18.73": ("अर्जुन ने कहा: मेरा मोह नष्ट हो गया; हे अच्युत, आपकी कृपा से मुझे स्मृति मिली; मैं स्थिर हूँ, मेरा सन्देह गया — मैं आपकी आज्ञा का पालन करूँगा।",
         "अर्जुन उत्तर देते हैं: “मेरा भ्रम दूर हुआ; हे अपरिवर्तनीय प्रभु, आपकी कृपा से मुझे स्मृति मिली। मैं स्थिर हूँ, सन्देह-रहित — मैं आपकी आज्ञा का पालन करूँगा।”"),
"18.74": ("संजय ने कहा: इस प्रकार मैंने वासुदेव और महात्मा पार्थ का अद्भुत, रोमांचक संवाद सुना।",
         "संजय वर्णन करते हैं: “इस प्रकार मैंने वासुदेव और उदार पार्थ की अद्भुत, रोंगटे खड़े करने वाली वार्ता सुनी।”"),
"18.75": ("व्यास की कृपा से मैंने यह परम, सबसे गुह्य योग — योगेश्वर कृष्ण स्वयं बोले — सुना।",
         "व्यास की मेहरबानी से यह सबसे गहरा भेद मेरे कानों तक आया — कहा खुद योगेश्वर कृष्ण ने।"),
"18.76": ("हे राजन्, केशव और अर्जुन के इस अद्भुत, पवित्र संवाद को बार-बार स्मरण करके, मैं बार-बार हर्षित होता हूँ।",
         "हे राजन्, कृष्ण और अर्जुन की वह अनोखी पावन बातचीत जब-जब याद आती है, मेरा मन फिर-फिर खिल उठता है।"),
"18.77": ("और हे राजन्, हरि के उस अत्यन्त अद्भुत रूप को बार-बार स्मरण करके, मेरा आश्चर्य बड़ा है — और मैं बार-बार हर्षित होता हूँ।",
         "“और हे राजा, प्रभु के उस सबसे अद्भुत रूप को बार-बार स्मरण करके, मैं आश्चर्य और आनन्द से भर जाता हूँ।”"),
"18.78": ("जहाँ योगेश्वर कृष्ण और धनुर्धारी पार्थ हैं — वहाँ समृद्धि, विजय, वैभव और निश्चित नीति हैं; यह मेरा विश्वास है।",
         "“जहाँ योग के स्वामी कृष्ण और धनुर्धारी अर्जुन खड़े हैं — वहाँ भाग्य, विजय, समृद्धि और अटल ज्ञान होता है। यह मेरा दृढ़ विश्वास है।”"),
}
